FUNCTION functional_amount1(amount       IN NUMBER,
                           currency_code IN VARCHAR2,
                           exchange_rate IN NUMBER,
                           precision     IN NUMBER,
                           min_acc_unit  IN NUMBER) RETURN NUMBER IS

 CURSOR curr_info (cc FND_CURRENCIES.CURRENCY_CODE%TYPE) IS
 SELECT PRECISION,
        MINIMUM_ACCOUNTABLE_UNIT,
        CURRENCY_CODE
 FROM   FND_CURRENCIES
 WHERE  CURRENCY_CODE = cc;

 curr curr_info%ROWTYPE;
 loc_amount NUMBER;
 invalid_params EXCEPTION;

BEGIN

   /*--------------------------------------------------------------------*
    | Validate Parameters                                                |
    *--------------------------------------------------------------------*/

   IF (((currency_code IS NULL) AND
      (precision IS NULL) AND
      (min_acc_unit IS NULL)) OR
      (amount IS NULL) ) THEN
      
      BEGIN
         RAISE invalid_params;
      END;
    END IF;

    /*--------------------------------------------------------------------*
     | Only get currency info from database if not supplied as parameters |
     *--------------------------------------------------------------------*/

   IF ((precision IS NULL) AND (min_acc_unit IS NULL)) THEN
      BEGIN
         OPEN curr_info(currency_code);
         FETCH curr_info INTO curr;
         CLOSE curr_info;

         IF (curr.currency_code IS NULL) THEN
              RAISE invalid_params;
         END IF;
      END;
   ELSE
      BEGIN
         curr.precision := precision;
         curr.minimum_accountable_unit := min_acc_unit;
      END;
   END IF;

   loc_amount := amount * NVL(exchange_rate, 1);

   /*-----------------*
    | Round correctly |
    *-----------------*/

   IF (curr.minimum_accountable_unit IS NULL) THEN
      RETURN( ROUND(loc_amount, curr.precision));
   ELSE
      RETURN( ROUND((loc_amount / curr.minimum_accountable_unit)) *
              curr.minimum_accountable_unit);
   END IF;

EXCEPTION
WHEN OTHERS THEN
   -- Bug 2191876
   IF curr_info%ISOPEN THEN
      CLOSE curr_info;
   END IF;

   RAISE;

END functional_amount1;

PROCEDURE print_fix (
            fix_column   IN VARCHAR2,
            old_value    IN VARCHAR2,
            fix_value    IN VARCHAR2
        ) IS

 l_fix   VARCHAR2(4000) := '';

BEGIN
		
   IF ( upper(fix_column) = upper('gl_date') ) THEN
      g_gl_date_new := old_value;
      g_gl_date_current := fix_value;
   ELSIF ( upper(fix_column) = upper('amount_due_remaining') ) THEN
      g_amount_due_rem_new := old_value;
  	  g_amount_due_rem_current := fix_value;
   ELSIF ( upper(fix_column) = upper('amount_line_items_original') ) THEN
      g_amount_line_itemso_new := old_value;
      g_amount_line_itemso_current := fix_value;
   ELSIF ( upper(fix_column) = upper('freight_original') ) THEN
      g_freight_original_new := old_value;
      g_freight_original_current := fix_value;
   ELSIF ( upper(fix_column) = upper('tax_original') ) THEN
      g_tax_original_new := old_value;
  	  g_tax_original_current := fix_value;
   ELSIF ( upper(fix_column) = upper('amount_credited') ) THEN
      g_amount_credited_new := old_value;
      g_amount_credited_current := fix_value;
   ELSIF ( upper(fix_column) = upper('amount_applied') ) THEN
      g_amount_applied_new := old_value;
      g_amount_applied_current := fix_value;
   ELSIF ( upper(fix_column) = upper('amount_adjusted') ) THEN
      g_amount_adjusted_new := old_value;
   	  g_amount_adjusted_current := fix_value;
   ELSIF ( upper(fix_column) = upper('receivables_charges_charged') ) THEN
      g_receivables_charges_new := old_value;
      g_receivables_charges_current := fix_value;
   ELSIF ( upper(fix_column) = upper('acctd_amount_due_remaining') ) THEN
      g_acctd_amnt_due_rem_new := old_value;
	  g_acctd_amnt_due_rem_current := fix_value;
   ELSIF ( upper(fix_column) = upper('status') ) THEN
      g_status_new := old_value;
      g_status_current := fix_value;
   ELSIF ( upper(fix_column) = upper('gl_date_closed') ) THEN
      g_gl_date_closed_new := TO_DATE(old_value,'YYYY/MM/DD');
      g_gl_date_closed_current := TO_DATE(fix_value,'YYYY/MM/DD');
   ELSIF ( upper(fix_column) = upper('actual_date_closed') ) THEN
      g_actual_date_closed_new := TO_DATE(old_value,'YYYY/MM/DD');
      g_actual_date_closed_current := TO_DATE(fix_value,'YYYY/MM/DD');
   ELSIF ( upper(fix_column) = upper('amount_line_items_remaining') ) THEN
      g_amount_line_itemsr_new := old_value;
      g_amount_line_itemsr_current := fix_value;
   ELSIF ( upper(fix_column) = upper('tax_remaining') ) THEN
      g_tax_remaining_new := old_value;
	  g_tax_remaining_current := fix_value;
   ELSIF ( upper(fix_column) = upper('freight_remaining') ) THEN
      g_freight_remaining_new := old_value;
	  g_freight_remaining_current := fix_value;
   ELSIF ( upper(fix_column) = upper('amount_due_original') ) THEN
      g_amount_due_orig_new := old_value;
	  g_amount_due_orig_current := fix_value;				
   ELSIF ( upper(fix_column) = upper('receivables_charges_remaining') ) THEN
      g_rec_charges_r_new := old_value;
	  g_rec_charges_r_current := fix_value;
   END IF;
EXCEPTION
WHEN OTHERS THEN
   print_log('XXOD ERROR :' || sqlerrm);
END;


-- Main code begins
BEGIN
   print_log('inside pay_120_prc');
   
   --check accounting flag
   begin
      select distinct ctt.accounting_affect_flag 
      into   l_accounting_affect_flag
      from   ra_customer_trx_all ct,
             ra_cust_trx_types_all ctt,
   	         ra_cust_trx_line_gl_dist_all gld
      where  ct.customer_trx_id = p_customer_trx_id
      and	 ct.cust_trx_type_id = ctt.cust_trx_type_id
      and	 ctt.type in ('INV', 'DM', 'CM', 'CB')
      and	 gld.customer_trx_id = ct.customer_trx_id
      and	 ct.complete_flag = 'Y'
      and	 gld.customer_trx_id = ct.customer_trx_id
      and	 gld.account_class = 'REC'
      and    ct.org_id = ctt.org_id 
      and	 gld.account_set_flag = 'N';
   exception 
   when others then
      l_accounting_affect_flag := 'N';
   end;

   if (l_accounting_affect_flag = 'Y') THEN

      select COUNT(payment_schedule_id)
      into l_payment_schedule_cnt
      from ar_payment_schedules_all
      where customer_trx_id = p_customer_trx_id;
 
      if (l_payment_schedule_cnt = 1) then 
 
         select payment_schedule_id
         into l_payment_schedule_id
         from ar_payment_schedules_all
         where customer_trx_id = p_customer_trx_id;
 
         ps_id_low := l_payment_schedule_id;
         ps_id_high := l_payment_schedule_id;
 
         mo_global.init('AR');
         mo_global.set_policy_context('S',l_org_id);
	
	     -- add to replace ARP_GLOBAL.functional_currency
         SELECT sob.currency_code
         INTO   l_functional_currency
         FROM   ar_system_parameters sp,
                gl_sets_of_books sob
         WHERE  sob.set_of_books_id = sp.set_of_books_id;

         l_counter := 0;
	
         OPEN v_ps FOR
         SELECT *
         FROM   ar_payment_schedules ps
         WHERE  SIGN(ps.payment_schedule_id) <> -1
         AND    ps.payment_schedule_id BETWEEN ps_id_low AND ps_id_high
         AND    class <> 'BR';
	  
         LOOP
            FETCH v_ps into rps;
            print_log('XXOD Debug inside child loop' );
            EXIT WHEN v_ps%NOTFOUND;
	  
            l_counter := l_counter+1;

            ps_id := rps.payment_schedule_id;

            select amount_due_original, amount_due_remaining, acctd_amount_due_remaining, gl_date, gl_Date_closed, actual_date_closed, status, amount_applied, amount_credited, amount_adjusted, 
                   amount_line_items_original, amount_line_items_remaining, tax_original, tax_remaining, freight_original, freight_remaining, receivables_charges_charged, receivables_charges_remaining
	        into   l_amt_due_orig_new, l_amt_due_rem_new, l_acctd_amt_due_rem_new, l_gl_Date, l_gl_Date_closed_new, l_Actual_date_closed_new, l_status_new, l_amt_applied_new, l_amt_credited_new, l_amt_adjusted_new, 
                   l_amt_line_items_orig_new, l_amt_line_items_rem_new, l_tax_orig_new, l_tax_rem_new, l_freight_orig_new, l_freight_rem_new, l_rec_Charges_charged_new, l_rec_charges_rem_new
 	        from   ar_payment_Schedules
 	        where payment_Schedule_id=  rps.payment_schedule_id;
	  
            -- Transaction case
            l_trx_num := rps.trx_number;
            l_ct_id := rps.customer_trx_id;
            l_class := SUBSTR(rps.class,1,4);

            -- Split Terms
            IF (rps.term_id IS NOT NULL )  THEN
               SELECT count(*) 
               INTO   l_split_term_exists
               FROM   ra_terms_lines tl
               WHERE  rps.term_id = tl.term_id ;

               --Bug 3074038 detect incomplete term lines for split terms
               SELECT sum(tl.relative_amount), 
                      rt.name
               INTO   l_sum_term_amount,
                      l_term_name
               FROM   ra_terms rt, 
                      ra_terms_lines tl
               WHERE  rt.term_id = tl.term_id
               AND    rps.term_id = tl.term_id
               GROUP BY rt.name;
            END IF;

            -- Bug 3074038 alert user when term lines are incomplete
            IF l_sum_term_amount <> 100 THEN
               print_log('TRX15:Payment term :'||l_term_name||' is a split term' );
               print_log('TRX15:Split percentages should sum to 100 but is: '||l_sum_term_amount);
               print_log('This payment term should be corrected!');
               GOTO NEXT_PAY; 
            END IF;

            IF l_split_term_exists > 1  THEN  
               l_actual_acctd_amt_due := l_acctd_amt_due_rem_new;
               l_actual_amount_due_orig := l_amt_due_orig_new;
            ELSE 
            -- ensure that the related customer_trx_id is complete and receivables
            -- row has the same gl date as the payment schedule
            -- Verify if PS.amount_due_original is correct
               BEGIN
                  SELECT ctlgd.gl_date,
                         ctlgd.acctd_amount,
                         ctlgd.amount
                  INTO   l_gl_date,
                         l_actual_acctd_amt_due,
                         l_actual_amount_due_orig
                  FROM   ra_cust_trx_line_gl_dist ctlgd,
                         ra_customer_trx trx,
                         ra_cust_trx_types ctt,
                         gl_code_combinations gcc
                  WHERE  trx.customer_trx_id = rps.customer_trx_id
                  AND    trx.complete_flag   = 'Y'
                  AND    ctt.cust_trx_type_id = trx.cust_trx_type_id
                  AND    ctt.type in ('INV', 'DEP', 'GUAR', 'CM', 'DM', 'CB')
                  AND    gcc.code_combination_id = ctlgd.code_combination_id
                  AND    ctlgd.customer_trx_id = trx.customer_trx_id
                  AND    ctlgd.account_class = 'REC'
                  AND    ctlgd.latest_rec_flag = 'Y';

                  IF l_gl_date <> l_gl_date_new THEN
                     print_log('TRX10:rps.gl_date is          : '||l_gl_date_new);
                     print_log('TRX10:should be ctlgd.gl_date : '|| l_gl_date);
	  	             print_fix('gl_date',TO_CHAR(l_gl_date_new,'YYYY/MM/DD'),TO_CHAR(l_gl_date,'YYYY/MM/DD'));
                  END IF;
                
                  IF l_amt_due_orig_new <> l_actual_amount_due_orig THEN
                     print_log('TRX00:rps.amount_due_original is : '|| l_amt_due_orig_new);
                     print_log('TRX00:Should be                  : '|| l_actual_amount_due_orig );
				     print_fix('amount_due_original',l_amt_due_orig_new,l_actual_amount_due_orig);
                  END IF;
               EXCEPTION
               WHEN OTHERS THEN 
                  print_log( 'TRX12:error joining to trx:'||sqlerrm );
                  GOTO NEXT_PAY ;
               END;

               -- Get line amount
               -- Note that CHARGES works just like the LINE line_type (etrm)

               /* Bug-4014624  - Added l_rec_charges_amount */
               BEGIN 

                  SELECT NVL(SUM( DECODE(line.line_type,
                                        'LINE', line.extended_amount,
                                        'CB'  , line.extended_amount, 0)),0),
                         NVL(SUM( DECODE(line.line_type,
                                        'FREIGHT',line.extended_amount, 0)),0),
                         NVL(SUM( DECODE(line.line_type,
                                        'TAX',line.extended_amount, 0)),0),
                         NVL(SUM( DECODE(line.line_type,
                                        'CHARGES',line.extended_amount, 0)),0)
                  INTO   l_line_amount,
                         l_freight_amount,
                         l_tax_amount,
                         l_rec_charges_amount  
                  FROM   ra_customer_trx_lines line,
                         ra_customer_trx       trx 
                  WHERE  trx.customer_trx_id = rps.customer_trx_id
                  AND    trx.customer_trx_id = line.customer_trx_id
                  AND    trx.complete_flag = 'Y' ;

			      print_log('XXOD Debug l_amt_line_items_orig_new : '||l_amt_line_items_orig_new );
				  print_log('XXOD Debug l_line_amount : '||l_line_amount );
                  
                  IF l_amt_line_items_orig_new <> l_line_amount THEN
                     print_log('TRX00: amount_line_items_original is : '||l_amt_line_items_orig_new );
                     print_log('TRX00: Should be                     : '||l_line_amount );
				     print_fix('amount_line_items_original',l_amt_line_items_orig_new,l_line_amount);
                  END IF;

                  IF NVL(l_freight_orig_new,0) <> l_freight_amount THEN
                     print_log('TRX00: freight_original is : '||l_freight_orig_new);                  
                     print_log('TRX00: Should be           : '||l_freight_amount );
				     print_fix('freight_original',l_freight_orig_new,l_freight_amount);
                  END IF;

                  IF NVL(l_tax_orig_new,0) <> l_tax_amount THEN
                     print_log('TRX00: tax_original is : '||l_tax_orig_new );
                     print_log('TRX00: Should be       : '||l_tax_amount );
				     print_fix('tax_original',l_tax_orig_new,l_tax_amount);
                  END IF;

               EXCEPTION
               WHEN OTHERS THEN 
                  print_log( 'TRX99: error joining to trx_line : '||sqlerrm);
               END;

            END IF; --  End Split terms
    
            -- Get CM application amount, if any
            SELECT nvl(MAX(gl_date),to_date('1952/12/31', 'YYYY/MM/DD')),
                   nvl(MIN(gl_date),to_date('4712/12/31', 'YYYY/MM/DD')),
                   NVL(SUM(amount_applied),0),
                   nvl(MAX(apply_date),to_date('1952/12/31','YYYY/MM/DD')),
                   NVL(SUM(DECODE(application_type,'CM', decode(status,'APP',nvl(line_applied,0),'ACTIVITY',nvl(amount_applied,0)), 0)),0),
                   NVL(SUM(DECODE(application_type,'CM', nvl(freight_applied,0), 0)),0),
                   NVL(SUM(DECODE(application_type,'CM', nvl(tax_applied,0), 0)),0),
                   NVL(SUM(DECODE(application_type,'CM', nvl(receivables_charges_applied,0), 0)),0),
                   nvl(sum(DECODE(application_type,'CM',decode(status,'APP',0,'ACTIVITY',nvl(amount_applied,0)),0)),0)
            INTO   l_max_gl_date_applied_from,
                   l_min_gl_date_applied_from,
                   l_amount_applied_from,
                   l_max_apply_date_from,
                   l_line_applied_cm_amount,
                   l_freight_applied_cm_amount,
                   l_tax_applied_cm_amount,
                   l_rec_charges_cm_amount,
                   l_amount_credited_cm_amount
            FROM  ar_receivable_applications
            WHERE payment_schedule_id = rps.payment_schedule_id
            AND   status in ('APP','ACTIVITY')                                --added ACTIVITY for CM refund application, Bug8226015
            AND   NVL(confirmed_flag,'Y') = 'Y';

            -- Get total receipt and/or CM applications  on this Invoice 
            SELECT nvl(MAX(gl_date),to_date('1952/12/31', 'YYYY/MM/DD')),
                   nvl(MIN(gl_date),to_date('4712/12/31', 'YYYY/MM/DD')),
                   NVL(SUM(amount_applied),0) + 
                       NVL(SUM(nvl(earned_discount_taken,0)),0) + 
                       NVL(SUM(nvl(unearned_discount_taken,0)),0),
                   nvl(MAX(apply_date),to_date('1952/12/31', 'YYYY/MM/DD')),
                   NVL(SUM(DECODE(application_type,'CM',nvl(line_applied,0), 0)), 0),
                   NVL(SUM(DECODE(application_type,'CM',nvl(freight_applied,0), 0)), 0),
                   NVL(SUM(DECODE(application_type,'CM',nvl(tax_applied,0), 0)), 0),
                   NVL(SUM(DECODE(application_type,'CM',amount_applied, 0)), 0),
                   NVL(SUM(DECODE(application_type,'CASH',nvl(line_applied,0), 0)), 0),
                   NVL(SUM(DECODE(application_type,'CASH',nvl(freight_applied,0), 0)), 0),
                   NVL(SUM(DECODE(application_type,'CASH',nvl(tax_applied,0), 0)), 0),
                   NVL(SUM(DECODE(application_type,'CASH',amount_applied, 0)), 0),
                   NVL(SUM(DECODE(application_type,'CASH',( NVL(earned_discount_taken,0) + 
                                                            NVL(unearned_discount_taken,0) ), 0)), 0),
                   NVL(SUM(DECODE(application_type,'CM',nvl(receivables_charges_applied,0), 0)), 0),
                   NVL(SUM(DECODE(application_type,'CASH',nvl(receivables_charges_applied,0), 0)), 0),
                   NVL(SUM(DECODE(application_type,'CASH',( NVL(line_ediscounted,0) +
                                                            NVL(line_uediscounted,0) ), 0)), 0),
                   NVL(SUM(DECODE(application_type,'CASH',( NVL(freight_ediscounted,0) +
                                                            NVL(freight_uediscounted,0) ), 0)), 0),
                   NVL(SUM(DECODE(application_type,'CASH',( NVL(tax_ediscounted,0) +
                                                            NVL(tax_uediscounted,0) ), 0)), 0),
                   NVL(SUM(DECODE(application_type,'CASH',( NVL(charges_ediscounted,0) +
                                                            NVL(charges_uediscounted,0) ), 0)), 0)
            INTO   l_max_gl_date_applied_to,
                   l_min_gl_date_applied_to,
                   l_amount_applied_to,
                   l_max_apply_date_to,
                   l_line_credited_amount,
                   l_freight_credited_amount,
                   l_tax_credited_amount,
                   l_amount_credited,
                   l_line_applied_amount,
                   l_freight_applied_amount,
                   l_tax_applied_amount,
                   l_amount_applied ,
                   l_discount_amount,
                   l_rec_charges_credited_amount,
                   l_rec_charges_applied_amount,
                   l_line_discount_amount,
                   l_freight_discount_amount,
                   l_tax_discount_amount,
                   l_charges_discount_amount
            FROM   ar_receivable_applications
            WHERE  applied_payment_schedule_id = rps.payment_schedule_id
            AND    status = 'APP'
            AND    NVL(confirmed_flag,'Y') = 'Y';

            -- Amount applied = amount applied by (receipts) + CMs Application
            l_amount_applied := l_amount_applied + l_amount_applied_from * -1;

            IF nvl(l_amt_credited_new,0) <> (-l_amount_credited + l_amount_credited_cm_amount)  THEN
               print_log('TRX1:amt_credited <> recapp.amount_credited ');
               print_log('TRX1:'||l_amt_credited_new ||' <> '||(-l_amount_credited + l_amount_credited_cm_amount)); 
               print_fix('amount_credited',l_amt_credited_new,(-l_amount_credited + l_amount_credited_cm_amount));
            END IF;

            IF nvl(l_amt_applied_new,0) <> l_amount_applied  THEN
               print_log('TRX2:amount_applied <> recapp.amount_applied ');
               print_log('TRX2:'||l_amt_applied_new ||' <> '||l_amount_applied ); 
               print_fix('amount_applied',nvl(l_amt_applied_new,0),l_amount_applied);			  
            END IF;

            -- Get all adjustments on this Invoice or CM
            -- Bug-4014624 - Get the full adjusted value also
            SELECT nvl(MAX(gl_date),to_date('1952/12/31', 'YYYY/MM/DD')),
                   nvl(MIN(gl_date),to_date('4712/12/31', 'YYYY/MM/DD')),
                   NVL(SUM(amount),0),
                   NVL(MAX(NVL(apply_date,to_date('1952/12/31', 'YYYY/MM/DD')
                              )
                           ), to_date('1952/12/31', 'YYYY/MM/DD')) ,
                   NVL(SUM(NVL(line_adjusted,0)),0),
                   NVL(SUM(NVL(freight_adjusted,0)),0),
                   NVL(SUM(NVL(tax_adjusted,0)),0),
		           NVL(SUM(NVL(receivables_charges_adjusted,0)),0),
                   NVL(SUM(DECODE(type,'CHARGES',NVL(receivables_charges_adjusted,0),0)),0)
            INTO   l_max_gl_date_adj,
                   l_min_gl_date_adj,
                   l_amount_adj,
                   l_max_apply_date_adj,
                   l_line_adjusted_amount,
                   l_freight_adjusted_amount,
                   l_tax_adjusted_amount,
                   l_rec_charges_adjusted_amount,           /* Bug-4014624 Full adjustment value    */
		           l_rec_charges_adj                        /* Bug-4014624 Charges adjustment alone */
            FROM   ar_adjustments
            WHERE  payment_schedule_id = rps.payment_schedule_id
            AND    status = 'A';

            IF l_amt_adjusted_new <> l_amount_adj THEN
               print_log('TRX4:ps.amount_adjusted is : '||l_amt_adjusted_new);
               print_log('TRX4:Should be             : '||l_amount_adj );
		       print_fix('amount_adjusted',l_amt_adjusted_new,l_amount_adj);	         
            END IF;

            -- Bug-4014624 -- Added below code to update the receivables_charges_charged
            IF l_rec_Charges_charged_new <> (l_rec_charges_amount + l_rec_charges_adj) THEN
               print_log('TRX4:ps.receivables_charges_charged is : '||l_rec_Charges_charged_new);
               print_log('TRX4:Should be             : '||(l_rec_charges_amount + l_rec_charges_adj));
			   print_fix('receivables_charges_charged',l_rec_Charges_charged_new,(l_rec_charges_amount + l_rec_charges_adj));
            END IF;

            -- Bug 3103448 added discount amounts to each remaining amount calculation  
            IF l_split_term_exists = 1 THEN 
               l_amount_line_items_remaining :=  l_line_amount
                                            + l_line_adjusted_amount
                                            + l_line_applied_cm_amount
                                            + (l_line_credited_amount * -1 )
                                            - l_line_discount_amount
                                            - l_line_applied_amount ;

               l_freight_remaining :=  l_freight_amount
                                  + l_freight_applied_cm_amount
                                  + l_freight_adjusted_amount
                                  + (l_freight_credited_amount * -1 )
                                  - l_freight_applied_amount
                                  - l_freight_discount_amount ;

               l_tax_remaining :=  l_tax_amount
                              + l_tax_applied_cm_amount
                              + l_tax_adjusted_amount
                              + (l_tax_credited_amount * -1 )
                              - l_tax_applied_amount
                              - l_tax_discount_amount ;

              -- Bug3403892 added l_rec_Charges_charged_new as rps.receivables_charges_charged
              -- Bug-4014624 - Replace l_rec_Charges_charged_new with l_rec_charges_amount
              l_rec_charges_remaining :=  l_rec_charges_amount
                                      + l_rec_charges_cm_amount
                                      + l_rec_charges_adjusted_amount
                                      + (l_rec_charges_credited_amount * -1 )
                                      - l_rec_charges_applied_amount
                                      - l_charges_discount_amount ;
            END IF;

            l_total_amount_due_remaining :=   l_actual_amount_due_orig 
                                            - l_amount_applied_to
                                            + l_amount_applied_from
                                            + l_amount_adj ;

            IF l_amt_due_rem_new <> l_total_amount_due_remaining THEN   
               print_log('TRX3:ps.amount_due_remaining is : '||l_amt_due_rem_new);
               print_log('TRX3:Should be                  : '||l_total_amount_due_remaining  );
			   print_fix('amount_due_remaining',l_amt_due_rem_new,l_total_amount_due_remaining);   
            END IF;

            -- Bug 3121371 added handling for null amount for REC distribution

            IF l_actual_amount_due_orig IS NULL THEN
               print_log('TRX14:REC amount in gl_dist is NULL'); 
               print_log('TRX14:rps.amount_due_original is : '|| l_amt_due_orig_new );
               print_log('TRX14:Correct REC amount and rerun pay.sql'); 
               GOTO NEXT_PAY;
            ELSE
               l_functional_amount := functional_amount1(l_total_amount_due_remaining ,
                                         --ARP_GLOBAL.functional_currency,
                                         l_functional_currency,
                                         rps.exchange_rate,
                                         NULL,
                                         NULL ) ;
            END IF;

            IF l_actual_amount_due_orig = l_total_amount_due_remaining THEN 
               IF l_acctd_amt_due_rem_new <> l_actual_acctd_amt_due THEN
                  print_log('TRX11: rps.acctd_amount_due_remaining is : '|| l_acctd_amt_due_rem_new );
                  print_log('TRX11: Should be                         : '|| l_actual_acctd_amt_due );
				  print_fix('acctd_amount_due_remaining',l_acctd_amt_due_rem_new,l_actual_acctd_amt_due);   
               END IF;
            ELSE 
               IF l_acctd_amt_due_rem_new <> l_functional_amount THEN
                  print_log('TRX11: rps.acctd_amount_due_remaining is : '|| l_acctd_amt_due_rem_new );
                  print_log('TRX11: Should be                         : '|| l_functional_amount );
				  print_fix('acctd_amount_due_remaining',l_acctd_amt_due_rem_new,l_functional_amount);     
               END IF;
            END IF;

            IF l_total_amount_due_remaining = 0 THEN
               -- status check
               IF l_status_new = 'OP' THEN 
                  print_log( 'TRX5:adr=0 but status=OP' );
				  print_fix('status','OP','CL');	     
               END IF;

               l_greatest_gl_date := GREATEST(l_max_gl_date_applied_from,
                                          l_max_gl_date_applied_to,
                                          l_max_gl_date_adj);

               l_greatest_apply_date := GREATEST(l_max_apply_date_from,
                                             l_max_apply_date_to,
                                             l_max_apply_date_adj ); 
 
               IF (l_actual_amount_due_orig = 0 ) THEN
                  IF l_amt_due_rem_new <> 0 THEN
                     print_log('TRX6:ado=0 but adr<>0');
                  END IF;
               ELSE 
                  -- gl_date_closed check 
                  IF l_gl_date_closed_new <> l_greatest_gl_date THEN
                     print_log('TRX7:ps.gl_date_closed  is : '||l_gl_date_closed_new );
                     print_log('TRX7:Should be             : '||l_greatest_gl_date );
			  	     print_fix('gl_date_closed',TO_CHAR(l_gl_date_closed_new,'YYYY/MM/DD'),TO_CHAR(l_greatest_gl_date,'YYYY/MM/DD'));
                  END IF;

                  -- actual_date_closed check
                  IF trunc(l_actual_date_closed_new) <> trunc(l_greatest_apply_date) THEN
                     print_log('TRX91:ps.actual_date_closed  is : '||l_actual_date_closed_new );
                     print_log('TRX91:Should be                 : '||l_greatest_apply_date );
				     print_fix('actual_date_closed',TO_CHAR(l_actual_date_closed_new,'YYYY/MM/DD'),TO_CHAR(l_greatest_apply_date,'YYYY/MM/DD'));
                  END IF;
                   
                  -- amount_line_items_remaining check 
                  IF l_split_term_exists = 1 THEN
                     -- BUG 2446759: check for wash condition where line+tax+freight+charge = zero

                     IF (l_amt_line_items_rem_new + l_tax_rem_new + l_freight_rem_new + l_rec_charges_rem_new) <> 0 THEN
 
                        IF l_amt_line_items_rem_new <> 0 THEN
                           print_log('TRX00: amount_due_remaining is 0 but amount_line_items_remaining is : '||l_amt_line_items_rem_new);

                           IF l_amount_line_items_remaining  <> 0 THEN
                              print_log('Calculated amount_line_items_remaining is not 0 : '||l_amount_line_items_remaining);
                           END IF;   
                           print_fix('amount_line_items_remaining', l_amount_line_items_remaining , 0);
                        END IF ;

                        -- tax_remaining check 
                        IF l_tax_rem_new <> 0 THEN
                           print_log('TRX00: amount_due_remaining is 0 but tax_remaining is : '||l_tax_rem_new);
                
                           IF l_tax_remaining <> 0 THEN
                              print_log('Calculated tax_remaining is not 0 : '||l_tax_remaining);
                           END IF;
                           print_fix('tax_remaining', l_tax_remaining , 0); 
                        END IF;

                        -- freight_remaining check
                        IF l_freight_rem_new <> 0 THEN
                           print_log('TRX00: amount_due_remaining is 0 but freight_remaining is : '||l_freight_rem_new );
                           IF l_freight_remaining <> 0 THEN                             
                              print_log('Calculated freight_remaining is not 0 : '||l_freight_remaining );
                           END IF;
  					       print_fix('freight_remaining', l_freight_remaining , 0);
                        END IF ;

                        --  receivables_charges_remaining check
                        IF l_rec_charges_rem_new <> 0 THEN
                           print_log('TRX00: amount_due_remaining is 0 but charges_remaining is : '||l_rec_charges_rem_new );

                           IF l_rec_charges_remaining <> 0 THEN
                              print_log('Calculated charges_remaining is not 0 : '||l_rec_charges_remaining );
                           END IF;
                           print_fix('receivables_charges_remaining', l_rec_charges_remaining , 0);
                        END IF ;
                     END IF ;
                  END IF;
               END IF;
            ELSE -- if total_amount_due_remaining <> 0 
               -- status check
               IF l_status_new = 'CL' THEN
                  print_log( 'TRX8:adr<>0 but status=CL' );
			      print_fix('status', l_status_new , 'OP');
               END IF;

               -- gl_date_closed check
               IF l_gl_date_closed_new <> TO_DATE('4712/12/31', 'YYYY/MM/DD' ) THEN
                  print_log('TRX9:rps.gl_date_closed is : '||l_gl_date_closed_new );
                  print_log('TRX9:Should be             : 31-DEC-4712 ');
                  print_fix('gl_date_closed',TO_CHAR(l_gl_date_closed_new,'YYYY/MM/DD'),'TO_DATE(''4712/12/31'', ''YYYY/MM/DD'')');
               END IF;

               -- actual_date_closed check
               IF trunc(l_actual_date_closed_new) <> TO_DATE('4712/12/31', 'YYYY/MM/DD' ) THEN
                  print_log('TRX92:rps.actual_date_closed is : '||l_actual_date_closed_new );
                  print_log('TRX92:Should be                 : 31-DEC-4712 ');
			      print_fix('actual_date_closed',TO_CHAR(l_actual_date_closed_new,'YYYY/MM/DD'),'TO_DATE(''4712/12/31'', ''YYYY/MM/DD'')');  
               END IF;

               -- amount_line_items_remaining check
               IF l_split_Term_exists = 1 THEN

                  IF l_amt_line_items_rem_new <> l_amount_line_items_remaining THEN
                     print_log('TRX00 : amount_line_items_remaining is : '|| l_amt_line_items_rem_new );
                     print_log('TRX00 : Should be                      : '||l_amount_line_items_remaining );
                    print_fix('amount_line_items_remaining',l_amt_line_items_rem_new,l_amount_line_items_remaining); 
                  END IF;

                  -- tax_remaining check
                  IF NVL(l_tax_rem_new,0) <> l_tax_remaining THEN
                     print_log('TRX00: tax_remaining is : '|| l_tax_rem_new);
                     print_log('TRX00: Should be        : '|| l_tax_remaining );
				     print_fix('tax_remaining',l_tax_rem_new,l_tax_remaining); 
                  END IF;

                  -- freight_remaining check
                  IF NVL(l_freight_rem_new,0) <> l_freight_remaining THEN
                     print_log('TRX00: freight_remaining is : '|| l_freight_rem_new);
                     print_log('TRX00: Should be            : '|| l_freight_remaining );
			         print_fix('freight_remaining',l_freight_rem_new,l_freight_remaining);
                  END IF;

                  -- charges_remaining check
                  IF NVL(l_rec_charges_rem_new,0) <> l_rec_charges_remaining THEN
                     print_log('TRX00: charges_remaining is : '|| l_rec_charges_rem_new);
                     print_log('TRX00: Should be            : '|| l_rec_charges_remaining );
			         print_fix('receivables_charges_remaining',l_rec_charges_rem_new,l_rec_charges_remaining);
                  END IF;
              END IF;     
           END IF;
         
           l_least_gl_date := LEAST( l_min_gl_date_applied_from,         
                                   l_min_gl_date_applied_to,
                                   l_min_gl_date_adj );            

	  
           l_ct_id := NULL;
           l_trx_num := NULL;
           l_class  := NULL ;

           <<NEXT_PAY>>
	       IF ps_id IS NULL THEN
              NULL;
           END IF;
           
         END LOOP;
         CLOSE v_ps;
      END IF; -- (l_payment_schedule_cnt = 1)
   END IF; -- (l_accounting_affect_flag ='Y')
 
EXCEPTION 
WHEN Others THEN
   --g_sql_tokens('##$$PAY_120_FIX_TRX_SCRIPT$$##') := 'Error in PROCEDURE PAY_120_PRC '||sqlcode||'-'||sqlerrm;
   print_log('Error in PROCEDURE PAY_120_PRC'||SQLCODE||'-'||SQLERRM);
END pay_120_prc;



-------------------------
-- Recommended Patches
-------------------------

FUNCTION check_rec_patches_1 RETURN VARCHAR2 IS
  /* Signature AR_GEN_RECOMMENDED_PATCHES */
  l_col_rows   COL_LIST_TBL := col_list_tbl(); -- Row values
  l_rel_rows   COL_LIST_TBL := col_list_tbl(); -- Row release
  l_hdr        VARCHAR_TBL  := varchar_tbl(); -- Column headings
  l_app_date   DATE;         -- Patch applied date
  l_extra_info HASH_TBL_4K;  -- Extra information
  l_step       VARCHAR2(10);
  l_sig        SIGNATURE_REC;
  l_rel        VARCHAR2(3);
  l_rows       NUMBER := 0;

  CURSOR get_app_date(p_ptch VARCHAR2, p_rel VARCHAR2) IS
   SELECT min(Last_Update_Date) as date_applied
    FROM Ad_Bugs Adb
    WHERE Adb.Bug_Number like p_ptch
    AND ad_patch.is_patch_applied(p_rel, -1, adb.bug_number)!='NOT_APPLIED';

BEGIN

    print_log('Processing recommended patches signature: AR_GEN_RECOMMENDED_PATCHES (check_rec_patches_1) "Recommended Patches" (version 12)');

  -- Column headings
  l_step := '10';
  l_hdr.extend(5);
  l_hdr(1) := 'Patch';
  l_hdr(2) := 'Applied';
  l_hdr(3) := 'Date';
  l_hdr(4) := 'Name';
  l_hdr(5) := 'Note';
  l_col_rows.extend(5);
  l_rel_rows.extend(1);

IF substr(g_rep_info('Apps Version'),1,4) = '12.1' THEN
   l_rel := 'R12';

   l_rows := l_rows + 1;
   l_rel_rows(1)(l_rows) := l_rel;
   l_col_rows(1)(l_rows) := '22471504';
   l_col_rows(2)(l_rows) := 'No';
   l_col_rows(3)(l_rows) := NULL;
   l_col_rows(4)(l_rows) := 'R12.1: Receivables Recommended Patch Collection (AR RPC), February 2016';
   l_col_rows(5)(l_rows) := '[2102716.1]';

   l_rows := l_rows + 1;
   l_rel_rows(1)(l_rows) := l_rel;
   l_col_rows(1)(l_rows) := '22468218';
   l_col_rows(2)(l_rows) := 'No';
   l_col_rows(3)(l_rows) := NULL;
   l_col_rows(4)(l_rows) := 'R12.1: Subledger Accounting Recommended Patch Collection (SLA RPC), February 2016';
   l_col_rows(5)(l_rows) := '[1481222.1]';

   l_rows := l_rows + 1;
   l_rel_rows(1)(l_rows) := l_rel;
   l_col_rows(1)(l_rows) := '22458196';
   l_col_rows(2)(l_rows) := 'No';
   l_col_rows(3)(l_rows) := NULL;
   l_col_rows(4)(l_rows) := 'R12.1: E-Business Tax Reporting Ledger Cumulative Patch Collection (ZX), Feb 2016';
   l_col_rows(5)(l_rows) := '[1481235.1]';

   l_rows := l_rows + 1;
   l_rel_rows(1)(l_rows) := l_rel;
   l_col_rows(1)(l_rows) := '22453253';
   l_col_rows(2)(l_rows) := 'No';
   l_col_rows(3)(l_rows) := NULL;
   l_col_rows(4)(l_rows) := 'R12.1: E-Business Tax Recommended Patch Collection (ZX RPC), Feb 2016';
   l_col_rows(5)(l_rows) := '[1481235.1]';

   l_rows := l_rows + 1;
   l_rel_rows(1)(l_rows) := l_rel;
   l_col_rows(1)(l_rows) := '21340722';
   l_col_rows(2)(l_rows) := 'No';
   l_col_rows(3)(l_rows) := NULL;
   l_col_rows(4)(l_rows) := 'R12.1: Subledger Accounting Recommended Patch Collection (SLA RPC), August 2015';
   l_col_rows(5)(l_rows) := '[1481222.1]';

   l_rows := l_rows + 1;
   l_rel_rows(1)(l_rows) := l_rel;
   l_col_rows(1)(l_rows) := '8302889';
   l_col_rows(2)(l_rows) := 'No';
   l_col_rows(3)(l_rows) := NULL;
   l_col_rows(4)(l_rows) := 'R12.1:Rollup Patch for Brazilian Bank Collection';
   l_col_rows(5)(l_rows) := NULL;

END IF;

   l_extra_info('##SHOW_SQL##'):= 'Y';

   l_sig.sigrepo_id := '2932';
   l_sig.title := 'Recommended Patches';
   l_sig.fail_condition := '[Applied] = [No]';
   l_sig.problem_descr := 'You have recommended patch(es) not applied to this environment.  Please expand the list above for the details.';
   l_sig.solution := 'Please review the list above and schedule to apply any unappplied patches as soon as possible.

For the most current recommendations, use the Patch Wizard or the Updates & Patches Tab in My Oracle Support.<br>
Further guidance can be found in the following documents:<br>
<ul>
<li>[11086538/KA747] How to Find EBS Patches and EBS Technology Patches</li>
<li>[976188/KB739927] R11i / R12 : Patch Wizard Utility</li>
<li>[10940175/KA580] Patch Wizard FAQ</li>
</ul>
Best Practice: Always ensure that you are on the latest code with all recommended patches applied. This will help avoid known issues, prevent potential data corruption and provide the latest features and functionality. Having a proactive patching plan and periodic proactive patching process in place are the best ways to stay current.';
   l_sig.success_msg := '';
   l_sig.print_condition := 'FAILURE';
   l_sig.fail_type := 'W';
   l_sig.print_sql_output := 'Y';
   l_sig.limit_rows := 'N';
   l_sig.extra_info := l_extra_info;
   l_sig.include_in_xml :='P';
   l_sig.version := '12';

   -- if snapshot is old, add message to the solution
   IF nvl(g_snap_days, 10) > 30 THEN
       l_sig.solution := l_sig.solution || '<br><br><b>ADADMIN</b>: Maintain Snapshot Information was executed more than 30 days ago.<br>It is recommended that AD Utilities (Adadmin) "Maintain Snapshot Information" is run periodically as key tools (Patch Wizard, ADPatch,etc) rely on this information being accurate and up-to-date.';
   END IF;

  -- Check if applied
  get_current_time(g_query_start_time);
  FOR i in 1..l_rows loop
    l_step := '40';
    OPEN get_app_date(l_col_rows(1)(i),l_rel_rows(1)(i));
    FETCH get_app_date INTO l_app_date;
    CLOSE get_app_date;
    l_col_rows(1)(i) := '{'||l_col_rows(1)(i)||'}';
    IF l_app_date is not null THEN
      l_step := '50';
      l_col_rows(2)(i) := 'Yes';
      l_col_rows(3)(i) := to_char(l_app_date);
    END IF;
  END LOOP;
  g_query_elapsed := stop_timer(g_query_start_time);
  debug(' Rows fetched: '||to_char(l_rows));

  -- Register
  l_step := '60';
  g_signatures('AR_GEN_RECOMMENDED_PATCHES') := l_sig;

  --Render
  l_step := '70';
  RETURN process_signature_results(
    'AR_GEN_RECOMMENDED_PATCHES',     -- sig ID
    l_sig,                              -- signature information
    l_col_rows,                         -- data
    l_hdr);                             -- headers

EXCEPTION WHEN OTHERS THEN
  print_log('Error in check_rec_patches_1 at step '||l_step);
  raise;
END check_rec_patches_1;




