----------------------------------------------------------------
--- Validate Parameters                                      ---
----------------------------------------------------------------
PROCEDURE validate_parameters(
            p_user_name                    IN VARCHAR2    DEFAULT NULL
           ,p_resp_id                      IN NUMBER      DEFAULT NULL
           ,p_customer_trx_id              IN VARCHAR2    DEFAULT NULL
           ,p_includeGL                    IN VARCHAR2    DEFAULT 'Y'
           ,p_apps_check                   IN VARCHAR2    DEFAULT 'N'
           ,p_max_output_rows              IN NUMBER      DEFAULT 5000
           ,p_debug_mode                   IN VARCHAR2    DEFAULT 'Y')

IS

  l_revision                  VARCHAR2(25);
  l_date_char                 VARCHAR2(30);
  l_instance                  VARCHAR2(255);
  l_apps_version              VARCHAR2(255);
  l_host                      VARCHAR2(255);
  l_full_hostname             VARCHAR2(255);
  l_key                       VARCHAR2(255);
  l_system_function_var       VARCHAR2(2000);
  l_exists_val                VARCHAR2(2000);
  l_index                     NUMBER:=1;
  l_dbversion                 VARCHAR2(255);
  l_db_name                   VARCHAR2(255);
  l_step                      VARCHAR2(10);
  invalid_parameters EXCEPTION;
  invalid_escape EXCEPTION;

----------------------------------------------------------------
-- Analyzer-specific code: Validation Declarations            --
----------------------------------------------------------------






BEGIN

  l_step := '1';

  print_log(analyzer_title || ' Log File');
  print_log('***************************************************************');

  -- Create global hash for parameters. Numbers required for the output order
debug('begin populate parameters hash table');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'User Name';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_user_name,'DISPLAY_BOTH_25_PCNT_WORD');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Responsibility ID';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_resp_id,'NO_MASK');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Customer Trx Id';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_customer_trx_id,'NO_MASK');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Include GL';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_includeGL,'NO_MASK');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Include Apps Check';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_apps_check,'NO_MASK');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Maximum Rows to Display';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_max_output_rows,'NO_MASK');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Debug Mode';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_debug_mode,'NO_MASK');
debug('end populate parameters hash table');



  l_key := g_parameters.first;
  -- Print parameters to the log
  print_log(chr(10)||'Parameter Values before validation:');
  print_log('---------------------------');

  FOR i IN 1..g_parameters.COUNT LOOP
    print_log(to_char(i) || '. ' || g_parameters(i).pname || ': ' || g_parameters(i).pvalue);
  END LOOP;
  print_log('---------------------------');

  BEGIN

    SELECT max(release_name) INTO l_apps_version
    FROM fnd_product_groups;

    begin
        -- Try to get version using new 19c method
        execute immediate 'select instance_name, host_name, version_full, sys_context(''USERENV'',''DB_NAME'') FROM v$instance'
            into l_instance, l_host, l_dbversion, l_db_name;
    exception when others then
        -- Get version using old method
        SELECT instance_name, host_name, version, sys_context('USERENV','DB_NAME')
        INTO l_instance, l_host, l_dbversion, l_db_name
        FROM v$instance;
    end;
    l_host := nvl(l_host, sys_context('USERENV','SERVER_HOST'));
    l_instance := nvl(l_instance, sys_context('USERENV','INSTANCE_NAME'));

  EXCEPTION WHEN OTHERS THEN
    print_log('Error in validate_parameters gathering instance information: '
      ||sqlerrm);
    raise;
  END;

  l_step := '2';
  BEGIN
    SELECT distinct domain
    INTO l_full_hostname
    FROM (SELECT db_domain AS domain
            FROM fnd_databases
          UNION ALL
          SELECT domain AS domain
          FROM fnd_nodes) domains WHERE domains.domain IS NOT NULL and rownum = 1;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
          l_full_hostname := NULL;
        WHEN OTHERS    THEN
          print_log('Error in validate_parameters gathering instance information: '
          ||sqlerrm);
    END;

  l_step := '3';
-- Revision and date values can be populated by RCS
  l_revision := rtrim(replace('$Revision: 200.73  $','$',''));
  l_revision := ltrim(replace(l_revision,'Revision:',''));
  l_date_char := rtrim(replace('$Date: 2026/01/29 05:27:30 $','$',''));
  l_date_char := ltrim(replace(l_date_char,'Date:',''));
  l_date_char := to_char(to_date(l_date_char,'YYYY/MM/DD HH24:MI:SS'),'DD-MON-YYYY');

  l_step := '4';
-- Create global hash for mapping internal result codes (E, W, S, I) to user friendly result codes (error, warning, successful, information)
  g_result('E') := 'error';
  g_result('W') := 'warning';
  g_result('S') := 'success';
  g_result('I') := 'info';

  l_step := '5';
-- Create global hash for report information
-- Do not report host details (EBSAF-274); reverted by EBSAF-293
  g_rep_info('Host') := regexp_substr(l_host, '^[^.]+');
  -- the host name might already be fully qualified, need to check if it includes the domain before appending it
  IF (l_host LIKE '%.%') THEN
       g_rep_info('FullHost') := l_host;
  ELSE
       g_rep_info('FullHost') := l_host || '.' || l_full_hostname;
  END IF;
  l_step := '6';
  g_rep_info('Instance') := l_instance;
  g_rep_info('DB Name') := l_db_name;
  g_rep_info('DB Version') := l_dbversion;
  g_rep_info('Apps Version') := l_apps_version;
  g_rep_info('File Name') := 'ar_trx_analyzer.sql';
  g_rep_info('File Version') := l_revision;
  g_rep_info('Framework Version') := RTRIM(g_framework_version, ' ');
  g_rep_info('Execution Date') := to_char(sysdate,'DD-MON-YYYY HH24:MI:SS');
  g_rep_info('Description') := ('The ' || analyzer_title || ' <a href="' || g_cmos_km_url || g_analyzer_doc_id||'" target="_blank">(Note '||g_analyzer_doc_id||')</a> is a self-service health-check script that reviews the overall footprint, analyzes current configurations and settings for the environment and provides feedback and recommendations on best practices. Your application data is not altered in any way when you run this analyzer.');

  l_step := '7';
  IF (g_is_concurrent) THEN
     populate_user_details();
  END IF;

  ------------------------------------------------------------------------------
  -- NOTE: Add code here for validation to the parameters of your diagnostic
  ------------------------------------------------------------------------------
  l_step := '8';


  g_max_output_rows := nvl(p_max_output_rows,20);
  g_debug_mode := nvl(p_debug_mode, 'Y');

debug('begin parameter validation: p_user_name');
IF p_user_name IS NULL THEN
   print_error('INVALID ARGUMENT: Parameter User Name is required.');
   raise invalid_parameters;
END IF;
IF p_user_name IS NOT NULL THEN
BEGIN
SELECT USER_NAME
INTO l_exists_val
FROM FND_USER
WHERE USER_NAME = p_user_name
 AND user_name = nvl(FND_GLOBAL.USER_NAME, user_name)
 and rownum < 2;
EXCEPTION
   WHEN NO_DATA_FOUND THEN
   print_error('INVALID ARGUMENT: Error: Invalid user name.');
   raise invalid_parameters;
   WHEN OTHERS THEN
   print_error('INVALID ARGUMENT: Validation query for p_user_name failed with '||sqlerrm||'.');
   raise invalid_parameters;
END;
END IF;
debug('end parameter validation: p_user_name');

debug('begin parameter validation: p_resp_id');
IF p_resp_id IS NULL THEN
   print_error('INVALID ARGUMENT: Parameter Responsibility ID is required.');
   raise invalid_parameters;
END IF;
IF p_resp_id IS NOT NULL THEN
BEGIN
SELECT RESP.RESPONSIBILITY_ID
INTO l_exists_val
FROM FND_RESPONSIBILITY_VL RESP, FND_USER_RESP_GROUPS RG
WHERE RESP.RESPONSIBILITY_ID = p_resp_id
 AND rg.user_id = decode(FND_GLOBAL.USER_ID, -1, rg.user_id, FND_GLOBAL.USER_ID)
and rg.responsibility_id = resp.responsibility_id
and nvl(rg.end_date, sysdate) >= sysdate
 and rownum < 2;
EXCEPTION
   WHEN NO_DATA_FOUND THEN
   print_error('INVALID ARGUMENT: Error: Invalid responsibility name.');
   raise invalid_parameters;
   WHEN OTHERS THEN
   print_error('INVALID ARGUMENT: Validation query for p_resp_id failed with '||sqlerrm||'.');
   raise invalid_parameters;
END;
END IF;
debug('end parameter validation: p_resp_id');

debug('begin parameter validation: p_customer_trx_id');
IF p_customer_trx_id IS NULL THEN
   print_error('INVALID ARGUMENT: Parameter Customer Trx Id is required.');
   raise invalid_parameters;
END IF;
IF p_customer_trx_id IS NOT NULL THEN
BEGIN
SELECT TRX.CUSTOMER_TRX_ID
INTO l_exists_val
FROM RA_CUSTOMER_TRX_ALL TRX, HR_OPERATING_UNITS O
WHERE TRX.CUSTOMER_TRX_ID = p_customer_trx_id
 AND trx.org_id = o.organization_id
and (mo_global.is_mo_init_done = 'N' or mo_global.check_access(o.organization_id) = 'Y')


 and rownum < 2;
EXCEPTION
   WHEN NO_DATA_FOUND THEN
   print_error('INVALID ARGUMENT: Invalid Transaction Number.');
   raise invalid_parameters;
   WHEN OTHERS THEN
   print_error('INVALID ARGUMENT: Validation query for p_customer_trx_id failed with '||sqlerrm||'.');
   raise invalid_parameters;
END;
END IF;
debug('end parameter validation: p_customer_trx_id');

debug('begin parameter validation: p_includeGL');
IF p_includeGL IS NULL THEN
   print_error('INVALID ARGUMENT: Parameter Include GL is required.');
   raise invalid_parameters;
END IF;
IF p_includeGL IS NOT NULL AND p_includeGL NOT IN ( 'N','Y') THEN
   print_error('INVALID ARGUMENT: Invalid Include GL value. Valid values are Y or N.');
   raise invalid_parameters;
END IF;
debug('end parameter validation: p_includeGL');

debug('begin parameter validation: p_apps_check');
IF p_apps_check IS NULL THEN
   print_error('INVALID ARGUMENT: Parameter Include Apps Check is required.');
   raise invalid_parameters;
END IF;
IF p_apps_check IS NOT NULL AND p_apps_check NOT IN ( 'N','Y') THEN
   print_error('INVALID ARGUMENT: Incorrect value for Include Apps Check parameter: Please enter Y or N.');
   raise invalid_parameters;
END IF;
debug('end parameter validation: p_apps_check');


debug('begin parameter validation: p_debug_mode');
IF p_debug_mode IS NOT NULL AND p_debug_mode NOT IN ( 'N','Y') THEN
   print_error('INVALID ARGUMENT: Debug Mode is invalid.  Valid values are Y or N');
   raise invalid_parameters;
END IF;
debug('end parameter validation: p_debug_mode');



-- Validation to verify analyzer is run on proper e-Business application version
-- In case validation at the beginning is updated/removed, adding validation here also so execution fails

  IF substr(l_apps_version,1,4) NOT IN ('12.0','12.1','12.2') THEN
    print_log('eBusiness Suite version = '||l_apps_version);
    print_log('ERROR: This Analyzer script is compatible for following version(s): 12.0,12.1,12.2');
    raise invalid_parameters;
  END IF;

-- .log enhancements (ER # 140)
  print_log(chr(10)||'Instance Information:');
  print_log('---------------------------');
  -- Do not report host details (EBSAF-274); reverted by EBSAF-293
  print_log('Host: '||g_rep_info('Host'));
  print_log('FullHost: '||g_rep_info('FullHost'));
  print_log('Instance: '||g_rep_info('Instance'));
  print_log('Database name: '||g_rep_info('DB Name'));
  print_log('Database version: '||g_rep_info('DB Version'));
  print_log('Applications version: '||g_rep_info('Apps Version'));
  print_log('Analyzer version: '||g_rep_info('File Version'));
  -- Report call details for troubleshooting (EBSAF-265)
  print_log('Calling method: '||g_rep_info('Calling From') );
  print_log('Calling module: '||g_rep_info('Calling Module') );
  print_log('---------------------------');

  -- Log session details (EBSAF-308)
  l_step := '8.5';
  print_log(chr(10)||'Session Information:');
  print_log('---------------------------');
  print_log('Language Code: '||sys_context('USERENV', 'LANG'));
  print_log('Region: '||sys_context('USERENV', 'NLS_TERRITORY'));
  print_log('Locale: '||sys_context('USERENV', 'LANGUAGE'));
  print_log('Date Format: '||sys_context('USERENV', 'NLS_DATE_FORMAT'));
  -- Get number characters
  select max(value) into l_system_function_var from v$parameter where name = 'nls_numeric_characters';
  print_log('Number Characters: '||l_system_function_var);
  -- Check for language installation
  begin
    execute immediate 'select max(installed_flag) from FND_LANGUAGES where language_code = sys_context(''USERENV'', ''LANG'')' into l_system_function_var;
    if (l_system_function_var is null or l_system_function_var not in ('B', 'I')) then
      print_log('WARNING: FND_LANGUAGES shows the session language is not installed.');
      print_log('Signatures relying on translation information may have incorrect results.');
    end if;
  exception when others then
    print_log('WARNING: Failed to check FND_LANGUAGES if session language is installed.');
  end;
  print_log('---------------------------');

  -- Verify escape character is set properly (EBSAF-265)
  l_step := '9';
  IF regexp_replace('Replace Test', '\s', '*') <>
     regexp_replace('Replace Test', chr(92) || 's', '*') THEN
    print_log('Invalid Escape:  Expected "' || chr(92) || 's' ||'" Received "\s"');
    print_log('Backslash character was not escaped properly during installation or execution.');
    raise invalid_escape;
  END IF;

  l_step := '10';
----------------------------------------------------------------
-- Analyzer-specific code: Additional Validation              --
----------------------------------------------------------------
debug('begin Additional Code: Additional Validation');
declare 
   l_seg_ctr NUMBER;
   
begin
 
   execute immediate 'alter session set NLS_DATE_FORMAT = ''DD-MON-YYYY''';

   g_trx_id_tmp := p_customer_trx_id;
   g_user_name_tmp := p_user_name;
   g_resp_id_tmp := p_resp_id;


   select org_id
   into   g_org_id
   from   ra_customer_trx_all
   where  customer_trx_id = g_trx_id_tmp;

   -- set Org context   
   mo_global.set_policy_context('S', g_org_id); 
   arp_global.init_global;

   open get_mo_org;
   Loop
      Fetch get_mo_org into g_mo_org;
      exit when get_mo_org%NOTFOUND;
      
      debug('g_mo_org = ' || g_mo_org);
   end loop;
   close get_mo_org;


   g_org_id_tmp := g_org_id;

   select ar.set_of_books_id, hr.name, ar.allow_late_charges
   into g_ledger_id, g_ou_name, g_allow_late_charges
   from ar_system_parameters_all ar, hr_operating_units hr
   where ar.org_id = g_org_id_tmp
   and   ar.org_id = hr.organization_id;
 
   select count(*)
   into   g_count_dbg_msg
   from   fnd_log_messages;

   -- Check if MFAR used?
    select nvl(FND_PROFILE.value('AR_MFAR_ACTIVATED'),'N')
    into   g_mfar
    from   dual;

   begin
      select U.RESPONSIBILITY_NAME
      into g_resp_name
      from FND_RESPONSIBILITY_VL U
      where u.responsibility_id = g_resp_id_tmp
      and u.application_id = 222;
   exception
   when no_data_found then
      g_resp_name := 'No responsibility provided';
   end;


   g_invoicing_rule_id := NULL;
   g_count := 0;

   BEGIN

      select trx.customer_trx_id, decode(typ.type, 'BR', trx.drawee_id, trx.bill_to_customer_id), decode(typ.type, 'BR', trx.drawee_site_use_id, trx.bill_to_site_use_id),
             to_char(trx.customer_trx_id), trx.invoicing_rule_id, typ.type, 
             trx.complete_flag, trx.ax_accounted_flag, trx.trx_number,
             trx.customer_reference, bat.name, bat.batch_source_id,bat.auto_trx_numbering_flag, typ.name, 
             to_char(trx.trx_date,'DD-MON-YYYY'), trx.invoice_currency_code, 
             to_char(trx.exchange_rate), pay.name, to_char(trx.term_due_date,'DD-MON-YYYY'), 
             rul.name, trx.status_trx, to_char(trx.initial_customer_trx_id), 
             to_char(trx.previous_customer_trx_id),
             ----- for autoaccounting
             nvl(trx.primary_salesrep_id, -88), nvl(decode(typ.type, 'BR', trx.drawee_site_use_id, trx.bill_to_site_use_id), -88),  nvl(trx.cust_trx_type_id, -88)
      into   g_customer_trx_id, g_cust_acct_id, g_bill_to_site_use,
             g_trx_id, g_invoicing_rule_id, g_type, 
             g_complete_flag, g_ax_accounted_flag, g_trxnumber, 
             g_custref, g_source, g_batch_source_id, g_auto_trx, g_typename, 
             g_trxdate, g_currency, 
             g_exchrate, g_terms, g_due, 
             g_rule, g_status, g_orig, 
             g_cred,
             g_salesrep_id, g_site_use_id, g_trx_type_id
      FROM   RA_CUSTOMER_TRX_ALL   trx,          
             RA_CUST_TRX_TYPES_ALL typ,          
             RA_BATCH_SOURCES_ALL  bat,          
             RA_TERMS              pay,          
             RA_RULES              rul  
      WHERE  trx.customer_trx_id = g_trx_id_tmp
      AND    typ.cust_trx_type_id(+) = trx.cust_trx_type_id 
      AND    NVL(typ.org_id(+), -99) = NVL(trx.org_id,  -99) 
      AND    bat.batch_source_id(+)  = trx.batch_source_id 
      AND    NVL(bat.org_id(+), -99) = NVL(trx.org_id, -99) 
      AND    pay.term_id(+)          = trx.term_id 
      AND    rul.rule_id(+)          = trx.invoicing_rule_id;

      if g_bill_to_site_use is not null then
         -- pick up the Customer related IDs once, for use in CUSTOMER_DATA sigs
         select cas.cust_acct_site_id, ps.party_site_id, loc.location_id
         into   g_cust_acct_site_id, g_party_site_id, g_location_id
         from   HZ_CUST_SITE_USES_ALL su, HZ_CUST_ACCT_SITES_ALL cas, HZ_PARTY_SITES ps, hz_locations loc
         where  su.site_use_id = g_bill_to_site_use
         and    su.cust_acct_site_id = cas.cust_acct_site_id
         and    cas.party_site_id =  ps.party_site_id  
         and    ps.location_id = loc.location_id;
      end if;

      -- pick up profile IDs
      BEGIN

         SELECT cust_account_profile_id,
                profile_class_id
         INTO   g_cust_acct_profile_id, 
                g_profile_class_id
         FROM   hz_customer_profiles
         WHERE  cust_account_id = g_cust_acct_id
         and    site_use_id = g_bill_to_site_use;

         print_log('CUST_ACCT_PROFILE_ID = ' || g_cust_acct_profile_id ||
                   ' PROFILE_CLASS_ID = ' || g_profile_class_id);

      EXCEPTION
      WHEN NO_DATA_FOUND THEN
          g_cust_acct_profile_id := -1;
          g_profile_class_id := -1;
      END;


      -- pick up Late Charge Site if it exists
      BEGIN
          SELECT site_use_id
          INTO   g_late_charge_site
          FROM   hz_cust_site_uses_all
          where  cust_acct_site_id in (SELECT cust_acct_site_id
                                       FROM HZ_CUST_ACCT_SITES_ALL
                                       WHERE cust_account_id = g_cust_acct_id)
          and    site_use_code = 'LATE_CHARGE';
          
          print_log('Late Charges Site = ' || g_late_charge_site);
      EXCEPTION
      WHEN OTHERS THEN
          g_late_charge_site := -1;
      END;

      -- pick up usage of BFB
      BEGIN
          SELECT distinct 'Y'
          INTO   g_uses_bfb
          FROM   hz_customer_profiles
          where  cust_account_id = g_cust_acct_id
          and    nvl(cons_inv_flag,'N') = 'Y';

      EXCEPTION
      WHEN OTHERS THEN
          g_uses_bfb := 'N';
      END;



      print_log('Evaluate AutoAccounting');
      -------------------------------------
      
      -- Get distinct account_class values where segments are sourced from non-constant


      open aa_get_account_class;
      Loop
         Fetch aa_get_account_class into g_account_class;
         exit when aa_get_account_class%NOTFOUND;

         print_log('Inside aa_get_account_class, g_account_class = ' || g_account_class);

         -- check which segments are sourced from a table rather than a constant
         l_seg_ctr := 0;
         
         open aa_get_flex_seg(g_account_class, g_org_id_tmp);
         loop
            fetch aa_get_flex_seg into aa_t(l_seg_ctr);
            exit when aa_get_flex_seg%NOTFOUND;
          
            if aa_t(l_seg_ctr).table_name is not null then
               -- this segment is sourced from a table should be checked
               print_log('   Segment ' || aa_t(l_seg_ctr).segment  || ' for ' || g_account_class || ' is sourced from ' || aa_t(l_seg_ctr).table_name);
               
               if g_account_class = 'REV' then
                  if aa_t(l_seg_ctr).table_name = 'RA_CUST_TRX_TYPES' then
                     g_AA_REV_TRX := 'Y';
                     print_log('      AA_REV_TRX = Y');

                  elsif aa_t(l_seg_ctr).table_name = 'RA_SALESREPS' then
                     g_AA_REV_SALES := 'Y';
                     print_log('      AA_REV_SALES = Y');

                  elsif aa_t(l_seg_ctr).table_name = 'RA_SITE_USES' then
                     g_AA_REV_SITE := 'Y';
                     print_log('      AA_REV_SITE = Y');

                  elsif aa_t(l_seg_ctr).table_name = 'RA_STD_TRX_LINES' then
                     g_AA_REV_ITEM := 'Y';
                     print_log('      AA_REV_ITEM = Y');

                  end if;
               elsif g_account_class = 'REC' then
                  if aa_t(l_seg_ctr).table_name = 'RA_CUST_TRX_TYPES' then
                     g_AA_REC_TRX := 'Y';
                     print_log('      AA_REC_TRX = Y');

                  elsif aa_t(l_seg_ctr).table_name = 'RA_SITE_USES' then
                     g_AA_REC_SITE := 'Y';
                     print_log('      AA_REC_SITE = Y');

                  elsif aa_t(l_seg_ctr).table_name = 'RA_SALESREPS' then
                     g_AA_REC_SALES := 'Y';
                     print_log('      AA_REC_SALES = Y');

                  end if;       
               elsif g_account_class in ('UNEARN','UNBILL') then
                  if aa_t(l_seg_ctr).table_name = 'RA_CUST_TRX_TYPES' then
                     g_AA_UN_TRX := 'Y';
                     print_log('      AA_UN_TRX = Y');

                  elsif aa_t(l_seg_ctr).table_name = 'RA_SITE_USES' then
                     g_AA_UN_SITE := 'Y';
                     print_log('      AA_UN_SITE = Y');

                  elsif aa_t(l_seg_ctr).table_name = 'RA_STD_TRX_LINES' then
                     g_AA_UN_ITEM := 'Y';
                     print_log('      AA_UN_ITEM = Y');

                  elsif aa_t(l_seg_ctr).table_name = 'RA_SALESREPS' then
                     g_AA_UN_SALES := 'Y';
                     print_log('      AA_UN_SALES = Y');

                  end if;                       
               end if;

            end if;

            l_seg_ctr := l_seg_ctr + 1;

         end loop;
         close aa_get_flex_seg;

      end loop;
      close aa_get_account_class;
  
      -- initialize items used to check cross-validation rules
      open get_segments(g_ledger_id); 
      loop
         fetch get_segments into g_flex_num, g_seg_num, g_seg_col;
         exit when get_segments%NOTFOUND;

         if g_seg_used is null then
            g_seg_used := 'gl.' || g_seg_col || ', segment'|| g_seg_num || '_low, segment' || g_seg_num || '_high';
            g_seg_cond := 'gl.' || g_seg_col || ' between segment' || g_seg_num || '_low and segment'|| g_seg_num||'_high';
            g_ccid_segs := 'gl.' || g_seg_col;
         else
            g_seg_used := g_seg_used || ', gl.' || g_seg_col || ', segment'|| g_seg_num || '_low, segment' || g_seg_num || '_high';
            g_seg_cond := g_seg_cond || ' and gl.' || g_seg_col || ' between segment' || 
                                       g_seg_num || '_low and segment' || g_seg_num||'_high';
            g_ccid_segs := g_ccid_segs || ', gl.' || g_seg_col;
         end if;

         end loop;
         close get_segments; 
      
         print_log('GL account segments used: ' || g_seg_used);
         print_log('Conditions to check rules: ' || g_seg_cond); 
         print_log('CCID segs: ' || g_ccid_segs);

   EXCEPTION
   WHEN NO_DATA_FOUND then
      print_log('Customer_trx_id does not exist in RA_CUSTOMER_TRX_ALL, but will continue to look for orphan records.');
      g_customer_trx_id := g_trx_id_tmp;
   END;

   select count(*) 
   into g_count
   from ra_cust_trx_line_gl_dist_all
   where customer_trx_id = g_trx_id_tmp
   and account_set_flag = 'N'; 

   BEGIN

     SELECT payment_schedule_id 
     INTO g_payment_schedule_id
     FROM ar_payment_schedules_all 
     WHERE customer_trx_id =  g_trx_id_tmp;

     EXCEPTION 
     WHEN OTHERS THEN
         g_payment_schedule_id := NULL;
      END;

   g_includeGL := upper(p_includeGL);
END;
-- Procedure for pay.
   pay_120_prc(g_trx_id_tmp,g_org_id_tmp);


  --script parameters signature
  select to_char(min(gl_date),'DD-MON-YYYY'), to_char(max(gl_date),'DD-MON-YYYY') 
  into   g_gl_date_start, g_gl_date_end 
  from
  (
  select   gl_date
  from     ra_cust_trx_line_gl_dist_all
  where    customer_trx_id = g_trx_id_tmp
  and       account_set_flag = 'N'
  union
  select   gl_date
  from     ar_receivable_applications_all
  where    customer_trx_id = g_trx_id_tmp
  union
  select   gl_date
  from     AR_TRANSACTION_HISTORY_ALL
  where    POSTABLE_FLAG ='Y'
  and customer_trx_id = g_trx_id_tmp
   );

  select user_id
  into g_user_id
  from fnd_user
  where user_name = g_user_name_tmp;

  select  currency_code
  into      g_ledger_currency
  from    gl_ledgers
  where  ledger_id = g_ledger_id;





    /* SEEDED EBS BANNER BEGIN */

    -- Premier Support Checks by priority
    select min(error_type) into l_system_function_var from (
        -- Database in Sustaining Support
        select 1 error_type from V$VERSION WHERE banner like '%11.2%' or banner like '%11.1%' or banner like '%10.%'
        union
        -- Application Version 11.5
        select 2 error_type from fnd_product_groups where release_name like '11.5%'
        union
        -- Application Version 12.1
        select 3 error_type from fnd_product_groups where release_name like '12.1%'
        union
        -- Database in Extended Support
        select 4 error_type from V$VERSION WHERE banner like '%12.1%'
        union
        -- Application Version 12.0
        select 5 error_type from fnd_product_groups where release_name like '12.0%'
        union
        -- Application Version 12.2.x outdated
        select 6 error_type from fnd_product_groups where release_name in ('12.2.0' , '12.2.1' , '12.2.2' , '12.2.3' , '12.2.4' , '12.2.5' , '12.2.6')
    );

    -- Set banner message by error type
    case l_system_function_var
        when 1 then
            -- Database in Sustaining Support
            g_banner_severity := 'W';
            g_banner_message := 'The database version running on this instance is in Sustaining Support. Please refer to Oracle''s Lifetime Support Policy in [2655839.2#supportp].<br>Ignore this warning if you have upgraded since this analyzer output was generated.';
        when 2 then
            -- Application Version 11.5
            g_banner_severity := 'W';
            g_banner_message := 'Premier Support for the application version on this instance ended on November 2010. Please refer to Oracle''s Lifetime Support Policy in [2655839.2#supportp].<br> Ignore this warning if you have upgraded since this analyzer output was generated.';
        when 3 then
            -- Application Version 12.1
            g_banner_severity := 'W';
            g_banner_message := 'Premier Support End for the application version on this instance is on December 2021. Please refer to Oracle''s Lifetime Support Policy in [2655839.2#supportp]. <br>Ignore this warning if you have upgraded since this analyzer output was generated.';
        when 4 then
            -- Database in Extended Support
            g_banner_severity := 'W';
            g_banner_message := 'The database version running on this instance is in Extended Support. Please refer to Oracle''s Lifetime Support Policy in [2655839.2#supportp].<br>Ignore this warning if you have upgraded since this analyzer output was generated.';
        when 5 then
            -- Application Version 12.0
            g_banner_severity := 'W';
            g_banner_message := 'Premier Support for the application version on this instance ended on January 2012. Please refer to Oracle''s Lifetime Support Policy in [2655839.2#supportp].<br>Ignore this warning if you have upgraded since this analyzer output was generated.';
        when 6 then
           -- Application Version 12.2.7
           g_banner_severity := 'W';
           g_banner_message := '<b>Effective July 1, 2024, the E-Business Suite 12.2 Error Correction Baseline will be 12.2.7.</b><br>
<br>
<div><div style="display:inline-block; text-align:left; max-width:800px;">Updating the application version to release 12.2.7 or higher will ensure you have access to major product releases.<br>
Refer to:<ul>
<li>[1195034/KB696368] Oracle E-Business Suite Error Correction Support Policy</li>
<li><a href="https://blogs.oracle.com/ebstech/post/update-error-correction-baseline-for-ebs-122" target="_blank">Oracle E-Business Suite Technology Blog</a> Update: Error Correction Baseline for EBS 12.2</li>
</ul>
Customers running E-Business Suite products on the 12.2.3 - 12.2.6 release levels are encouraged to update to current code levels of those products before July 2024 so they can benefit from the simpler and smaller patches that will be available starting in July 2024.<br>
In the event a new issue is reported on a product at a code level below the baseline, Oracle Support will attempt to resolve the issue and engage Development if necessary. Development may determine that the issue can be resolved at the customer code level, or may determine that the only practical way to provide the fix is for the customer to apply the baseline (or later) code in the affected area, and provide the fix at that level.
</div></div>';
        else
            -- No banner required
            g_banner_message := null;
    end case;
    /* SEEDED EBS BANNER END */
debug('end Additional Code: Additional Validation');



  g_parameters.DELETE;

  -- Recreate global hash for parameters after validation (includes the modifiers)
debug('begin populate parameters hash table');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'User Name';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_user_name,'DISPLAY_BOTH_25_PCNT_WORD');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Responsibility ID';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_resp_id,'NO_MASK');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Customer Trx Id';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_customer_trx_id,'NO_MASK');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Include GL';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_includeGL,'NO_MASK');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Include Apps Check';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_apps_check,'NO_MASK');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Maximum Rows to Display';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_max_output_rows,'NO_MASK');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Debug Mode';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_debug_mode,'NO_MASK');
debug('end populate parameters hash table');



  l_key := g_parameters.first;
  -- Print parameters to the log
  l_step := '11';
  print_log(chr(10)||'Parameter Values after validation:');
  print_log('---------------------------');

  FOR i IN 1..g_parameters.COUNT LOOP
    print_log(to_char(i) || '. ' || g_parameters(i).pname || ': ' || g_parameters(i).pvalue);
  END LOOP;
  print_log('---------------------------');

  -- Create global hash of SQL token values
debug('begin populate sql tokens hash table');
   g_sql_tokens('##$$TRXID$$##') := g_trx_id_tmp;
   g_masked_tokens('##$$TRXID$$##') := mask_text( g_sql_tokens('##$$TRXID$$##'), 'NO_MASK');
   g_sql_tokens('##$$ORGID$$##') := g_org_id;
   g_masked_tokens('##$$ORGID$$##') := mask_text( g_sql_tokens('##$$ORGID$$##'), 'NO_MASK');
   g_sql_tokens('##$$TYPE$$##') := g_type;
   g_masked_tokens('##$$TYPE$$##') := mask_text( g_sql_tokens('##$$TYPE$$##'), 'NO_MASK');
   g_sql_tokens('##$$COMPLETE_FLAG$$##') := g_complete_flag;
   g_masked_tokens('##$$COMPLETE_FLAG$$##') := mask_text( g_sql_tokens('##$$COMPLETE_FLAG$$##'), 'NO_MASK');
   g_sql_tokens('##$$TRXNUMBER$$##') := g_trxnumber;
   g_masked_tokens('##$$TRXNUMBER$$##') := mask_text( g_sql_tokens('##$$TRXNUMBER$$##'), 'NO_MASK');
   g_sql_tokens('##$$CUSTREF$$##') := g_custref;
   g_masked_tokens('##$$CUSTREF$$##') := mask_text( g_sql_tokens('##$$CUSTREF$$##'), 'DISPLAY_BOTH_25_PCNT_WORD');
   g_sql_tokens('##$$SOURCE$$##') := g_source;
   g_masked_tokens('##$$SOURCE$$##') := mask_text( g_sql_tokens('##$$SOURCE$$##'), 'NO_MASK');
   g_sql_tokens('##$$TYPENAME$$##') := g_typename;
   g_masked_tokens('##$$TYPENAME$$##') := mask_text( g_sql_tokens('##$$TYPENAME$$##'), 'NO_MASK');
   g_sql_tokens('##$$TRXDATE$$##') := g_trxdate;
   g_masked_tokens('##$$TRXDATE$$##') := mask_text( g_sql_tokens('##$$TRXDATE$$##'), 'NO_MASK');
   g_sql_tokens('##$$CURRENCY$$##') := g_currency;
   g_masked_tokens('##$$CURRENCY$$##') := mask_text( g_sql_tokens('##$$CURRENCY$$##'), 'NO_MASK');
   g_sql_tokens('##$$EXCHRATE$$##') := g_exchrate;
   g_masked_tokens('##$$EXCHRATE$$##') := mask_text( g_sql_tokens('##$$EXCHRATE$$##'), 'NO_MASK');
   g_sql_tokens('##$$TERMS$$##') := g_terms;
   g_masked_tokens('##$$TERMS$$##') := mask_text( g_sql_tokens('##$$TERMS$$##'), 'NO_MASK');
   g_sql_tokens('##$$DUE$$##') := g_due;
   g_masked_tokens('##$$DUE$$##') := mask_text( g_sql_tokens('##$$DUE$$##'), 'NO_MASK');
   g_sql_tokens('##$$RULE$$##') := g_rule;
   g_masked_tokens('##$$RULE$$##') := mask_text( g_sql_tokens('##$$RULE$$##'), 'NO_MASK');
   g_sql_tokens('##$$STATUS$$##') := g_status;
   g_masked_tokens('##$$STATUS$$##') := mask_text( g_sql_tokens('##$$STATUS$$##'), 'NO_MASK');
   g_sql_tokens('##$$ORIG$$##') := g_orig;
   g_masked_tokens('##$$ORIG$$##') := mask_text( g_sql_tokens('##$$ORIG$$##'), 'NO_MASK');
   g_sql_tokens('##$$CRED$$##') := g_cred;
   g_masked_tokens('##$$CRED$$##') := mask_text( g_sql_tokens('##$$CRED$$##'), 'NO_MASK');
   g_sql_tokens('##$$TRX_ID$$##') := g_trx_id;
   g_masked_tokens('##$$TRX_ID$$##') := mask_text( g_sql_tokens('##$$TRX_ID$$##'), 'NO_MASK');
   g_sql_tokens('##$$LEDGERID$$##') := g_ledger_id;
   g_masked_tokens('##$$LEDGERID$$##') := mask_text( g_sql_tokens('##$$LEDGERID$$##'), 'NO_MASK');
   g_sql_tokens('##$$RESP_ID$$##') := g_resp_id_tmp;
   g_masked_tokens('##$$RESP_ID$$##') := mask_text( g_sql_tokens('##$$RESP_ID$$##'), 'NO_MASK');
   g_sql_tokens('##$$USERNAME$$##') := g_user_name_tmp;
   g_masked_tokens('##$$USERNAME$$##') := mask_text( g_sql_tokens('##$$USERNAME$$##'), 'DISPLAY_BOTH_25_PCNT_WORD');
   g_sql_tokens('##$$AA_REV_TRX$$##') := g_AA_REV_TRX;
   g_masked_tokens('##$$AA_REV_TRX$$##') := mask_text( g_sql_tokens('##$$AA_REV_TRX$$##'), 'NO_MASK');
   g_sql_tokens('##$$AA_REV_SALES$$##') := g_AA_REV_SALES;
   g_masked_tokens('##$$AA_REV_SALES$$##') := mask_text( g_sql_tokens('##$$AA_REV_SALES$$##'), 'NO_MASK');
   g_sql_tokens('##$$AA_REV_SITE$$##') := g_AA_REV_SITE;
   g_masked_tokens('##$$AA_REV_SITE$$##') := mask_text( g_sql_tokens('##$$AA_REV_SITE$$##'), 'NO_MASK');
