debug('begin add_signature: AR_TRX_GL_DAILY_RATES');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '22451',
      p_sig_id                 => 'AR_TRX_GL_DAILY_RATES',
      p_sig_sql                => 'SELECT from_currency,
       to_currency,
       conversion_date,
       user_conversion_type,
       show_conversion_rate,
       show_inverse_con_rate,
       conversion_rate,
       inverse_conversion_rate,
       view_privilege,
       use_privilege,
       modify_privilege,
       status_code,
       conversion_type,
       context,
       last_update_date,
       last_updated_by,
       last_update_login,
       created_by,
       creation_date
FROM   gl_daily_rates_v
WHERE  status_code != ''D''
AND    view_privilege = ''Y''
AND    from_currency = ''##$$LEDGERCUR$$##''
AND    to_currency = ''##$$CURRENCY$$##''
AND    to_currency <> from_currency
AND    conversion_date = to_date(''##$$TRXDATE$$##'',''DD-MON-YYYY'') 
ORDER BY from_currency,
         to_currency,
         conversion_date DESC,
         user_conversion_type',
      p_title                  => 'Currency Exchange Rate Information',
      p_fail_condition         => 'NRS',
      p_problem_descr          => 'There is no exchange rate defined for the invoice currency.  ',
      p_solution               => 'Please make sure you setup an exchange_rate for '||mask_text(g_currency, nvl( upper(''), 'NO_MASK') )||'',
      p_success_msg            => 'Displaying exchange rate information for currency_code '||mask_text(g_currency, nvl( upper(''), 'NO_MASK') )||'',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '3'
      );
