debug('end add_signature: AR_TRX_GL_DAILY_RATES');



debug('begin add_signature: AR_TRX_AA_DUP_SEGMENTS');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '18999',
      p_sig_id                 => 'AR_TRX_AA_DUP_SEGMENTS',
      p_sig_sql                => 'SELECT ad.type, ads.segment_num, ads.segment, seg.segment_name
FROM ra_account_default_segments ads,
            ra_account_defaults_all ad, 
            ar_system_parameters_all sys,
            gl_sets_of_books gsob,
            fnd_id_flex_structures flex, 
            fnd_id_flex_segments seg
WHERE ad.gl_default_id = ads.gl_default_id
and sys.org_id = ##$$ORGID$$##
and sys.org_id = ad.org_id
and sys.set_of_books_id = gsob.set_of_books_id
and flex.id_flex_num = gsob.chart_of_accounts_id
and flex.application_id = 101
and flex.id_flex_code = ''GL#''
and seg.id_flex_num = flex.id_flex_num
and seg.application_id = 101
and seg.id_flex_code = ''GL#''
and ads.segment = seg.application_column_name
having count(ads.segment) <> count(distinct(ads.segment))
group by ad.type, ads.segment_num, ads.segment, seg.segment_name
order by 1, 2',
      p_title                  => 'AutoAccounting Set Up has Duplicate Segments',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'AutoAccounting set up has duplicate segments.',
      p_solution               => '<ul> 
<li>The analyzer has identified the issue described in [1548670/KB769684].</li> 
<li>Please log a Service Request and upload this analyzer output.</li> 
</ul>',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
