debug('begin add_signature: EBS_FIN_AR_TRX_INV_ACC_RULES');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '27105',
      p_sig_id                 => 'EBS_FIN_AR_TRX_INV_ACC_RULES',
      p_sig_sql                => 'select	ctl.previous_customer_trx_id INV_CUSTOMER_TRX_ID, ctl.customer_trx_id CM_CUSTOMER_TRX_ID, 
        ctl.previous_customer_trx_line_id INV_CUSTOMER_TRX_LINE_ID, ctl.customer_trx_line_id CM_CUSTOMER_TRX_LINE_ID,  
        invctl.accounting_rule_id INVOICE_ACCT_RULE, ctl.accounting_rule_id CM_ACCT_RULE,
        invctl.accounting_rule_duration INVOICE_RULE_DURATION, ctl.accounting_rule_duration CM_RULE_DURATION,
        invctl.rule_start_date INVOICE_RULE_START_DATE, ctl.rule_start_date CM_RULE_START_DATE,
        invctl.rule_end_date INVOICE_RULE_END_DATE, ctl.rule_end_date CM_RULE_END_DATE,
        invctl.autorule_duration_processed INVOICE_RULE_DURATION_PROCESS , ctl.autorule_duration_processed CM_RULE_DURATION_PROCESS ,
        invctl.autorule_complete_flag INVOICE_RULE_COMPLETE_FLAG, ctl.autorule_complete_flag CM_RULE_COMPLETE_FLAG
from 	ra_customer_trx_lines_all invctl,
  	ra_customer_trx_lines_all ctl,
  	ra_customer_trx_all trx,
  	ra_cust_trx_types_all trx_type
where	ctl.customer_trx_id  = trx.customer_trx_id
and     ctl.previous_customer_trx_id = invctl.customer_trx_id
and     invctl.customer_trx_line_id = ctl.previous_customer_trx_line_id 
and		trx.customer_trx_id = ##$$TRXID$$##
and		trx.cust_trx_type_id = trx_type.cust_trx_type_id
and 	(trx.invoicing_rule_id is not NULL or ctl.accounting_rule_id is not NULL )
and     ctl.line_type = ''LINE''
and     trx_type.type = ''CM''
and     trx_type.org_id = trx.org_id
order by ctl.customer_trx_id, ctl.customer_trx_line_id',
      p_title                  => 'Accounting Rules Information of Referenced Invoice',
      p_fail_condition         => 'NRS',
      p_problem_descr          => 'There are no Accounting Rules on Referenced Invoice.',
      p_solution               => 'Accounting Rules Information of Referenced Invoice.',
      p_success_msg            => 'Accounting Rules Information of Referenced Invoice.',
      p_print_condition        => nvl('SUCCESS','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '1'
      );
   l_info.delete;
