debug('begin add_signature: AR_TRX_AR_ADJUSTMENTS_ALL_TOTALS');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '4532',
      p_sig_id                 => 'AR_TRX_AR_ADJUSTMENTS_ALL_TOTALS',
      p_sig_sql                => 'SELECT adjustment_type,
       sum(amount) sum_amount,
       sum(line_adjusted) sum_line_adjusted,
       sum(freight_adjusted) sum_freight_adjusted,
       sum(tax_adjusted) sum_tax_adjusted,
       sum(receivables_charges_adjusted) sum_charges_adjusted,
       sum(acctd_amount) sum_acctd_amount,
      decode(sum(nvl(amount,0)) - sum(nvl(line_adjusted,0)) - sum(nvl(freight_adjusted,0))  - sum(nvl(tax_adjusted,0))
                     -sum(nvl(receivables_charges_adjusted,0)), 0,''BALANCED'',''OUT OF BALANCE'') STATUS
FROM   ar_adjustments_all
WHERE  customer_trx_id = ##$$TRXID$$##
AND    postable = ''Y''
AND    status = ''A''
GROUP BY adjustment_type',
      p_title                  => 'AR_ADJUSTMENTS_ALL Totals',
      p_fail_condition         => '[STATUS] = [OUT OF BALANCE]',
      p_problem_descr          => 'The sum of adjustments made to this transaction in AR_ADJUSTMENTS are out of balance.',
      p_solution               => 'Please review the Data Integrity section of this analyzer, to identify the issue that may be causing the out of balance condition.',
      p_success_msg            => 'Displaying sum of adjustments to this transaction from AR_ADJUSTMENTS_ALL table.',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '10'
      );
