debug('begin add_signature: EBS_FIN_AR_TRX_CREATION_REQUEST_DETAILS');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '29818',
      p_sig_id                 => 'EBS_FIN_AR_TRX_CREATION_REQUEST_DETAILS',
      p_sig_sql                => 'select distinct fr.request_id,
ft.user_concurrent_program_name,
to_char(fr.actual_start_date,''dd-MON-yy hh24:mi:ss'') "Started",
to_char(fr.actual_completion_date,''dd-MON-yy hh24:mi:ss'') "Completed",
decode(fr.phase_code,''C'',''Completed'',''I'',''Inactive'',''P'',''Pending'',''R'',''Running'',''NA'') "Phasecode",
decode(fr.status_code, ''A'',''Waiting'', ''B'',''Resuming'', ''C'',''Normal'', ''D'',''Cancelled'', ''E'',''Error'', ''F'',''Scheduled'', ''G'',''Warning'', ''H'',''On Hold'', ''I'',''Normal'', ''M'',
''No Manager'', ''Q'',''Standby'', ''R'',''Normal'', ''S'',''Suspended'', ''T'',''Terminating'', ''U'',''Disabled'', ''W'',''Paused'', ''X'',''Terminated'', ''Z'',''Waiting'') "Status",
fr.COMPLETION_TEXT,
fr.argument_text "Parameters",
fr.responsibility_id,
fr.parent_request_id,
fr.argument1,
fr.argument2,
fr.argument3,
fr.argument4,
fr.argument5,
fr.argument6,
fr.argument7,
fr.argument8,
fr.argument9,
fr.argument10,
fr.argument11,
fr.argument12,
fr.argument13,
fr.argument14,
fr.argument15,
fr.argument16,
fr.argument17,
fr.argument18,
fr.argument19,
fr.argument20,
fr.argument21,
fr.argument22,
fr.argument23,
fr.argument24,
fr.argument25
from fnd_concurrent_requests fr, fnd_concurrent_programs fp, fnd_concurrent_programs_tl ft
where fr.concurrent_program_id = fp.concurrent_program_id
and   fr.program_application_id = fp.application_id
and ft.concurrent_program_id=fr.concurrent_program_id
and fr.request_id in (select request_id from ra_customer_trx_all
		where customer_trx_id  = ##$$TRXID$$## 
		and request_id is not null)',
