debug('begin add_signature: EBS_FIN_AR_TRX_XLA_CUSTOM_ADRS');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '23357',
      p_sig_id                 => 'EBS_FIN_AR_TRX_XLA_CUSTOM_ADRS',
      p_sig_sql                => 'SELECT DISTINCT
    adr.line_definition_code,
    adr.line_definition_owner_code,
    adr.accounting_line_code,
    adr.accounting_line_type_code,
    adr.segment_rule_code,
    adr.segment_rule_type_code,
    adr.segment_rule_name,
    adr.flexfield_segment_name,
    adr.segment_rule_owner
FROM
    xla_distribution_links xdl,
    xla_ae_headers xah,
    xla_transaction_entities_upg xte,
    xla_line_defn_adr_assgns_f_v adr
WHERE
    xdl.ae_header_id = xah.ae_header_id
    AND xah.application_id = 222
    AND xdl.application_id = xah.application_id
    AND xah.entity_id = xte.entity_id
    AND xte.application_id = 222
    AND ((xte.entity_code in (''BILLS_RECEIVABLE'') and ''DM'' = ''BR'') 
          OR
         (xte.entity_code in (''TRANSACTIONS'') and ''DM''  <> ''BR''))
    AND nvl(source_id_int_1, - 99) =  ##$$TRXID$$##
    AND adr.line_definition_code = xdl.line_definition_code
    AND adr.amb_context_code = xah.amb_context_code
    AND adr.accounting_line_code = xdl.accounting_line_code
    AND adr.segment_rule_type_code <> ''S''
ORDER BY
    adr.accounting_line_code',
      p_title                  => 'Custom ADRs Associated ',
      p_fail_condition         => 'NRS',
      p_problem_descr          => 'There are no custom ADR associated with this transaction''s Accounting. This does not necessarily indicate an error/issue exists.
',
      p_solution               => 'No custom ADR associated with this transaction''s Accounting.',
      p_success_msg            => 'Displaying Custom ADR''s associated with this transaction''s Accounting.',
      p_print_condition        => nvl('SUCCESS','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '6'
      );
   l_info.delete;
debug('end add_signature: EBS_FIN_AR_TRX_XLA_CUSTOM_ADRS');



