debug('begin add_signature: AR_TRX_AUTOACC_SEGMENTS');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '11071',
      p_sig_id                 => 'AR_TRX_AUTOACC_SEGMENTS',
      p_sig_sql                => 'SELECT b.segment_name, e.segment_num,
decode(e.constant,null, decode(e.table_name,''RA_CUST_TRX_TYPES'', ''Transaction Types'',
''RA_SITE_USES'', ''Site'',
''RA_SALESREPS'', ''Salesreps'',
''RA_STD_TRX_LINES'', ''Standard Lines'',
e.table_name), e.constant) Sourced_From
FROM FND_ID_FLEX_SEGMENTS_VL b,
GL_LEDGERS c,
AR_SYSTEM_PARAMETERS_ALL d,
RA_ACCOUNT_DEFAULT_SEGMENTS e,
RA_ACCOUNT_DEFAULTS_ALL a
WHERE b.application_id = 101
AND b.id_flex_code = ''GL#''
AND d.set_of_books_id = c.ledger_id
AND b.id_flex_num = c.chart_of_accounts_id
AND e.segment = b.application_column_name
AND a.gl_default_id = e.gl_default_id
and d.org_id = a.org_id
AND NVL(d.org_id, -99) = ##$$ORGID$$##
and a.type = ''##$$FK1$$##''
order by e.segment_num',
      p_title                  => 'AutoAccounting Segments for ##$$FK1$$##',
      p_fail_condition         => 'NRS',
      p_problem_descr          => 'No AutoAccounting segments defined.',
      p_solution               => 'If you intend to use AutoAccounting to derive your GL accounts, please review [1069052/KB449160] Setting Up AutoAccounting Rules In Receivables.',
      p_success_msg            => 'Displaying current AutoAccounting segments setup.',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '22'
      );
   l_info.delete;
debug('end add_signature: AR_TRX_AUTOACC_SEGMENTS');



