  add_signature(
      p_sig_repo_id            => '8850',
      p_sig_id                 => 'AR_TRX_AA_MISS_REV_ITEM',
      p_sig_sql                => 'SELECT segment1 "NAME", description, nvl(to_char(sales_account),''MISSING'') "GL_ACCOUNT"
FROM   mtl_system_items_b
WHERE  (inventory_item_id, organization_id) IN
         (select inventory_item_id, 
                 nvl(decode(warehouse_id,-99,NULL), 
                     to_number(oe_profile.value(''SO_ORGANIZATION_ID'',org_id)))
          from ra_customer_trx_lines_all
          where customer_trx_id = ##$$TRXID$$##)   
AND nvl(sales_account,-1) = -1
and ( (''##$$FK1$$##'' = ''REV'' and ''##$$AA_REV_ITEM$$##'' = ''Y'') 
           or (''##$$FK1$$##'' = ''UNEARN'' and ''##$$RULE$$##'' = ''Advance Invoice'' and ''##$$AA_UN_ITEM$$##'' = ''Y'') 
           or (''##$$FK1$$##'' = ''UNBILL'' and ''##$$RULE$$##'' = ''Arrears Invoice'' and ''##$$AA_UN_ITEM$$##'' = ''Y'') )',
      p_title                  => 'Inventory Item Setup: Missing ##$$FK1$$## GL Account',
