      p_problem_descr          => 'The Revenue account derives one or more segments from the GL account of the inventory item, but the inventory item set up is incomplete.',
      p_solution               => 'For more information on how to define a Revenue account for this inventory item, please review [1069052/KB449160#aref_section28] Setting Up AutoAccounting Rules In Receivables [Video].',
      p_success_msg            => 'GL Account for Revenue exists for this Inventory Item, no action required.',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '25'
      );
