      p_sig_repo_id            => '18509',
      p_sig_id                 => 'AR_TRX_AA_SHOW_REV_ITEM',
      p_sig_sql                => 'SELECT b.segment1 "NAME", b.description, gl.code_combination_id, ##$$g_ccid_segs$$##
FROM   mtl_system_items_b b, gl_code_combinations gl
WHERE  (inventory_item_id, organization_id) IN
         (select inventory_item_id, 
                 nvl(decode(warehouse_id,-99,NULL), 
