debug('begin add_signature: AR_LC_PROFILE_OPTION');
   l_info('##MASK##LEVEL_VALUE'):= 'NO_MASK';
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '7055',
      p_sig_id                 => 'AR_LC_PROFILE_OPTION',
      p_sig_sql                => 'SELECT
    substr(e.profile_option_name,1,25) profile,
    DECODE(a.level_id,
        10001,
        ''Site'',
        10002,
        ''Application'',
        10003,
        ''Resp'',
        10004,
        ''User''
    ) "LEVEL",
    DECODE(a.level_id,
        10001,
        ''Site'',
        10002,
        c.application_short_name,
        10003,
        b.responsibility_name,
        10004,
        ##$$A$$##.mask_text(d.user_name,''##$$M$$##'')
    ) "LEVEL VALUE",
    nvl(a.profile_option_value,''Is Null'') value,
    substr(a.last_update_date,1,25) updated_date
FROM
    fnd_profile_option_values a,
    fnd_responsibility_tl b,
    fnd_application c,
    fnd_user d,
    fnd_profile_options e
WHERE
    e.profile_option_name IN (''AR_USE_STATEMENTS_AND_DUNNING_SITE_PROFILE'')
AND e.profile_option_id = a.profile_option_id
AND a.level_value = b.responsibility_id (+)
AND a.level_value = c.application_id (+)
AND a.level_value = d.user_id (+)
ORDER BY 2,3',
      p_title                  => 'Profile Options Used by Late Charges',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Displaying the settings for profile AR: Use Statement, Dunning, and Late Charges Site Profiles.',
      p_solution               => 'If any of the rows returns Yes, please ensure that you have defined a Late Charges site for customers you intend to calculate Late Charges against.
<ul>
<li><b>Navigation:</b> Receivables > Customers > Customers </li>
<li>Query the customer</li>
<li>Open the site you want Late Charges to be assigned to</li>
<li>Under <em>Business Purposes</em> tab, add another row for Late Charges, Save</li>
</ul>',
      p_success_msg            => '',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '17'
      );
   l_info.delete;
debug('end add_signature: AR_LC_PROFILE_OPTION');



