debug('begin add_signature: AR_LC_CUST_CHARGE_START_DATE');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '7189',
      p_sig_id                 => 'AR_LC_CUST_CHARGE_START_DATE',
      p_sig_sql                => 'SELECT
trx.trx_number "TRX NUMBER",
cp.charge_begin_date "SITE PROFILE CHARGE START DATE",
ps.due_date "TRX DUE DATE"
FROM
hz_customer_profiles cp,
ra_customer_trx_all trx,
ar_payment_schedules_all ps
WHERE cp.cust_account_profile_id = ##$$CAPID$$##
and   trx.customer_trx_id = ps.customer_trx_id
and   trx.customer_trx_id = ##$$TRXID$$##
AND   ps.due_date < cp.charge_begin_date',
      p_title                  => 'Due Date is Before Late Charge Start Date',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'The start date for late charges for the customer site comes after the due date of the invoice.',
      p_solution               => 'If you want charges to be calculated on the transaction, please ensure that the start date for late charges is on or before the due date of the invoice.
<ul>
<li>Reference: Late Charges Issue: Generate Late Charges is not Picking Overdue Invoices [746324/KB272606]</li>
</ul>',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '21'
      );
   l_info.delete;
debug('end add_signature: AR_LC_CUST_CHARGE_START_DATE');



debug('begin add_signature: AR_LC_SCHED_START_DATE');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '7187',
      p_sig_id                 => 'AR_LC_SCHED_START_DATE',
      p_sig_sql                => 'SELECT distinct acsh.start_date "Late Charge Start Date",
       acsh.schedule_id,
       arps.due_date "Invoice Due Date"
FROM   ar_charge_schedule_hdrs acsh,
       ar_payment_schedules_all arps,
       HZ_CUSTOMER_PROFILES hcp
WHERE  acsh.schedule_id IN 
      (SELECT interest_schedule_id
       FROM   hz_cust_profile_amts
       WHERE  cust_account_profile_id = ##$$CAPID$$##
       UNION 
       SELECT penalty_schedule_id
       FROM   hz_cust_profile_amts
       WHERE  cust_account_profile_id = ##$$CAPID$$##
      )
and    arps.due_date <= acsh.start_date
and    hcp.CUST_ACCOUNT_PROFILE_ID = ##$$CAPID$$##
and    arps.customer_trx_id=##$$TRXID$$##
and    org_id =##$$ORGID$$##',
      p_title                  => 'Late Charge Schedule Starts After Transaction Due Date',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'The start date of the Late Charges Schedule is after the due date of the transaction. This means that the transaction will already be overdue and the late charges schedule is not yet in effect.',
      p_solution               => 'The start date of the Late Charges Schedule is after the due date of the invoice, hence late charges will not calculate.
<ul>
<li>To correct this issue:</li>
<li><b>Navigation:</b> Receivables > Customers > Customers > query the customer</li>
<li>Under the Late Charges tab, change the start date to an applicable date</li>
<li>Reference: Late Charges Issue: Generate Late Charges is not Picking Overdue Invoices [746324/KB272606]</li>
</ul>',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '16'
      );
   l_info.delete;
debug('end add_signature: AR_LC_SCHED_START_DATE');



debug('begin add_signature: AR_LC_TIER_START_DATE');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '7188',
      p_sig_id                 => 'AR_LC_TIER_START_DATE',
      p_sig_sql                => 'SELECT distinct archs.schedule_name "Schedule Name",
       acsh.schedule_id,
       acsh.start_date "Tier Start Date",
       arps.due_date "Transaction Due Date"
FROM   ar_charge_schedule_hdrs acsh,
       ar_charge_schedules archs,
       ar_payment_schedules_all arps,
       HZ_CUSTOMER_PROFILES hcp
WHERE  acsh.schedule_id IN 
       (SELECT interest_schedule_id
        FROM   hz_cust_profile_amts
        WHERE  cust_account_profile_id = ##$$CAPID$$##
        AND    INTEREST_TYPE in (''CHARGES_SCHEDULE'',''CHARGE_PER_TIER'')
        UNION 
        SELECT penalty_schedule_id
        FROM   hz_cust_profile_amts
        WHERE  cust_account_profile_id = ##$$CAPID$$##
        AND    INTEREST_TYPE in (''CHARGES_SCHEDULE'',''CHARGE_PER_TIER''))
    and arps.due_date <= acsh.start_date
    and arps.customer_trx_id = ##$$TRXID$$##
    and hcp.CUST_ACCOUNT_PROFILE_ID = ##$$CAPID$$##
    and archs.schedule_id = acsh.schedule_id
    and acsh.status = ''A''
    and hcp.site_use_id = ##$$SITEUSEID$$##',
      p_title                  => 'Charge Tier Start Date is After Invoice Due Date',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'The late charge tier start date is after the due date of the transaction.',
      p_solution               => 'The late charge tier start date for the customer is after the due date of the invoice, hence late charges will not calculate.
<ul>
<li>To correct this issue:</li>
<li><b>Navigation:</b> Receivables > Late Charges > Charge Schedules</li>
<li>Query the schedule name returned and make required changes to the start date</li>
<li>Reference: Late Charges Issue: Generate Late Charges is not Picking Overdue Invoices [746324/KB272606]</li>
</ul>',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '13'
      );
   l_info.delete;
debug('end add_signature: AR_LC_TIER_START_DATE');



debug('begin add_signature: AR_LC_DM_ACCTS_MISSING');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '7211',
      p_sig_id                 => 'AR_LC_DM_ACCTS_MISSING',
      p_sig_sql                => 'Select ractt.Name, Decode(Nvl(Gl_Id_Rec,-1),-1,''Y'',''N'') Missing_Receivable, 
       Decode(Nvl(Gl_Id_Rev,-1),-1,''Y'',''N'') Missing_Revenue,
       Decode(Nvl(Gl_Id_Unbilled,-1),-1,''Y'',''N'') Missing_Unbilled_Receivable, 
       Decode(Nvl(Gl_Id_Unearned,-1),-1,''Y'',''N'') Missing_Unearned_Revenue,
       Decode(Nvl(Gl_Id_Clearing,-1),-1,''Y'',''N'') Missing_Clearing
   From   Ra_Cust_Trx_Types_all ractt,
          hz_customer_profiles hzp
   Where  (Nvl(Gl_Id_Rec,-1) = -1 Or
           Nvl(Gl_Id_Rev,-1) = -1  )
     And Cust_Trx_Type_Id In
  (Select Late_Charge_Dm_Type_Id From Ar_System_Parameters_All
     Where Org_Id=##$$ORGID$$##)
     and hzp.LATE_CHARGE_TYPE = ''DM''
     and hzp.cust_account_id = ##$$CUSTACCTID$$##',
      p_title                  => 'Late Charge Debit Memo Missing GL Accounts',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'The Debit Memo transaction type used for Late Charges is missing GL accounts.',
      p_solution               => 'This customer is setup for Debit Memo late charges. However not all of the GL accounts have been defined for the transaction type.
<ul>
<li>Reference: Generate Late Charge Process Error: Header Interest_Header_ID Code Combination ID is Required [1587278/KB245472].</li>
</ul>',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '16'
      );
   l_info.delete;
debug('end add_signature: AR_LC_DM_ACCTS_MISSING');



