debug('begin add_signature: AR_LC_MISMATCH_SCHED_TYPE');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '7262',
      p_sig_id                 => 'AR_LC_MISMATCH_SCHED_TYPE',
      p_sig_sql                => 'SELECT
hcpa.interest_schedule_id "Schedule ID",
hcpa.interest_type "Interest Type",
acs.schedule_name "Schedule Name",
acs.schedule_description "Schedule Description",
rcta.bill_to_site_use_id  "Customer Site ID",
acsh.SCHEDULE_HEADER_TYPE "Schedule Type"
FROM
hz_cust_profile_amts hcpa,
AR_CHARGE_SCHEDULE_HDRS acsh,
AR_CHARGE_SCHEDULES acs,
AR_PAYMENT_SCHEDULES_ALL ps,
RA_CUSTOMER_TRX_ALL rcta
WHERE
hcpa.CURRENCY_CODE IN (
SELECT
rcta.invoice_currency_code
FROM
ra_customer_trx_all rcta
WHERE
rcta.customer_trx_id = ##$$TRXID$$##
)
and hcpa.interest_type = ''CHARGE_PER_TIER''
and hcpa.interest_schedule_id = acsh.schedule_id
and acsh.SCHEDULE_HEADER_TYPE <> ''AMOUNT''
and acs.schedule_id = acsh.schedule_id
and hcpa.cust_account_id = ##$$CUSTACCTID$$##
and ps.customer_site_use_id = hcpa.site_use_id
and rcta.customer_trx_id = ps.customer_trx_id
and rcta.customer_trx_id = ##$$TRXID$$##',
      p_title                  => 'Incorrect Schedule Type for Charge Schedule Per Tier',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Schedule Type must be Amount, when Interest Charge type = ''Charge Schedule per Tier''.',
      p_solution               => 'Since you picked Interest Charge type = ''Charge Schedule per Tier'', the Charge Schedule you picked must have Schedule type = Amount.
<ul>
<li>Option 1: If you want to keep using <em>Charge Schedule per Tier</em>, then you need to use a Charge Schedule that has Schedule type = Amount.</li>
<ul>
<li><b>Navigation:</b> Receivables > Late Charges > Charge Schedules</li>
<li>Identify a Schedule that uses Schedule Type = Amount</li>
<li>Once you have determined which Schedule you should use, update the profile</li>
<li><b>Navigation:</b> Receivables > Customers > Customers</li>
<li>Query the customer and under the late charges tab</li>
<li>Change the Charge Schedule</li>
</ul>


<li>Option 2: If you want to use a Charge Schedule that has Schedule type = Percent, then change the Customer profile</li>
<ul>
<li><b>Navigation:</b> Receivables > Customers > Customers</li>
<li>Query the customer and under the late charges tab</li>
<li>Change the Interest Charge type to ''Charge Schedule per Invoice''</li>
</ul>

<li>Reference: Transactions Workbench: Known Issues for Late Charges [1311307/KB480660#err1]</li>
</ul>',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '17'
      );
   l_info.delete;
debug('end add_signature: AR_LC_MISMATCH_SCHED_TYPE');



debug('begin add_signature: AR_LC_INV_HEADER_STAMPED');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '7221',
      p_sig_id                 => 'AR_LC_INV_HEADER_STAMPED',
      p_sig_sql                => 'Select   distinct inth.interest_batch_id, inth.worker_num
From     ar_interest_batches_all intb,
         ar_interest_headers_all  inth
Where    intb.INTEREST_BATCH_ID = inth.INTEREST_BATCH_ID
And     inth.worker_num is not null
And     intb.batch_status = ''F''
And     intb.transferred_status = ''E''
And     not exists
     (select ''x''  FROM ar_interest_headers_all intho
      WHERE intho.interest_batch_id =inth.interest_batch_id
        AND intho.worker_num        = inth.worker_num
        AND intho.process_status    = ''S''  
      )
And     not exists
     (select ''x''  FROM ar_interest_headers_all  intho
      WHERE intho.interest_batch_id =inth.interest_batch_id
        AND intho.display_flag  = ''Y''  
        AND intho.worker_num    = inth.worker_num
      )
And     not exists
     (select ''x''  FROM ar_interest_headers_all intho
      WHERE intho.interest_batch_id =inth.interest_batch_id
        AND intho.display_flag  <>  ''N''  
        AND intho.worker_num   = inth.worker_num
      )
And     not exists
     (select ''x''  FROM ar_interest_headers_all intho
      WHERE intho.interest_batch_id =inth.interest_batch_id
        AND intho.process_status  <> ''N''  
        AND intho.worker_num    = inth.worker_num
      )
And     not exists
     (
     select ''x'' from ar_interest_headers_all intho
      where intho.interest_batch_id = inth.interest_batch_id  
      and   intho.process_status <> ''S''
      and   intho.worker_num <> inth.worker_num
     )',
      p_title                  => 'Late Charge Headers Incorrectly Stamped with Success "S"',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Header late charge records are incorrectly stamped as successful when using multiple workers.',
      p_solution               => '<ul>
<li>Please log a Service Request with Oracle Support to correct this corruption</li>
<li>Reference: Transactions Workbench Issue: Late Charges Ended in Error at Batch Level When Run in Final Mode [1955258/KB795672]</li>
</ul>',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '10'
      );
   l_info.delete;
debug('end add_signature: AR_LC_INV_HEADER_STAMPED');



