      p_sig_repo_id            => '7218',
      p_sig_id                 => 'AR_LC_ORPHAN_LINES',
      p_sig_sql                => 'SELECT *
from ar_interest_lines_all iline
         WHERE NOT EXISTS
           (SELECT ''X''
           FROM ar_interest_headers_all ihd
            WHERE ihd.interest_header_id=iline.interest_header_id
            )',
      p_title                  => 'Orphan Late Charge Lines Exist',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Orphaned late charge lines exist which do not have late charge header records.',
