debug('begin add_signature: AR_TRX_AR_00007_8_DUP_TAX_DIST');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '4671',
      p_sig_id                 => 'AR_TRX_AR_00007_8_DUP_TAX_DIST',
      p_sig_sql                => 'SELECT g1.customer_trx_id, sum(g1.amount) Unposted_tax, 
       sum(g2.amount) Posted_tax
FROM   ra_cust_trx_line_gl_dist_all g1,
       ra_cust_trx_line_gl_dist_all g2 
WHERE  g1.customer_trx_id = ##$$TRXID$$##
AND    g1.customer_trx_id = g2.customer_trx_id 
AND    g1.account_class = ''TAX''
AND    g1.posting_control_id = -3 
AND    g1.account_set_flag = ''N'' 
AND    g2.posting_control_id <> -3 
AND    g2.account_class = ''TAX'' 
AND    g2.account_set_flag = ''N''
AND    g2.org_id = g1.org_id 
AND    g1.org_id = g2.org_id 
GROUP BY g1.customer_trx_id, g1.org_id 
HAVING sum(g1.amount) = sum(g2.amount)',
      p_title                  => 'Duplicate Tax Distributions (AR_00007_8)',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Transaction has duplicate tax distributions in RA_CUST_TRX_LINE_GL_DIST_ALL.',
      p_solution               => '<ul><li>The analyzer has identified data corruption described in [1277053/KB626208]</li>
<li>Please log a Service Request and upload this analyzer output.</li>
</ul>',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '5'
      );
   l_info.delete;
debug('end add_signature: AR_TRX_AR_00007_8_DUP_TAX_DIST');



debug('begin add_signature: AR_TRX_AR_00014_NULL_ACCTD_AMT');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '4672',
      p_sig_id                 => 'AR_TRX_AR_00014_NULL_ACCTD_AMT',
      p_sig_sql                => 'SELECT gld.customer_trx_id,
  ctl.customer_trx_line_id,
  ctl.previous_customer_trx_id inv_customer_trx_id,
  gld.cust_trx_line_gl_dist_id,
  ctl.accounting_rule_id,
  ctl.extended_amount,
  gld.amount,
  gld.acctd_amount,
  gld.posting_control_id,
  nvl(trx.exchange_rate, 1) exchange_rate,
  arpcurr.currround(gld.amount * nvl(trx.exchange_rate, 1),
gsob.currency_code) new_acctd_amount
FROM ra_cust_trx_line_gl_dist_all gld,
  ra_customer_trx_lines_all ctl,
  ra_customer_trx_all trx,
  gl_sets_of_books gsob
where trx.customer_trx_id = ##$$TRXID$$##
 and  gld.account_set_flag = ''N''
 and trx.customer_trx_id = trx.customer_trx_id
 and trx.set_of_books_id = gsob.set_of_books_id
 and gld.account_class in (''REV'', ''UNBILL'', ''UNEARN'')
 AND gld.customer_trx_id = ctl.customer_trx_id
 AND gld.customer_trx_line_id = ctl.customer_trx_line_id
 and gld.customer_trx_id = trx.customer_trx_id
 and gld.amount is not null
 and gld.acctd_amount is null
 and trx.invoicing_rule_id in (-2, -3)
 and gld.posting_control_id <> -3
order by customer_trx_id, ctl.customer_trx_line_id,
gld.cust_trx_line_gl_dist_id',
      p_title                  => 'Null RA_CUST_TRX_LINE_GL_DIST_ALL.ACCTD_AMOUNT (AR_00014)',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Transaction has ACCTD_AMOUNT showing null in RA_CUST_TRX_LINE_GL_DIST_ALL.',
      p_solution               => '<ul>
<li>The analyzer has identified data corruption described in [2059651/KB712817] AR_00014 Transaction has Records where RA_CUST_TRX_LINE_GL_DIST_ALL.ACCTD_AMOUNT is Null</li>
<li>Please log a Service Request and upload this analyzer output.</li>
</ul>',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '7'
      );
   l_info.delete;
debug('end add_signature: AR_TRX_AR_00014_NULL_ACCTD_AMT');



