debug('begin add_signature: AR_TRX_AR_00022_MISS_TAX_LINES');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '4683',
      p_sig_id                 => 'AR_TRX_AR_00022_MISS_TAX_LINES',
      p_sig_sql                => 'select distinct ct.customer_trx_id, ctl.customer_trx_line_id, gld.event_id , gld.gl_date,ct.exchange_rate, gld.posting_Control_id,xah.gl_transfer_status_code
from ra_customer_trx_all ct,
ra_customer_trx_lines_all ctl,
ra_cust_trx_types_all ctt ,
ra_cust_trx_line_gl_dist_all gld,
xla_events xe,
xla_ae_headers xah
WHERE ct.customer_trx_id = ##$$TRXID$$##
and ct.customer_trx_id = ctl.customer_trx_id
and ct.invoicing_rule_id is null
and ctl.line_type = ''LINE''
and ct.cust_Trx_type_id = ctt.cust_Trx_type_id
and ctt.type in(''INV'',''CM'',''DM'')
and ct.customer_trx_id = gld.customer_trx_id
and gld.account_Class = ''REC''
and gld.latest_Rec_flag = ''Y''
and gld.account_set_flag = ''N''
and not exists
(select ''x'' from ra_customer_trx_lines_all ctlin
where ctlin.customer_trx_id = ctl.customer_trx_Id
and ctlin.line_type = ''TAX''
and ctlin.link_to_cust_Trx_line_id = ctl.customer_trx_line_id
)
and exists
(SELECT * FROM ZX_LINES zl
WHERE zl.application_id = 222
AND zl.entity_code = ''TRANSACTIONS''
AND zl.event_class_code in (''INVOICE'',''DEBIT_MEMO'',''CREDIT_MEMO'')
AND zl.trx_id = ctl.customer_trx_id
AND zl.trx_line_id = ctl.customer_trx_LINE_ID
)
and gld.event_id = xe.event_id
and xe.application_id = 222
and xah.event_id = xe.event_id
and xe.event_status_code = ''P''
and xe.process_status_code = ''P''
and xah.application_id = 222',
      p_title                  => 'Missing Tax in RA_CUSTOMER_TRX_LINES_ALL (AR_00022)',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Transaction is Missing Tax in RA_CUSTOMER_TRX_LINES_ALL',
      p_solution               => '<ul><li>The analyzer has identified data corruption described in [1566061/KB786026]</li>
<li>Please log a Service Request and upload this analyzer output.</li>
</ul>',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '7'
      );
