      p_sig_sql                => 'SELECT CUST_TRX_LINE_GL_DIST_ID
,      CUSTOMER_TRX_LINE_ID
,      CODE_COMBINATION_ID
,      SET_OF_BOOKS_ID
,      LAST_UPDATE_DATE
,      LAST_UPDATED_BY
