,      REQUEST_ID
,      PROGRAM_APPLICATION_ID
,      PROGRAM_ID
,      PROGRAM_UPDATE_DATE
,      CONCATENATED_SEGMENTS
,      ORIGINAL_GL_DATE
,      POST_REQUEST_ID
,      POSTING_CONTROL_ID
,      ACCOUNT_CLASS
,      RA_POST_LOOP_NUMBER
,      CUSTOMER_TRX_ID
,      ACCOUNT_SET_FLAG
