debug('begin add_signature: AR_TRX_AR_00104_MISS_TAX');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '4684',
      p_sig_id                 => 'AR_TRX_AR_00104_MISS_TAX',
      p_sig_sql                => 'select distinct ct.customer_trx_id, gld.event_id , gld.gl_date, ct.exchange_rate 
from   ra_customer_trx_all ct, 
       ra_cust_trx_types_all ctt,
       ra_cust_trx_line_gl_dist_all gld 
WHERE  ct.customer_trx_id = ##$$TRXID$$##
and    ct.customer_trx_id in 
       (SELECT  distinct zl.trx_id 
        FROM    zx_lines zl,
                ra_customer_trx_lines_all lines 
        WHERE   zl.application_id = 222 
        AND     zl.entity_code = ''TRANSACTIONS'' 
        AND     zl.event_class_code IN (''INVOICE'',''DEBIT_MEMO'',''CREDIT_MEMO'') 
        AND     zl.trx_id = lines.customer_trx_id 
        AND     NOT EXISTS (SELECT  zl_in.* 
                            FROM    zx_lines zl_in,
                                    ra_customer_trx_lines_all lines_in 
                            WHERE   zl_in.application_id = 222 
                            AND     zl_in.entity_code = ''TRANSACTIONS'' 
                            AND     zl_in.event_class_code IN (''INVOICE'',''DEBIT_MEMO'',''CREDIT_MEMO'') 
                            AND     zl_in.trx_id = lines_in.customer_trx_id 
                            AND     zl_in.tax_line_id = lines_in.tax_line_id 
                            AND     lines_in.customer_trx_id = lines.customer_trx_id )) 
and   ct.cust_Trx_type_id = ctt.cust_Trx_type_id 
and   ctt.type in (''INV'',''CM'') 
and   ct.customer_trx_id = gld.customer_trx_id 
and   gld.account_set_flag = ''N'' 
and   gld.account_class = ''REC''
and   gld.latest_rec_flag = ''Y''
and   gld.posting_control_id = -3 
AND   NOT EXISTS (select ''x'' 
                  from   ra_cust_trx_line_gl_dist_all gld 
                  where  gld.customer_trx_id = ct.customer_trx_id 
                  and    gld.account_set_flag =''N'' 
                  and    gld.posting_control_id <> -3)',
      p_title                  => 'Missing Tax line in AR but are generated in ZX_LINES (AR_00104)',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Transaction is missing tax lines in AR but tax lines are generated in ZX_LINES.',
      p_solution               => '<ul><li>The analyzer has identified data corruption described in [2060893/KB740174]</li>
<li>Please log a Service Request and upload this analyzer output.</li>
</ul>',
      p_success_msg            => 'Transaction is missing tax lines in AR but tax lines are generated in ZX_LINES.',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '5'
      );
   l_info.delete;
debug('end add_signature: AR_TRX_AR_00104_MISS_TAX');



