              and    gld_unearn.rec_offset_flag = ''Y'' 
              group by gld_unearn.customer_trx_id , gld_unearn.customer_trx_line_id 
              having  sum(gld_unearn.amount) = ctl.extended_amount ) 
  group by ct.customer_trx_id , ctl.customer_trx_line_id, GLD.GL_DATE, GLD.EVENT_ID 
  HAVING ( SUM(GLD.AMOUNT) <> 0 OR sum(gld.acctd_amount) <> 0)',
      p_title                  => 'Revenue Distributions with Incorrect AMOUNT and ACCTD_AMOUNT (AR_00202)',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Transaction has incorrect Revenue AMOUNT and ACCTD_AMOUNT.',
      p_solution               => '<ul><li>The analyzer has identified data corruption described in [1565612/KB730146]</li>
<li>Please log a Service Request and upload this analyzer output.</li>
</ul>',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
