debug('begin add_signature: AR_TRX_AR_00210_CANT_APPLY_UPG');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '4693',
      p_sig_id                 => 'AR_TRX_AR_00210_CANT_APPLY_UPG',
      p_sig_sql                => 'select  ct.customer_trx_id, ct.trx_number, ct.trx_date, 
        ps.amount_due_remaining ps_amount_due_remaining, 
        ps.acctd_amount_due_remaining ps_acctd_amt_due_remaining, 
        a.amount_due_remaining line_amount_due_remaining, a.acctd_amount_due_remaining 
        lines_acctd_amt_due_remaining, 
        ABS (ps.amount_due_remaining - a.amount_due_remaining) difference_amount, 
        ABS (ps.acctd_amount_due_remaining - a.acctd_amount_due_remaining-nvl(gld.acctd_amount, 0)) 
        difference_acctd_amount, 
        ps.invoice_currency_code, ps.gl_date, ps.status, ct.org_id org_id 
 from   ar_payment_schedules_all ps, 
        ra_cust_trx_line_gl_dist_all gld, 
        ra_customer_trx_all ct, (select customer_trx_id, 
                                 sum(amount_due_remaining + nvl(chrg_amount_remaining, 0) + 
                                 nvl(frt_adj_remaining, 0)) amount_due_remaining, 
                                 sum(acctd_amount_due_remaining + nvl(chrg_acctd_amount_remaining, 0) +
                                 nvl(frt_adj_acctd_remaining, 0)) acctd_amount_due_remaining 
                                     from   ra_customer_trx_lines_all 
                                     where  customer_trx_id = customer_trx_id 
                                     GROUP BY customer_trx_id) a 
     where  ct.customer_trx_id = ##$$TRXID$$##
     and    ct.upgrade_method = ''R12''
     and    ct.customer_trx_id = ct.customer_trx_id 
     and    ps.customer_trx_id = ct.customer_trx_id 
     and    ct.customer_trx_id = a.customer_trx_id 
     and    ct.customer_trx_id = gld.customer_trx_id(+) 
     and    gld.account_class(+) = ''ROUND''
     and    ((a.amount_due_remaining is not null 
              and nvl(ps.amount_due_remaining,0) <> nvl(a.amount_due_remaining, 0)) 
             or 
             (a.acctd_amount_due_remaining is not null 
              and nvl(ps.acctd_amount_due_remaining - nvl(gld.acctd_amount,0),0) <> nvl(a.acctd_amount_due_remaining, 0) 
             and ps.acctd_amount_due_remaining <> a.acctd_amount_due_remaining))',
      p_title                  => 'Transaction With Incorrect Line Level Balances  (AR_00210)',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Transaction with incorrect line level balances. ',
      p_solution               => '<ul><li>The analyzer has identified data corruption described in [1464243/KB627869]</li>
<li>Please log a Service Request and upload this analyzer output.</li>
</ul>',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '3'
      );
   l_info.delete;
debug('end add_signature: AR_TRX_AR_00210_CANT_APPLY_UPG');



