debug('begin add_signature: AR_TRX_AR_S_00006_STAMP_POSTED_BUT_ORPHAN');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '4702',
      p_sig_id                 => 'AR_TRX_AR_S_00006_STAMP_POSTED_BUT_ORPHAN',
      p_sig_sql                => 'select 	DISTINCT ct.customer_trx_id customer_trx_id, 
		ct.trx_number trx_number,
		gld.event_id, 
		gld.gl_date,
		ctt.type type
from 	ra_cust_trx_line_gl_dist_all gld,
		ra_customer_trx_all ct,
		ra_cust_trx_types_all ctt
WHERE  ct.customer_trx_id = gld.customer_trx_id
and   	ct.cust_Trx_type_id = ctt.cust_trx_type_id
and   	ctt.type IN(''INV'',''CM'')
and   	gld.posting_control_id <> -3
AND   	gld.account_class = ''REC''
AND   	gld.account_set_flag=''N''
AND     gld.customer_trx_id = ##$$TRXID$$##
And     gld.org_id = ##$$ORGID$$##
AND     gld.latest_rec_flag = ''Y''
and exists
( select ''x'' from xla.xla_events
  where event_id = gld.event_id
  and   event_status_code = ''P''
  and   process_status_code = ''P''
  and application_id =222
  and event_type_code <> DECODE(ctt.type,''INV'',''INV_CREATE'',''CM'',''CM_CREATE'')
and exists
(select ''x'' from xla.xla_events
  where event_id = gld.event_id
  and   event_status_code = ''P''
  and   process_status_code = ''P''
  and application_id =222
  and event_type_code = DECODE(ctt.type,''INV'',''INV_UPDATE'',''CM'',''CM_UPDATE'')
  )
)',
      p_title                  => 'UPDATE Event Exists, but CREATE event is Orphan (AR_S_00006)',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Transaction has INV/CM_UPDATE event processed as first event, and INV/CM_CREATE is orphan.',
      p_solution               => '<ul><li>The analyzer has identified data corruption described in [KB626622]</li>
<li>Please log a Service Request and upload this analyzer output.</li>
</ul>',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '10'
      );
   l_info.delete;
debug('end add_signature: AR_TRX_AR_S_00006_STAMP_POSTED_BUT_ORPHAN');



