debug('begin add_signature: AR_TRX_AR_S_00009_DUP_CM_ENTITIES');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '5729',
      p_sig_id                 => 'AR_TRX_AR_S_00009_DUP_CM_ENTITIES',
      p_sig_sql                => 'select 	distinct ct.customer_trx_id, gld.event_id
from 	ra_cust_trx_types ctt,
	ra_customer_trx ct,
	ra_cust_trx_line_gl_dist gld,
	ar_receivable_applications ra
where 	ct.cust_trx_type_id = ctt.cust_trx_type_id
and 	ctt.type = ''CM''
and 	ct.customer_trx_id = ##$$TRXID$$##
and 	gld.customer_trx_id = ct.customer_trx_id
--and 	ct.created_from =''RAXTRX''
and 	gld.account_set_flag = ''N''
and 	gld.account_class = ''REC''
and 	gld.latest_rec_flag=''Y''
and 	gld.event_id is not null
and 	ra.application_type = ''CM''
and 	ra.posting_control_id = -3
and 	ra.customer_trx_id = ct.customer_trx_id
and 1 < 
	( select count(distinct xe.entity_id)
	  from 	xla_events xe, xla_transaction_entities_upg xte1
	  where	xte1.application_id =222
	  and xe.application_id =222
	  and xe.entity_id = xte1.entity_id
	  and nvl(xte1.source_id_int_1,-99) = ct.customer_trx_id
	  and ct.set_of_books_id = xte1.ledger_id
	  and xte1.entity_code = ''TRANSACTIONS''
)
order by ct.customer_trx_id, gld.event_id',
      p_title                  => 'Duplicate CM Entities (AR_S_00009)',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Credit Memo has duplicate CM Entities in XLA_TRANSACTION_ENTITIES',
      p_solution               => '<ul><li>The analyzer has identified data corruption described in [2213891/KB726183]</li>
<li>Please log a Service Request and upload this analyzer output.</li>
</ul>',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '3'
      );
   l_info.delete;
debug('end add_signature: AR_TRX_AR_S_00009_DUP_CM_ENTITIES');



