debug('begin add_signature: AR_TRX_AR_S_00016_INCORRECT_EXT_AMT_LNS');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '8247',
      p_sig_id                 => 'AR_TRX_AR_S_00016_INCORRECT_EXT_AMT_LNS',
      p_sig_sql                => 'Select  distinct line.customer_trx_id customer_trx_id,line.customer_trx_line_id customer_trx_line_id,
		ra.complete_flag complete_flag, ra.previous_customer_trx_id previous_customer_trx_id, ra.invoicing_rule_id invoicing_rule_id ,
		nvl(ra.EXCHANGE_RATE, 1) exch_rate, ra.org_id org_id, ra.invoice_currency_code currency_code
From    ra_customer_trx_lines_all line,
		ra_customer_trx_all ra,
		ra_cust_trx_types_all type,
		ra_cust_trx_line_gl_dist_all gld
Where   ra.cust_trx_type_id = type.cust_trx_type_id
And     type.type = ''CM''
And     ra.customer_trx_id = line.customer_trx_id
And     line.customer_trx_id = gld.customer_trx_id
And     line.customer_trx_line_id = gld.customer_trx_line_id
And     line.line_type = ''LINE''
And     line.unit_selling_price = 0
And     line.revenue_amount = 0
And     line.extended_amount <> 0
--And    gld.posting_control_id = -3
And    	ra.complete_flag = ''Y''
And    	ra.customer_trx_id = ##$$TRXID$$##
--And   ra.trx_date between l_trx_start_date and l_trx_end_date
And not exists (Select applied_customer_trx_id
    From ar_receivable_applications_all rec_app
    Where rec_app.applied_customer_trx_id = ra.customer_trx_id)
order by customer_trx_id',
      p_title                  => 'Incorrect EXTENDED_AMT in RA_CUSTOMER_TRX_LINES (AR_S_00016)',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Transaction has incorrect extended_amount in RA_CUSTOMER_TRX_LINES',
