debug('begin add_signature: AR_TRX_AR_S_00020_TRX_MISSING_BILL_TO_SITE');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '9485',
      p_sig_id                 => 'AR_TRX_AR_S_00020_TRX_MISSING_BILL_TO_SITE',
      p_sig_sql                => 'SELECT trx.customer_trx_id,
              trx.trx_number,
	   trx.org_id,
       trx.bill_to_customer_id,
       trx.BILL_TO_SITE_USE_ID,
       su.SITE_USE_ID
   FROM RA_CUSTOMER_TRX_ALL trx
       ,RA_CUST_TRX_TYPES_ALL tty
       ,HZ_CUST_ACCOUNTS_ALL ct
       ,HZ_CUST_ACCT_SITES_ALL st
       ,HZ_CUST_SITE_USES_ALL su
   WHERE trx.CUST_TRX_TYPE_ID = tty.CUST_TRX_TYPE_ID
   AND tty.TYPE in (''INV'',''CM'',''DM'',''CB'',''GUAR'',''DEP'')
   AND trx.org_id = tty.org_id
   AND trx.ORG_ID = su.ORG_ID
   AND trx.BILL_TO_CUSTOMER_ID = ct.CUST_ACCOUNT_ID
   AND st.CUST_ACCOUNT_ID = ct.CUST_ACCOUNT_ID
   AND st.CUST_ACCT_SITE_ID = su.CUST_ACCT_SITE_ID
   AND su.STATUS = ''A''
   AND su.PRIMARY_FLAG = ''Y''
   AND su.SITE_USE_CODE = ''BILL_TO''
   And trx.customer_trx_id = ##$$TRXID$$##
   AND trx.ORG_ID = ##$$ORGID$$##
   AND     (
            NOT EXISTS
                    (SELECT  ''x''
                    FROM    hz_cust_site_uses_all stu
                    WHERE   stu.org_id = trx.org_id
                    AND     stu.site_use_id = trx.bill_to_site_use_id
                    AND     status = ''A''
                    )
        OR      EXISTS
                (
                SELECT  1
                FROM    hz_cust_site_uses_all stu
                       ,hz_cust_acct_sites_all act_site
                       ,hz_cust_accounts_all act
                WHERE   stu.org_id = trx.org_id
                AND     act.cust_account_id = trx.bill_to_customer_id
                AND     act_site.cust_account_id <> act.cust_account_id
                AND     stu.cust_acct_site_id = act_site.cust_acct_site_id
                AND     stu.site_use_id = trx.bill_to_site_use_id
                AND     stu.status = ''A''
                )
        )',
      p_title                  => 'Transaction Missing Bill_To_Site_Use_Id (AR_S_00020)',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Transaction is missing bill_to_site_use_id.',
      p_solution               => '<ul><li>The analyzer has identified data corruption described in [1448222/KB719856]</li>
<li>Please log a Service Request and upload this analyzer output.</li>
</ul>',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '7'
      );
   l_info.delete;
debug('end add_signature: AR_TRX_AR_S_00020_TRX_MISSING_BILL_TO_SITE');



