debug('begin add_signature: AR_TRX_AR_S_00023_INCLUDED_IN_NETTING_BATCH');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '10051',
      p_sig_id                 => 'AR_TRX_AR_S_00023_INCLUDED_IN_NETTING_BATCH',
      p_sig_sql                => 'select trx.trx_number TRX_Number,
       trx.customer_trx_id Customer_Trx_Id,
       fnba.batch_name, 
       fnba.batch_number, 
       fnba.batch_status_code
from
  ra_customer_trx_all trx
, ar_payment_schedules_all ps
, fun_net_ar_txns_all fnar
, fun_net_batches_all fnba
where
    trx.customer_trx_id = ps.customer_trx_id
and trx.customer_trx_id = fnar.customer_trx_id
and fnar.batch_id       = fnba.batch_id
and ps.status         = ''OP''
and trx.complete_flag   = ''Y''
and fnba.batch_status_code <> ''CANCELLED''
and fnba.batch_status_code <> ''COMPLETE''
and fnba.batch_status_code <> ''REVERSED''
and trx.customer_trx_id = ##$$TRXID$$##',
      p_title                  => 'Transaction Included in Pending Netting Batch',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'This transaction is currently included in a Netting Batch that has not completed processing yet. This transaction is not eligible for processing in another Netting Batch.',
