debug('begin add_signature: AR_TRX_AR_S_00025_WRONG_SOBID');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '10543',
      p_sig_id                 => 'AR_TRX_AR_S_00025_WRONG_SOBID',
      p_sig_sql                => 'select h.customer_trx_id,
h.trx_number
from ra_customer_trx_all h
where h.customer_trx_id = ##$$TRXID$$##
and exists
(
(select ''1'' from ra_customer_trx_all t , ar_system_parameters_all p
where t.org_id = p.org_id and t.set_of_books_id <> p.set_of_books_id
and t.customer_trx_id = h.customer_trx_id)
union
select ''1'' from ra_customer_trx_lines_all l , ar_system_parameters_all p
where l.org_id = p.org_id and l.set_of_books_id <> p.set_of_books_id
and l.customer_trx_id = h.customer_trx_id
union
select ''1'' from ra_cust_trx_line_gl_dist_all g , ar_system_parameters_all p
where g.org_id = p.org_id and g.set_of_books_id <> p.set_of_books_id
and g.customer_trx_id = h.customer_trx_id
union
select ''1'' from ar_receivable_applications_all r , ar_system_parameters_all p
where r.org_id = p.org_id and r.set_of_books_id <> p.set_of_books_id
and r.applied_customer_trx_id = h.customer_trx_id
union
select ''1'' from ar_receivable_applications_all r , ar_system_parameters_all p
where r.org_id = p.org_id and r.set_of_books_id <> p.set_of_books_id
and r.customer_trx_id = h.customer_trx_id
)',
      p_title                  => 'Transaction with incorrect SOB_ID in AR Tables',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Transaction has incorrect Set_of_books_id in AR table.',
      p_solution               => '<ul><li>The analyzer has identified data corruption described in [2397177/KB748310]</li>
<li>Please log a Service Request and upload this analyzer output.</li>
</ul>',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '2'
      );
   l_info.delete;
debug('end add_signature: AR_TRX_AR_S_00025_WRONG_SOBID');



debug('begin add_signature: AR_TRX_AR_S_00026_APPL_TERM_SEQ');
