debug('begin add_signature: AR_TRX_AR_S_00030_DUP_TAX');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '10870',
      p_sig_id                 => 'AR_TRX_AR_S_00030_DUP_TAX',
      p_sig_sql                => 'select distinct ct.customer_trx_id,ct.trx_number, ctl.customer_trx_line_id, gld.event_id , gld.gl_date,ct.exchange_rate, gld.posting_Control_id
from ra_customer_trx_all ct,
  ra_customer_trx_lines_all ctl,
  ra_cust_trx_types_all ctt ,
  ra_cust_trx_line_gl_dist_all gld
WHERE ct.customer_trx_id =  ##$$TRXID$$##
and ct.customer_trx_id = ctl.customer_Trx_id
and ct.invoicing_rule_id is null
and ctl.line_type = ''LINE''
and ct.cust_Trx_type_id = ctt.cust_Trx_type_id
and ctt.type in(''INV'',''CM'',''DM'')
and ct.customer_trx_id = gld.customer_trx_id
and gld.account_Class = ''REC''
and gld.latest_Rec_flag = ''Y''
and gld.account_set_flag = ''N''
and exists
  (select count(*) -- check for duplicated Tax lines with the same TAX_LINE_ID
  from ra_Customer_trx_lines_all ctlin
  where ctlin.customer_trx_id =ctl.customer_Trx_Id
  and ctlin.line_type = ''TAX''
  and ctlin.link_to_cust_Trx_line_id = ctl.customer_trx_line_id
  and ctl.tax_line_id is not Null -- to exclude the GST Tax rows
  having count(*) > 1
)
and exists
  (SELECT * FROM ZX_LINES zl
  WHERE zl.application_id = 222
  AND zl.entity_code = ''TRANSACTIONS''
  AND zl.event_class_code in (''INVOICE'',''DEBIT_MEMO'',''CREDIT_MEMO'')
  AND zl.trx_id = ctl.customer_trx_id
  AND zl.trx_line_id = ctl.CUSTOMER_TRX_LINE_ID
  )',
      p_title                  => 'Duplicate TAX lines in RA_CUSTOMER_TRX_LINES_ALL (AR_S_00030)',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Transaction has duplicate TAX lines having the same LINK_TO_CUST_TRX_LINE_ID and TAX_LINE_ID in RA_CUSTOMER_TRX_LINES_ALL',
      p_solution               => '<ul><li>The analyzer has identified data corruption described in [2423761/KB754367]</li>
<li>Please log a Service Request and upload this analyzer output.</li>
</ul>',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '8'
      );
   l_info.delete;
debug('end add_signature: AR_TRX_AR_S_00030_DUP_TAX');



debug('begin add_signature: AR_TRX_AR_S_00033_OVERLAP_DISPUTE');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '11594',
      p_sig_id                 => 'AR_TRX_AR_S_00033_OVERLAP_DISPUTE',
      p_sig_sql                => 'SELECT 	p.customer_trx_id, 
        p.trx_number,
        p.class,
        dh.payment_schedule_id ps_id,
       	dh.dispute_history_id  dh_id,
       	dh.start_date,
       	nvl(dh.end_date,sysdate) end_date
FROM  	ar_dispute_history dh,
        ar_payment_schedules_all p
WHERE 	dh.start_date > nvl(dh.end_date,sysdate)
AND     dh.payment_schedule_id = p.payment_schedule_id
AND     p.class not in (''PMT'')
AND   	dh.payment_schedule_id in (select p2.payment_schedule_id
                                   from ar_payment_schedules_all p2
                                   where p2.customer_trx_id = ##$$TRXID$$##)
',
      p_title                  => 'Overlapping Dates on Transaction Dispute',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'The transaction in Disputes table ar_dispute_history table is showing overlapping start and end dates.',
