debug('begin add_signature: AR_TRX_AR_S_00043_INV_NOT_NULL_SEL_BATCH_ID');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '12421',
      p_sig_id                 => 'AR_TRX_AR_S_00043_INV_NOT_NULL_SEL_BATCH_ID',
      p_sig_sql                => 'SELECT  ps.trx_number, ps.payment_schedule_id ,ps.customer_trx_id, ps.selected_for_receipt_batch_id, ps.gl_date, ps.class
FROM    ar_payment_schedules_all ps
WHERE   ps.selected_for_receipt_batch_id IS NOT NULL
AND     ps.selected_for_receipt_batch_id >=0
AND     ps.customer_trx_id = ##$$TRXID$$##
AND     NOT EXISTS
        (SELECT  1
        FROM    ar_receivable_applications_all ra
        WHERE   ra.applied_customer_trx_id = ps.customer_trx_id
         AND     ra.applied_payment_schedule_id = ps.payment_schedule_id
        AND     ra.DISPLAY = ''Y''
        AND     EXISTS
                (SELECT  1
                FROM    ar_cash_receipt_history_all crh
                WHERE   ra.cash_receipt_id = CRH.cash_receipt_id
                AND     crh.batch_id = ps.selected_for_receipt_batch_id))
AND     EXISTS
		(SELECT  1
		FROM    ar_cash_receipt_history_all crh
		WHERE    crh.batch_id = ps.selected_for_receipt_batch_id)				
UNION
SELECT  ps.trx_number, ps.payment_schedule_id ,ps.customer_trx_id, ps.selected_for_receipt_batch_id, ps.gl_date, ps.class
FROM    ar_payment_schedules_all ps
WHERE   ps.selected_for_receipt_batch_id IS NOT NULL
AND     ps.selected_for_receipt_batch_id >=0
AND     ps.customer_trx_id = ##$$TRXID$$##
AND     NOT EXISTS
        (SELECT 1 FROM AR_BATCHES_ALL bat
         WHERE bat.batch_id = ps.selected_for_receipt_batch_id)
UNION
SELECT  ps.trx_number, ps.payment_schedule_id ,ps.customer_trx_id, ps.selected_for_receipt_batch_id, ps.gl_date, ps.class
FROM    ar_payment_schedules_all ps
WHERE   ps.selected_for_receipt_batch_id IS NOT NULL
AND     ps.selected_for_receipt_batch_id >=0
AND     ps.customer_trx_id = ##$$TRXID$$##
AND     ps.status = ''OP''
AND     EXISTS
        (SELECT 1 FROM AR_BATCHES_ALL bat
         WHERE bat.batch_id = ps.selected_for_receipt_batch_id
           AND bat.BATCH_APPLIED_STATUS in (''COMPLETED_APPROVAL'', ''STARTED_FORMAT'',''COMPLETED_FORMAT''))
ORDER BY 4,3',
      p_title                  => 'Payment Schedule With Selected for Receipt Batch Id (AR_S_00043)',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Transaction has payment schedule with selected_for_receipt_batch_id. ',
      p_solution               => '<ul><li>The analyzer has identified data corruption described in [2527837/KB772210]</li>
<li>Please follow the steps provided in the document in a TEST instance with the same data as PROD.  If the issue is resolved, please migrate the solution to the other environments; otherwise, please log a Service Request and upload this Analyzer output</li> </ul>
',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '4'
      );
   l_info.delete;
debug('end add_signature: AR_TRX_AR_S_00043_INV_NOT_NULL_SEL_BATCH_ID');



