                                  WHERE
                                      gld.customer_trx_id     = gldrec.customer_trx_id
                                  AND gldrec.account_class    = ''REC''
                                  AND gldrec.account_set_flag = ''N''
                                  AND gldrec.latest_rec_flag  = ''Y''
                                  )',
