debug('begin add_signature: AR_TRX_AR_S_00055_DUP_UNEARN_RAM');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '14805',
      p_sig_id                 => 'AR_TRX_AR_S_00055_DUP_UNEARN_RAM',
      p_sig_sql                => 'SELECT gld.customer_trx_id, gld.customer_trx_line_id, 
       gld.code_combination_id, gld.amount, 
       gld.acctd_amount, count(*) 
 FROM  ra_customer_trx_all ct, 
       ra_cust_trx_line_gl_dist_all gld 
 WHERE ct.customer_trx_id = ##$$TRXID$$##
 AND   gld.customer_trx_id = ct.customer_trx_id 
 AND   gld.account_class = ''UNEARN''
 AND   gld.rec_offset_flag= ''Y'' 
 AND   gld.ACCOUNT_SET_FLAG = ''N'' 
 AND   gld.POSTING_CONTROL_ID = -3 
 GROUP BY gld.customer_trx_id, gld.customer_trx_line_id, 
          gld.code_combination_id, GLD.AMOUNT, 
          gld.ACCTD_AMOUNT 
 HAVING  count(*) > 1
AND EXISTS
(
SELECT ''x''
FROM ra_cust_trx_line_gl_dist gldin
WHERE gldin.customer_trx_id = gld.customer_trx_id
AND gldin.revenue_adjustment_id IS NOT NULL
)
AND NOT EXISTS
(
SELECT 1
FROM ra_cust_trx_line_gl_dist gldp
WHERE gldp.customer_trx_id = gld.customer_trx_id
AND gldp.account_set_flag = ''N''
AND gldp.posting_control_id <> - 3
)',
      p_title                  => 'Duplicate UNEARN Distributions with RAM (AR_S_00055)',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Transaction has duplicate unearn distributions in RA_CUST_TRX_LINE_GL_DIST_ALL and has revenue_adjustment (RAM).',
      p_solution               => '<ul><li>The analyzer has identified data corruption described in Case 2 in [1569870/KB757706]</li>
