        ar_payment_schedules_all ps
where   ps.customer_trx_id = ra.applied_customer_trx_id
and     ra.applied_customer_trx_id = ##$$TRXID$$##
and     not exists
       (select ''Y''
        from   ar_payment_schedules_all ps2
        where  ra.applied_payment_schedule_id = ps2.payment_schedule_id
        and ps2.customer_trx_id = ra.applied_customer_trx_id)
