debug('begin add_signature: AR_TRX_AR_S_00080_DIFF_ACC_RULE_DUR');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '19089',
      p_sig_id                 => 'AR_TRX_AR_S_00080_DIFF_ACC_RULE_DUR',
      p_sig_sql                => 'SELECT  ctl.customer_trx_id
        ,ct.trx_number
        ,ctl.customer_trx_line_id
       ,ct_inv.accounting_rule_duration
       ,ctl.accounting_rule_duration cm_rule_duration
FROM    ra_customer_trx_lines_all ctl
       ,ra_customer_trx_all ct
       ,ra_customer_trx_lines_all ct_inv
       ,ra_cust_trx_types_all ctt
WHERE   ct.customer_trx_id = ctl.customer_trx_id
AND     ct.customer_trx_id    = ##$$TRXID$$##
AND     ct_inv.customer_trx_id = ctl.previous_customer_trx_id
AND     ct_inv.customer_trx_line_id = ctl.previous_customer_trx_line_id
AND     ctt.cust_trx_type_id = ct.cust_trx_type_id
AND     ctt.type = ''CM''
AND     ct.complete_flag = ''Y''
AND     ctl.line_type = ''LINE''
AND     ctl.accounting_rule_id IS NOT NULL
AND     ctl.autorule_complete_flag = ''N''
AND     ctl.accounting_rule_duration <> ct_inv.accounting_rule_duration
AND     ctl.previous_customer_trx_id IS NOT NULL
AND     ctl.previous_customer_trx_line_id IS NOT NULL
AND     NOT EXISTS
            (
            SELECT  1
            FROM    ra_cust_trx_line_gl_dist_all gld
            WHERE   gld.customer_trx_id = ct.customer_trx_id
            AND     gld.posting_control_id <> - 3
            )
			',
      p_title                  => 'CM Accounting Rule Duration Different from Invoice (AR_S_00080)',
      p_fail_condition         => 'RS',
