      p_sig_repo_id            => '20855',
      p_sig_id                 => 'AR_TRX_AR_S_00086_CM_MISSING_TAX',
      p_sig_sql                => 'select  ct.customer_trx_id, 
        ct.trx_number,
        ctl.customer_trx_line_id,
        ct.previous_customer_trx_id
from    ra_customer_trx_all ct,
        zx_lines zx, 
        ra_cust_trx_types_all ctt,
        ra_customer_trx_lines_all ctl,
        ra_cust_trx_line_gl_dist_all gld
where   ct.cust_trx_type_id = ctt.cust_trx_type_id
and     ct.complete_flag=''Y''
and     ct.previous_customer_trx_id is not null
and     ctt.type = ''CM''
and     ct.customer_trx_id = ctl.customer_trx_id
and     ctl.line_type = ''TAX''
and     ctl.previous_customer_Trx_line_id is null
and     zx.trx_id = ctl.customer_trx_id
and     zx.tax_line_id = ctl.tax_line_id
