debug('begin add_signature: AR_TRX_AR_S_00090_MISMATCH_GL_DATE_IN_GLD_XE');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '21416',
      p_sig_id                 => 'AR_TRX_AR_S_00090_MISMATCH_GL_DATE_IN_GLD_XE',
      p_sig_sql                => 'SELECT  gld.customer_trx_id customer_trx_id, 
        xte.transaction_number trx_number,
        gld.gl_date gl_dist_gl_date,
         xe.event_id event_id,
        xe.event_date xe_event_date,
        gld.account_class account_class,
        gld.cust_trx_line_gl_dist_id cust_trx_line_gl_dist_id,
        gld.org_id org_id,
        gld.posting_control_id posting_control_id ,
        xe.event_status_code event_status_code ,
        xe.process_status_code process_status_code 
FROM    RA_CUST_TRX_LINE_GL_DIST_ALL gld,
        XLA_EVENTS xe,
        XLA_TRANSACTION_ENTITIES_UPG xte
WHERE   gld.customer_trx_id = ##$$TRXID$$##
AND     nvl(xte.source_id_int_1,-99)  = gld.customer_trx_id
AND   xte.entity_code in (''TRANSACTIONS'',''MANUAL'') 
AND     xe.event_id = gld.event_id
AND     gld.account_set_flag = ''N''
AND     trunc(gld.gl_date) <> trunc(xe.event_date)',
      p_title                  => 'Mismatched GL_DATE in RA_CUST_TRX_LINE_GL_DIST_ALL and EVENT_DATE in XLA_EVENTS (AR_S_00090)',
