debug('begin add_signature: AR_TRX_AR_S_00092_INCONSISTENT_REC_REV_GL_DATE');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '21591',
      p_sig_id                 => 'AR_TRX_AR_S_00092_INCONSISTENT_REC_REV_GL_DATE',
      p_sig_sql                => 'select trx.trx_number,
       trx.customer_trx_id,
       trx.invoicing_rule_id,
       gld_rec.gl_date "REC GL_DATE",
       gld_rev.gl_date "REV GL_DATE",
       gld_rec.event_id "REC EVENT_ID",
       gld_rev.event_id "REV EVENT_ID"
from   ra_customer_trx_all trx,
       xla_events xe_rec,
       xla_events xe_rev,
	   ra_cust_trx_line_gl_dist_all gld_rec,
       ra_cust_trx_line_gl_dist_all gld_rev
where  trx.customer_trx_id = ##$$TRXID$$##
and    trx.invoicing_rule_id is NULL
and    trx.customer_trx_id = gld_rec.customer_trx_id
and    trx.customer_trx_id = gld_rev.customer_trx_id
and    gld_rec.account_class = ''REC''
and    trx.invoicing_rule_id is NULL
and    gld_rev.account_class = ''REV''
and    gld_rev.ccid_change_flag is NULL
and    gld_rev.cogs_request_id is NULL
and    not exists (select 1 
                   from   ra_cust_trx_line_gl_dist_all gl_dist 
				   where  account_class = ''UNEARN'' 
				   and    gl_dist.customer_trx_id = trx.customer_trx_id) 
and    gld_rev.gl_date <> gld_rec.gl_date
and    xe_rec.event_date <> xe_rev.event_date
and    xe_rec.event_id = gld_rec.event_id
and    xe_rev.event_id = gld_rev.event_id',
      p_title                  => 'Inconsistent GL_DATE between the REC and REV rows in RA_CUST_TRX_LINE_GL_DIST_ALL for Invoices with no rules',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'There are GL_DATE inconsistencies between the REC row and REV rows for invoices with no rules.',
