debug('begin add_signature: AR_TRX_AR_S_00103_DUP_XLA_AE_HEADERS');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '22394',
      p_sig_id                 => 'AR_TRX_AR_S_00103_DUP_XLA_AE_HEADERS',
      p_sig_sql                => 'SELECT xte.source_id_int_1    customer_trx_id,
       xte.transaction_number TRX_Number,
       ev.event_id,
       ev.event_date, 
       ev.event_type_code,
       ev.event_status_code,
       hdr.ae_header_id duplicate_ae_header_id,
       hdr.accounting_entry_status_code,
       hdr.gl_transfer_status_code,       
       xte.security_id_int_1  org_id
FROM   xla_ae_headers hdr,
       xla_events ev,
       xla_transaction_entities_upg xte
WHERE  xte.application_id = 222
       AND ev.entity_id = xte.entity_id
       AND xte.entity_code = ''TRANSACTIONS''
       AND Nvl(xte.source_id_int_1, -99) = ##$$TRXID$$##
       AND hdr.ledger_id = ##$$LEDGERID$$##
       AND hdr.application_id = ev.application_id
       AND hdr.gl_transfer_status_code = ''N''
       AND hdr.accounting_entry_status_code <> ''F''
       AND ev.event_id = hdr.event_id
       AND ev.event_status_code = ''P''
       AND ev.process_status_code = ''P''
       AND EXISTS (SELECT ''x''
                   FROM   xla_ae_headers hdr1
                   WHERE  hdr1.application_id = 222
                          AND hdr1.event_id = hdr.event_id
                          AND hdr1.ledger_id = hdr.ledger_id
                          AND hdr1.gl_transfer_status_code IN ( ''Y'', ''S'' )
                          AND hdr1.accounting_entry_status_code = ''F'') ',
      p_title                  => 'Duplicate XLA_AE_HEADERS (AR_S_00103)',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Transaction has duplicate record(s) in XLA_AE_HEADERS.',
