debug('begin add_signature: EBS_FIN_AR_TRX_AR_S_00128_CM_REFUND');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '27209',
      p_sig_id                 => 'EBS_FIN_AR_TRX_AR_S_00128_CM_REFUND',
      p_sig_sql                => 'select ct.customer_trx_id, 
            ct.trx_number "Transaction Number",
            ra.receivable_application_id, 
            ra.application_type, 
            ra.amount_applied, 
            ra.apply_date,
            ra.application_ref_type ,
            ra.application_ref_id ,
            ra.application_ref_num
from  ar_receivable_applications_all ra, ra_customer_trx_all ct
 where ra.customer_trx_id = ##$$TRXID$$##
 and  ra.customer_trx_id = ct.customer_trx_id
and   application_type = ''CM''
and   (APPLIED_PAYMENT_SCHEDULE_ID = -8 or APPLICATION_REF_TYPE = ''AP_REFUND_REQUEST'')
and   amount_applied > 0
and   display = ''Y''
and not exists
	 	 (select receivable_application_id from ar_receivable_applications ra1
	 	  where applied_payment_schedule_id = -8
	 	  and application_ref_type = ''AP_REFUND_REQUEST''
	 	  and amount_applied < 0
	 	  and ra1.application_ref_id = ra.application_ref_id)
and ((application_ref_id is null ) or 
         (application_ref_id in
		 (select invoice_id from ap_invoices_all
		  where application_id = 222
		  and product_table = ''AR_RECEIVABLE_APPLICATIONS_ALL''
		  and cancelled_date is NOT NULL
		  AND reference_key1 = ra.receivable_application_id)))',
      p_title                  => 'CM Refund Application With Null Application Attributes (AR_S_00128)',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'CM Refund application with null application_ref_id and/or application_ref_num and/or AP Invoice is Canceled . Error-CANCEL_REFUND is occurring when trying to unapply it.',
      p_solution               => '<ul><li>The analyzer has identified data corruption described in [761993/KB711022]</li>
<li>Please log a Service Request and upload this analyzer output.</li>
</ul>',
      p_success_msg            => '',
