debug('begin add_signature: EBS_FIN_AR_TRX_XLA_GL_XFR_IN_XLA_NOT_IN_GL');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '23208',
      p_sig_id                 => 'EBS_FIN_AR_TRX_XLA_GL_XFR_IN_XLA_NOT_IN_GL',
      p_sig_sql                => 'SELECT h.ledger_id, l.ae_header_id, 
       h.accounting_date, h.period_name, h.entity_id,
       l.gl_sl_link_id, l.gl_sl_link_table
FROM   xla_ae_lines l, xla_ae_headers h 
WHERE  h.ae_header_id in (select h2.ae_header_id
                          from   xla_ae_headers h2
						  where  application_id = 222
						  and    entity_id in (SELECT entity_id
                                               FROM   xla_transaction_entities_upg xte
                                               WHERE  xte.application_id = 222
                                               AND    xte.entity_code in (''TRANSACTIONS'',''MANUAL'')
                                               AND    nvl(source_id_int_1,-99) = ##$$TRXID$$##))
