debug('begin add_signature: EBS_FIN_AR_TRX_AR_S_00130_NORULE_REC_REV_DIFF_EV');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '27256',
      p_sig_id                 => 'EBS_FIN_AR_TRX_AR_S_00130_NORULE_REC_REV_DIFF_EV',
      p_sig_sql                => 'select trx.trx_number,
       trx.customer_trx_id,
       gld_rec.gl_date "REC GL_DATE",
       gld_non_rec.gl_date "NON REC GL_DATE",
       gld_rec.event_id "REC EVENT_ID",
       gld_non_rec.event_id "NON REC EVENT_ID",
      xe_rec.EVENT_STATUS_CODE "REC Event Status",
      xe_rev.EVENT_STATUS_CODE "Non REC Event Status"
from   ra_customer_trx_all trx,
       xla_events xe_rec,
       xla_events xe_rev,
       ra_cust_trx_line_gl_dist_all gld_rec,
       ra_cust_trx_line_gl_dist_all gld_non_rec
where trx.customer_trx_id =  ##$$TRXID$$## 
and   trx.invoicing_rule_id is NULL
and   trx.customer_trx_id = gld_rec.customer_trx_id
and   trx.customer_trx_id = gld_non_rec.customer_trx_id
and   gld_rec.account_class = ''REC''
and   gld_non_rec.account_class <> ''REC''
and   gld_non_rec.ccid_change_flag is NULL
and   trunc(gld_non_rec.gl_date) <> trunc(gld_rec.gl_date)
and   trunc(xe_rec.event_date) <> trunc(xe_rev.event_date)
and   xe_rec.event_id = gld_rec.event_id
and   xe_rev.event_id = gld_non_rec.event_id
and xe_rec.application_id = 222
and xe_rev.application_id = 222
and not exists  ( select 1 from ar_line_conts_all  cont 
where cont.customer_trx_line_id = gld_non_rec.customer_trx_line_id )',
