debug('begin add_signature: AR_TRX_ENTERED_ACCTD_AMT_NOT_SAME_SIDE');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '15953',
      p_sig_id                 => 'AR_TRX_ENTERED_ACCTD_AMT_NOT_SAME_SIDE',
      p_sig_sql                => 'SELECT trx.customer_trx_id,
       trx.trx_number,
       nvl(l.entered_dr,0) ENTERED_DR,
       nvl(l.accounted_dr,0) ACCOUNTED_DR,
       nvl(l.entered_cr,0) ENTERED_CR,
       nvl(l.accounted_cr, 0) ACCOUNTED_CR 
FROM   xla_ae_lines l, 
       xla_ae_headers h,
       xla_transaction_entities_upg xte,
       ra_customer_trx_all trx,
	   ra_cust_trx_types_all ctt
WHERE  xte.security_id_int_1 = 204
AND    xte.ledger_id = 1
AND    xte.application_id = 222
AND    xte.entity_code = ''TRANSACTIONS''
AND    xte.source_id_int_1 = trx.customer_trx_id
AND    trx.cust_trx_type_id = ctt.cust_trx_type_id
AND    ctt.name != ''Projects Invoice''
AND    trx.customer_trx_id = ##$$TRXID$$##
AND    xte.entity_id = h.entity_id
AND    l.application_id = h.application_id 
AND    l.ae_header_id = h.ae_header_id 
AND    h.application_id = 222 
AND    h.ledger_id = 1
AND   l.accounting_class_code not in (''EXCHANGE_GAIN_LOSS'', ''BALANCE'', ''INTRA'', ''ROUNDING'', ''SUSPENSE'', ''CURR_ROUND'')
AND h.accounting_entry_status_code = ''I''
AND    ((sign(nvl(l.entered_dr,0)) <> sign(nvl(l.accounted_dr,0))) 
         or (sign(nvl(l.entered_cr,0)) <> sign(nvl(l.accounted_cr,0)))
       )',
      p_title                  => 'Entered Amount and Accounted Amount are Not on Same Side',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'The entered amount and accounted amount are not on the same side.
',
      p_solution               => '<ul><li>The analyzer has identified data corruption described in [1457829/KB722355].</li>
<li>Please log a Service Request and upload this analyzer output.</li>
</ul>
',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '6'
      );
   l_info.delete;
debug('end add_signature: AR_TRX_ENTERED_ACCTD_AMT_NOT_SAME_SIDE');



