  add_signature(
      p_sig_repo_id            => '27746',
      p_sig_id                 => 'EBS_FIN_AR_TRX_CM_CURR_ROUND',
      p_sig_sql                => 'Select    distinct ra.receivable_application_id receivable_application_id, ct.customer_trx_id  customer_trx_id ,ra.gl_date gl_date , 
