WHERE  a.LINE_TYPE        =''TAX''
AND c.ACCOUNT_SET_FLAG = ''N''
AND c.ACCOUNT_CLASS    = ''REC''
AND c.LATEST_REC_FLAG  = ''Y''
AND a.CUSTOMER_TRX_ID  = c.CUSTOMER_TRX_ID
AND a.CUSTOMER_TRX_ID = ##$$TRXID$$## 
AND NOT EXISTS
(SELECT 1
FROM RA_CUST_TRX_LINE_GL_DIST_ALL d
WHERE a.CUSTOMER_TRX_ID    = d.CUSTOMER_TRX_ID
AND a.CUSTOMER_TRX_LINE_ID = d.CUSTOMER_TRX_LINE_ID
AND d.ACCOUNT_CLASS        = ''TAX''
AND d.account_set_flag = ''N'')
and a.extended_amount <> 0
and a.LINE_TYPE   = ''TAX''',
