debug('begin add_signature: EBS_FIN_AR_TRX_AR_S_00149_MISSING_CMAPP_DISTRIBUTIONS');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '30346',
      p_sig_id                 => 'EBS_FIN_AR_TRX_AR_S_00149_MISSING_CMAPP_DISTRIBUTIONS',
      p_sig_sql                => 'SELECT  ra.receivable_application_id receivable_application_id
       ,ra.customer_trx_id customer_trx_id ,ra.gl_date gl_date, ra.org_id org_id, ra.event_id event_id
FROM    ar_receivable_applications_all ra
WHERE   ra.application_type = ''CM''
AND     ra.posting_control_id = - 3
AND     ra.customer_trx_id = ##$$TRXID$$##
AND     (NOT EXISTS
(
SELECT  1
FROM    ar_distributions_all
WHERE   source_table = ''RA''
AND     source_id = ra.receivable_application_id
)
OR      NOT EXISTS
(
SELECT  sum (nvl (ard.acctd_amount_dr
                 ,0))
       ,sum (nvl (ard.acctd_amount_cr
                 ,0))
FROM    ar_distributions_all ard
WHERE   ard.source_id = ra.receivable_application_id
AND     ard.source_table = ''RA''
GROUP BY ard.source_id
        ,ard.source_table
HAVING  sum (nvl (ard.acctd_amount_dr
                 ,0)) = sum (nvl (ard.acctd_amount_cr
                                 ,0))
)
)
ORDER BY ra.customer_trx_id, ra.receivable_application_id',
      p_title                  => 'Missing or Imbalance Distributions For Credit Memo Application (AR_S_00149)',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Create Accounting is unable to account Credit Memo Application due to Missing or Imbalance Distributions',
      p_solution               => '<ul><li>The analyzer has identified data corruption described in [1604314/KB747092]</li>
