      p_sig_sql                => 'SELECT distinct rule.RULE_ID ,rule.NAME, rule.FREQUENCY,rule.OCCURRENCES,rule.DEFERRED_REVENUE_FLAG,  trxlns.CUSTOMER_TRX_ID, trxlns.CUSTOMER_TRX_LINE_ID, trxlns.LINE_NUMBER, trxlns.EXTENDED_AMOUNT, trxlns.ACCOUNTING_RULE_DURATION , trxlns.RULE_START_DATE , trxlns.AUTORULE_COMPLETE_FLAG , trxlns.AUTORULE_DURATION_PROCESSED , trxlns.RULE_END_DATE 
FROM   RA_RULES rule,
       RA_CUSTOMER_TRX_LINES_ALL trxlns
WHERE  rule.rule_id = trxlns.accounting_rule_id
AND    trxlns.line_type =''LINE''
AND    trxlns.accounting_rule_id is NOT NULL
AND    rule.deferred_revenue_flag =''Y''  
AND trxlns.customer_trx_id =  ##$$TRXID$$##
AND NOT EXISTS 
(  select 1 from  RA_CUST_TRX_LINE_GL_DIST_ALL gld_rev
   where   trxlns.customer_trx_id = gld_rev.customer_trx_id
   and   trxlns.customer_trx_line_id = gld_rev.customer_trx_line_id
   and   gld_rev.account_class = ''REV''
   and   gld_rev.account_set_flag = ''N''
   group by gld_rev.customer_trx_id,gld_rev.customer_trx_line_id
  having sum( gld_rev.amount) = trxlns.EXTENDED_AMOUNT 
) 
ORDER BY trxlns.CUSTOMER_TRX_ID, trxlns.LINE_NUMBER',
      p_title                  => 'Transactions Lines with Deferred Accounting rule where Revenue is not fully recognized',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Transactions Lines with Deferred Accounting rule where Revenue is not fully recognized',
      p_solution               => 'Invoice Lines have Deferred Accounting Rule So  Schedule Revenue via Revenue Accounting Management (RAM) wizard
Responsibility: Receivables Manager
Navigation: Control > Accounting > Revenue Accounting
Refer to [1116934/KB626095]  "section 2.Setting up Invoicing and Accounting Rules"  for more details.',
      p_success_msg            => 'Transactions Lines with Deferred Accounting rule where Revenue is not fully recognized',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '2'
      );
   l_info.delete;
debug('end add_signature: EBS_FIN_AR_TRX_LINES_DEFER_RULE_REV_NOT_RECOG');



debug('begin add_signature: EBS_FIN_AR_TRX_AR_S_00151_MISSING_BR_DIST');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '30350',
      p_sig_id                 => 'EBS_FIN_AR_TRX_AR_S_00151_MISSING_BR_DIST',
      p_sig_sql                => 'select transaction_history_id,customer_trx_id
from ar_transaction_history_all th 
where th.customer_trx_id =  ##$$TRXID$$##
and th.postable_flag = ''Y''
and th.posting_control_id = -3
and  NVL(th.org_id, -99) = ##$$ORGID$$## 
and not exists
( select ''x'' from ar_distributions_all ard
   where ard.source_id = th.transaction_history_id
   and ard.source_table = ''TH'') 
UNION
select transaction_history_id,customer_trx_id
from ar_transaction_history_all thb, ar_distributions_all ardu
where thb.customer_trx_id = ##$$TRXID$$##
and thb.postable_flag = ''Y''
and thb.posting_control_id = -3
and  NVL(thb.org_id, -99) = ##$$ORGID$$## 
and ardu.source_id = thb.transaction_history_id
and ardu.source_table = ''TH''
group by thb.transaction_history_id,thb.customer_trx_id
having sum(nvl(ardu.acctd_amount_dr,0)) <> sum(nvl(ardu.acctd_amount_cr,0))
UNION
select DISTINCT thu.transaction_history_id, thu.customer_trx_id
from ar_transaction_history_all thu, ra_customer_trx_lines_all ctl
where thu.customer_trx_id = ##$$TRXID$$##
and thu.postable_flag = ''Y''
and thu.posting_control_id = -3
and  NVL(thu.org_id, -99) = ##$$ORGID$$## 
and ctl.customer_trx_id = thu.customer_trx_id
and EXISTS
       (SELECT  code_combination_id
        FROM    ar_distributions_all
        WHERE   source_id IN
                (
                SELECT  transaction_history_id
                FROM    ar_transaction_history_all t1
                WHERE   t1.customer_trx_id = ctl.br_ref_customer_trx_id
                )
        AND     source_table = ''TH''
        AND     source_type = ''UNPAIDREC''
        AND     code_combination_id NOT IN
                (
                SELECT  code_combination_id
                FROM    ar_distributions_all
                WHERE   source_id IN
                        (
                        SELECT  transaction_history_id
                        FROM    ar_transaction_history_all t2
                        WHERE   t2.customer_trx_id = ctl.customer_trx_id
                        )
                AND     source_table = ''TH''
                AND     source_type = ''REC''
                AND     amount_cr <> 0
                )
        )',
      p_title                  => 'Missing or Imbalance Distributions For Bills receivable  (AR_S_00151)',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Create Accounting is unable to account Bills Receivable Transactions due to Missing or Imbalance Distributions',
      p_solution               => '<ul>
<li>The analyzer has identified data corruption described in [1518842/KB709427]</li> <li>Please follow the steps provided in the document in a TEST instance with the same data as PROD. If the issue is resolved, please migrate the solution to the other environments; otherwise, please log a Service Request and upload this Analyzer output</li>
</ul>',
      p_success_msg            => 'Create Accounting is unable to account Bills Receivable Transactions due to Missing or Imbalance Distributions',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '2'
      );
   l_info.delete;
debug('end add_signature: EBS_FIN_AR_TRX_AR_S_00151_MISSING_BR_DIST');



debug('begin add_signature: EBS_FIN_AR_TRX_SALESPER_DT_NOT_PER_ASSGN_DT');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '31222',
      p_sig_id                 => 'EBS_FIN_AR_TRX_SALESPER_DT_NOT_PER_ASSGN_DT',
      p_sig_sql                => 'SELECT DISTINCT TRX.CUSTOMER_TRX_ID , TRX.PRIMARY_SALESREP_ID , TRX.TRX_DATE,
SR.START_DATE_ACTIVE,SR.END_DATE_ACTIVE, SR_PER.PERSON_ID, SR_PER.EFFECTIVE_START_DATE,SR_PER.EFFECTIVE_END_DATE
FROM RA_CUSTOMER_TRX_ALL TRX,
RA_CUST_TRX_TYPES_ALL TT,
RA_CUSTOMER_TRX_LINES_ALL LINES,
AR_SYSTEM_PARAMETERS_ALL AR,
FND_CURRENCIES CUR,
HZ_CUST_ACCOUNTS BILL_CUST,
HZ_PARTIES BILL_PARTY,
HZ_CUST_ACCT_SITES_ALL BILL_AS,
HZ_CUST_SITE_USES_ALL BILL_SU,
HZ_PARTY_SITES BILL_PS,
HR_ALL_ORGANIZATION_UNITS HR,
HR_ORGANIZATION_UNITS HRL,
JTF_RS_SALESREPS SR,
PER_ALL_ASSIGNMENTS_F SR_PER,
HR_ORGANIZATION_UNITS SR_HRL
WHERE TRX.CUSTOMER_TRX_ID = ##$$TRXID$$##
AND LINES.CUSTOMER_TRX_ID = TRX.CUSTOMER_TRX_ID
AND LINES.LINE_TYPE IN (''LINE'',''CB'')
AND TRX.ORG_ID = AR.ORG_ID
AND TRX.CUST_TRX_TYPE_ID = TT.CUST_TRX_TYPE_ID
AND TRX.ORG_ID = TT.ORG_ID
AND TRX.INVOICE_CURRENCY_CODE = CUR.CURRENCY_CODE
AND TRX.BILL_TO_CUSTOMER_ID = BILL_CUST.CUST_ACCOUNT_ID
AND BILL_CUST.PARTY_ID = BILL_PARTY.PARTY_ID
AND BILL_CUST.CUST_ACCOUNT_ID = BILL_AS.CUST_ACCOUNT_ID
AND BILL_AS.CUST_ACCT_SITE_ID = BILL_SU.CUST_ACCT_SITE_ID
AND BILL_SU.SITE_USE_ID = TRX.BILL_TO_SITE_USE_ID
AND BILL_AS.PARTY_SITE_ID = BILL_PS.PARTY_SITE_ID
AND LINES.WAREHOUSE_ID = HR.ORGANIZATION_ID (+)
AND TRX.ORG_ID = HRL.ORGANIZATION_ID
AND TRX.PRIMARY_SALESREP_ID = SR.SALESREP_ID (+)
AND TRX.ORG_ID = SR.ORG_ID (+)
AND SR.PERSON_ID = SR_PER.PERSON_ID (+)
AND TRX.TRX_DATE NOT BETWEEN NVL(SR_PER.EFFECTIVE_START_DATE,TRX.TRX_DATE) AND NVL(SR_PER.EFFECTIVE_END_DATE,TRX.TRX_DATE)
AND NVL(SR_PER.PRIMARY_FLAG,''Y'') = ''Y''
AND SR_PER.ASSIGNMENT_TYPE (+) = ''E''
AND SR_PER.ORGANIZATION_ID = SR_HRL.ORGANIZATION_ID (+)',
      p_title                  => 'Transaction Date is not between Salesperson Employee Assignment Effective Start Date and End Date',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Transaction Date is not between Salesperson''s Employee Assignment Effective Start Date and End Date in per_all_assignments_f',
      p_solution               => '<ul><li>The analyzer has identified data corruption described in [2757171/KB780829]</li>
<li>Please log a Service Request and upload this analyzer output.</li>
</ul>',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '1'
      );
   l_info.delete;
debug('end add_signature: EBS_FIN_AR_TRX_SALESPER_DT_NOT_PER_ASSGN_DT');



debug('begin add_signature: EBS_FIN_AR_TRX_ENTRIES_NOT_TRANSFER');
