    (SELECT entity_id
    FROM   xla_transaction_entities_upg xte
    WHERE  xte.application_id = 222
    AND  ((xte.entity_code in (''BILLS_RECEIVABLE'',''MANUAL'') and ''##$$TYPE$$##'' = ''BR'') 
    OR
         (xte.entity_code in (''TRANSACTIONS'',''MANUAL'') and ''##$$TYPE$$##''  <> ''BR'') )
    AND  nvl(source_id_int_1,-99) = ##$$TRXID$$##)
GROUP BY ledger_id, event_id
