debug('begin add_signature: EBS_FIN_AR_TRX_AR_S_00141_MUL_INV_CREATE');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '29623',
      p_sig_id                 => 'EBS_FIN_AR_TRX_AR_S_00141_MUL_INV_CREATE',
      p_sig_sql                => 'SELECT xe.event_type_code,
       xte.source_id_int_1       customer_trx_id,
       Count(xe.event_type_code) count
FROM   xla_events xe,
       xla_transaction_entities_upg xte
WHERE  xe.application_id = 222
       AND xe.application_id = xte.application_id
       AND xe.entity_id = xte.entity_id
       AND ( ( xte.entity_code IN ( ''BILLS_RECEIVABLE'', ''MANUAL'' )
               AND ''INV'' = ''BR'' )
              OR ( xte.entity_code IN ( ''TRANSACTIONS'', ''MANUAL'' )
                   AND ''INV'' <> ''BR'' ) )
       AND nvl(xte.source_id_int_1 ,-99) = ##$$TRXID$$##
       AND xe.event_type_code = ''INV_CREATE''
GROUP  BY xe.event_type_code,
          xte.source_id_int_1
HAVING Count(xe.event_type_code) > 1  ',
      p_title                  => 'Multiple EVENT_TYPE_CODE as "INV_CREATE" ',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Multiple EVENT_TYPE_CODE as INV_CREATE are found on this Transaction',
      p_solution               => '<ul><li>The analyzer has identified data corruption described in [3032776/KB710514].</li>
<li>Please log a Service Request and upload the Transaction Analyzer output.</li>
</ul>',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '4'
      );
   l_info.delete;
debug('end add_signature: EBS_FIN_AR_TRX_AR_S_00141_MUL_INV_CREATE');



