debug('begin add_signature: AR_TRX_AR_00057_ORPHAN_XLA');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '4682',
      p_sig_id                 => 'AR_TRX_AR_00057_ORPHAN_XLA',
      p_sig_sql                => 'select xte.source_id_int_1 customer_trx_id, xte.transaction_number TRX_Number, xte.entity_id, xe.event_id, xe.event_date, xe.event_type_code, xe.event_status_code, xte.ledger_id
from xla_events xe, xla_transaction_entities_upg xte
where xte.entity_code = ''TRANSACTIONS''
and xte.entity_id = xe.entity_id
and xte.application_id = 222
and xe.application_id = 222
and xe.event_status_code  <>  ''P'' 
and xe.process_status_code <> ''P''
and xte.source_id_int_1 = ##$$TRXID$$##
and not exists
(
SELECT ct.customer_trx_id, ct.trx_number, ct.org_id
FROM ra_cust_trx_line_gl_dist_all gld,
ra_customer_trx_all ct
WHERE ct.customer_trx_id = xte.source_id_int_1
AND gld.account_class = ''REC''
AND gld.latest_rec_flag = ''Y''
AND gld.account_set_flag = ''Y''
AND ct.customer_trx_id = gld.customer_trx_id
AND ct.complete_flag = ''Y''
)
and not exists
(select ''x'' from ra_cust_Trx_line_gl_dist_all
where customer_trx_id = xte.source_id_int_1
and posting_control_id = -3
and event_id = xe.event_id
union
select ''x'' from ar_receivable_applications_all
where customer_trx_id = xte.source_id_int_1
and posting_control_id = -3
and event_id = xe.event_id
union
select ''x'' from ar_receivable_applications_all
where applied_customer_trx_id = xte.source_id_int_1
and posting_control_id = -3
and event_id = xe.event_id
)
order by xe.event_id',
      p_title                  => 'Orphans in  XLA_EVENTS (AR_00057)',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Orphan record in XLA_EVENTS.',
      p_solution               => '<ul><li>The analyzer has identified data corruption described in [549020/KB627319]</li>
<li>Check if transaction exist and event needs to be populated in AR table if event_id is null.</li>
<li>Please log a Service Request and upload this analyzer output.</li>
</ul>',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '17'
      );
   l_info.delete;
debug('end add_signature: AR_TRX_AR_00057_ORPHAN_XLA');



