debug('begin add_signature: AR_GEN_GL_ACCT_SECURITY_RULES');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '7169',
      p_sig_id                 => 'AR_GEN_GL_ACCT_SECURITY_RULES',
      p_sig_sql                => 'SELECT frt.responsibility_name,
   frt.responsibility_id,
   ifs.id_flex_num Chart_of_accounts_id,
   ifs.segment_name,
   ifs.segment_num,
   fvr.flex_value_rule_name,
   DECODE(fvrl.include_exclude_indicator,
           ''E'', ''Exclude'',
           ''I'', ''Include'',
           ''Error'') Inc_exc,
   fvrl.flex_value_low,
   fvrl.flex_value_high,
   fvrl.creation_date,
   fvrl.last_update_date
FROM fnd_flex_value_rule_usages fvru,
   fnd_flex_value_rules fvr,
