debug('begin add_signature: EBS_FIN_AR_KEY_FLEX_INFO');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '30478',
      p_sig_id                 => 'EBS_FIN_AR_KEY_FLEX_INFO',
      p_sig_sql                => 'SELECT
    seg.id_flex_code,
    seg.segment_num,
    seg.segment_name,
    seg.application_column_name,
    val.segment_attribute_type,
    val.attribute_value,
    seg.enabled_flag,
    required_flag,
    display_flag,
    flex_value_set_name,
    seg.flex_value_set_id,
    seg.security_enabled_flag,
    freeze_flex_definition_flag,
    stru.dynamic_inserts_allowed_flag,
    stru.cross_segment_validation_flag
FROM
    fnd_id_flex_segments_vl      seg,
    fnd_flex_value_sets          sets,
    fnd_segment_attribute_values val,
    gl_ledgers                     gl,
    fnd_id_flex_structures_vl    stru
WHERE   seg.flex_value_set_id = sets.flex_value_set_id (+)
    AND seg.id_flex_code = val.id_flex_code (+)
    AND seg.id_flex_num = val.id_flex_num (+)
    AND seg.application_column_name = val.application_column_name (+)
    AND val.attribute_value (+) = ''Y''
    AND val.segment_attribute_type (+) <> ''GL_GLOBAL''
    AND seg.id_flex_num = gl.chart_of_accounts_id
    and gl.ledger_id = ##$$LEDGERID$$##
    and seg.id_flex_code = ''GL#''
    AND stru.id_flex_code = seg.id_flex_code
    AND stru.id_flex_num = seg.id_flex_num
    AND stru.application_id = seg.application_id
ORDER BY
    seg.id_flex_code,
    seg.segment_num',
      p_title                  => 'Key Flexfield Information',
      p_fail_condition         => 'NRS',
      p_problem_descr          => 'Key Flexfield Information not found.',
      p_solution               => 'This is a data collection of Key Flexfield Information',
      p_success_msg            => 'This is a data collection of Key Flexfield Information',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '1'
      );
   l_info.delete;
debug('end add_signature: EBS_FIN_AR_KEY_FLEX_INFO');



