debug('begin add_signature: AR_GEN_SLAM_REPORTING_LEDGER');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '22459',
      p_sig_id                 => 'AR_GEN_SLAM_REPORTING_LEDGER',
      p_sig_sql                => 'SELECT DISTINCT
    gl.ledger_id,
    gl.name "Ledger Name",
    glr.target_ledger_category_code,
    aad.accounting_method_code                                  slam_code,
    substr(rpad(aad.accounting_method_type_code, 8, '' ''), 1, 8) slam_type,
    aad.product_rule_code                                       aad_code,
    aad.product_rule_name                                       aad_name,
    to_char(aad.start_date_active, ''DD-MON-YYYY'')               start_date,
    to_char(aad.end_date_active, ''DD-MON-YYYY'')                 end_date,
    aad.acctg_method_rule_id                                    rule_id,
    substr(rpad(aad.product_rule_type_code, 8, '' ''), 1, 8)      aad_type,
    to_char(aad.last_update_date, ''DD-MON-YYYY HH24:MI:SS'')     last_update_date,
    to_char(aad.creation_date, ''DD-MON-YYYY HH24:MI:SS'')        creation_date,
    aad.application_id                                          app,
    aad.last_updated_by,
    aad.created_by
FROM   xla_acctg_method_rules_fvl aad,
              gl_ledgers                 gl,
              gl_ledger_relationships    glr
WHERE aad.application_id = 222
    AND  aad.accounting_method_code = gl.sla_accounting_method_code
    AND glr.primary_ledger_id = ##$$LEDGERID$$##
    AND glr.target_ledger_category_code <> ''PRIMARY''
    AND glr.target_ledger_id = gl.ledger_id
ORDER BY gl.ledger_id,
         glr.target_ledger_category_code,
         start_date',
      p_title                  => 'SLAM for Reporting Ledger(s)',
      p_fail_condition         => 'NRS',
      p_problem_descr          => 'Subledger Accounting Method (SLAM) for Reporting Ledger(s)',
      p_solution               => 'No Subledger Accounting Method defined for Reporting Ledger(s)',
      p_success_msg            => 'This is a data collection of Subledger Accounting Method (SLAM) for the Reproting Ledger(s).',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '1'
      );
   l_info.delete;
debug('end add_signature: AR_GEN_SLAM_REPORTING_LEDGER');



debug('begin add_signature: AR_GEN_AAD_PRIMARY_LEDGER');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '2934',
      p_sig_id                 => 'AR_GEN_AAD_PRIMARY_LEDGER',
      p_sig_sql                => 'select PRODUCT_RULE_CODE, 
       NAME, 
       to_char(CREATION_DATE,''DD-MON-YYYY HH24:MI:SS'') creation_date ,
       to_char(LAST_UPDATE_DATE,''DD-MON-YYYY HH24:MI:SS'') last_update,
       decode(COMPILE_STATUS_CODE,''Y'',''Compiled'',
                                  ''N'',''Not Compiled'',
                                  ''I'',''Invalid'',
                                  ''R'',''Validating'',
                                  ''Invalid - ''||COMPILE_STATUS_CODE) STATUS_CODE,
       ''XLA_00222_AAD_''|| PRODUCT_RULE_TYPE_CODE ||''_00000''|| PRODUCT_RULE_HASH_ID ||''_PKG'' AAD_Package,    
       PRODUCT_RULE_HASH_ID,
       ENABLED_FLAG,
       PRODUCT_RULE_TYPE_CODE,
       CREATED_BY,
       LAST_UPDATED_BY
from   xla_product_rules_fvl 
where  application_id = 222
and    (PRODUCT_RULE_CODE, amb_context_code) in 
         (SELECT PRODUCT_RULE_CODE, amb_context_code
          FROM   xla_acctg_method_rules_fvl
          WHERE upper(APPLICATION_NAME)=''RECEIVABLES''
          and   START_DATE_ACTIVE <= sysdate
          and   nvl(END_DATE_ACTIVE, sysdate) >= sysdate
          and   ACCOUNTING_METHOD_CODE in (select SLA_ACCOUNTING_METHOD_CODE 
                                           from   gl_ledgers 
                                           where  LEDGER_ID = ##$$LEDGERID$$##))
order by 6',
      p_title                  => 'AAD for Primary Ledger',
      p_fail_condition         => 'NRS',
      p_problem_descr          => 'Application Accounting Definitions (AAD) for Primary Ledger.',
      p_solution               => 'No Application Accounting Definitions Identified for Primary Ledger',
      p_success_msg            => 'This is a data collection of application accounting definitions (AAD) for the Primary Ledger.',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '6'
      );
   l_info.delete;
debug('end add_signature: AR_GEN_AAD_PRIMARY_LEDGER');



debug('begin add_signature: AR_GEN_AAD_REPORTING_LEDGERS');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '22461',
      p_sig_id                 => 'AR_GEN_AAD_REPORTING_LEDGERS',
      p_sig_sql                => 'SELECT
    gl.ledger_id,
    gl.name "Ledger Name",
    glr.target_ledger_category_code,
    slam.accounting_method_code   slam_code,
    aad.product_rule_code aad_code,
    aad.name aad_name,
    TO_CHAR(slam.start_date_active, ''DD-MON-YYYY'') start_date,
    TO_CHAR(slam.end_date_active, ''DD-MON-YYYY'') end_date,
    DECODE(aad.compile_status_code, ''Y'', ''Compiled'', ''N'', ''Not Compiled'', ''I'', ''Invalid'', ''R'', ''Validating'', ''Invalid - '' || compile_status_code
    ) status_code,
    ''XLA_00222_AAD_''
    || aad.product_rule_type_code
    || ''_00000''
    || aad.product_rule_hash_id
    || ''_PKG'' aad_package,
    aad.product_rule_hash_id,
    aad.enabled_flag,
    aad.product_rule_type_code,
    TO_CHAR(aad.creation_date, ''DD-MON-YYYY HH24:MI:SS'') creation_date,
    TO_CHAR(aad.last_update_date, ''DD-MON-YYYY HH24:MI:SS'') last_update,
    aad.created_by,
    aad.last_updated_by
FROM
    xla_product_rules_fvl aad,
    xla_acctg_method_rules_fvl slam,
    gl_ledgers gl,
    gl_ledger_relationships glr
WHERE
    slam.application_id = aad.application_id
    AND aad.application_id = 222
    AND slam.accounting_method_code = gl.sla_accounting_method_code
    AND glr.primary_ledger_id = ##$$LEDGERID$$##
    AND glr.target_ledger_category_code <> ''PRIMARY''
    AND glr.target_ledger_id = gl.ledger_id
    AND aad.product_rule_code = slam.product_rule_code
    AND aad.amb_context_code = slam.amb_context_code
order by ledger_id, slam.start_date_active asc',
      p_title                  => 'AAD for Reporting Ledger(s)',
      p_fail_condition         => 'NRS',
      p_problem_descr          => 'Application Accounting Definitions (AAD) for Reporting Ledger(s).',
      p_solution               => 'No Application Accounting Definitions Identified for Reporting Ledger(s).',
      p_success_msg            => 'This is a data collection of application accounting definitions (AAD) for the Reporting Ledger(s).',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '1'
      );
   l_info.delete;
debug('end add_signature: AR_GEN_AAD_REPORTING_LEDGERS');



debug('begin add_signature: AR_GEN_INVALID_AAD');
