      p_sig_sql                => 'SELECT distinct gps.application_id, gps.set_of_books_id, gps.closing_status,
           gps.period_year, gps.period_name, gps.start_date, gps.end_date,
           to_char(gps.last_update_date,''DD-MON-YYYY HH24:MI:SS'') last_update_date
    FROM   GL_PERIOD_STATUSES gps,
           AR_SYSTEM_PARAMETERS_ALL sys,
          (SELECT distinct gl_date
            FROM   ra_cust_trx_line_gl_dist_all
            WHERE  customer_trx_id = ##$$TRXID$$##
           union
         SELECT distinct gl_date
          FROM   ar_receivable_applications_all
          WHERE  customer_trx_id = ##$$TRXID$$##) atg_date
     WHERE    period_year in (select period_year
                              from   gl_period_statuses gps2
                              where  atg_date.gl_date between gps2.start_date and gps2.end_date)
     AND      NVL(sys.org_id, -99) = (select org_id
                                      from   ra_customer_trx_all
                                      where  customer_trx_id = ##$$TRXID$$##)
     AND      gps.set_of_books_id in (select distinct a.target_ledger_id ledger_id
                                      from gl_ledger_relationships a,
                                           gl_ledgers b
                                      where ledger_id = ##$$LEDGERID$$##
                                      and a.primary_ledger_id = b.ledger_id)
     AND      gps.application_id = 101
     AND nvl(adjustment_period_flag,''N'') = ''N''
    ORDER BY 1 desc, 2 asc, 6 asc',
      p_title                  => 'Period Information for GL',
      p_fail_condition         => 'NRS',
      p_problem_descr          => 'Period statuses for this transaction in GL_PERIOD_STATUSES for GL (application_id = 101).',
      p_solution               => 'No GL (application_id = 101) data found in GL_PERIOD_STATUSES for this transaction.',
      p_success_msg            => '',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '6'
      );
   l_info.delete;
debug('end add_signature: AR_TRX_GL_GL PERIOD_STATUSES');



debug('begin add_signature: AR_TRX_COMPARE_GL_PERIOD_STATUSES');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '19635',
      p_sig_id                 => 'AR_TRX_COMPARE_GL_PERIOD_STATUSES',
      p_sig_sql                => 'SELECT distinct gps.period_name PERIOD_NAME, gps.period_year YEAR, gps.start_date START_GL_DATE, 
                gps.end_date END_GL_DATE, gps.set_of_books_id SET_OF_BOOKS_ID, 
                gps.closing_status AR_PERIOD_STATUS,gps2.closing_status GL_PERIOD_STATUS, 
                to_char(gps.last_update_date,''DD-MON-YYYY HH24:MI:SS'') AR_LAST_UPDATED, 
                to_char(gps2.last_update_date,''DD-MON-YYYY HH24:MI:SS'') GL_LAST_UPDATED
    FROM   GL_PERIOD_STATUSES gps,
           AR_SYSTEM_PARAMETERS_ALL sys,
           GL_PERIOD_STATUSES gps2,
           AR_SYSTEM_PARAMETERS_ALL sys2,
          (SELECT   distinct gl_date
           FROM     ra_cust_trx_line_gl_dist_all
           WHERE    customer_trx_id = ##$$TRXID$$##
           AND posting_control_id = -3) atg_date 
    WHERE  gps.period_year in (select period_year
                              from   gl_period_statuses gps2
                              where  atg_date.gl_date between gps2.start_date and gps2.end_date)
     AND      NVL(sys.org_id, -99) = (select org_id
                                      from   ra_customer_trx_all
                                      where  customer_trx_id = ##$$TRXID$$##)
     AND      gps.set_of_books_id = ##$$LEDGERID$$##
     AND      gps.application_id = 222
     AND      gps2.application_id = 101
     AND      nvl(gps.adjustment_period_flag,''N'') = ''N''
     AND      gps.set_of_books_id = gps2.set_of_books_id
     AND      gps.period_name = gps2.period_name
     AND      gps.start_date = gps2.start_date
     AND      gps.end_date = gps2.end_date
     AND      gps2.closing_status = ''C''
     AND      gps.closing_status in (''O'', ''W'')
    ORDER BY gps.set_of_books_id asc, gps.start_date asc',
      p_title                  => 'Inconsistent GL Period Status Between AR and GL',
      p_fail_condition         => '[AR_PERIOD_STATUS] <> [GL_PERIOD_STATUS]',
      p_problem_descr          => 'GL period statuses for this transaction are inconsistent between AR  and GL.
',
      p_solution               => 'Please verify that the GL period status in AR and GL are consistent, otherwise you may encounter issues when trying to close the period.',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '8'
      );
   l_info.delete;
debug('end add_signature: AR_TRX_COMPARE_GL_PERIOD_STATUSES');



