debug('begin add_signature: AR_GEN_PROFILES');
   l_info('##MASK##LEVEL VALUE'):= 'NO_MASK';
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '5868',
      p_sig_id                 => 'AR_GEN_PROFILES',
      p_sig_sql                => 'SELECT user_profile_option_name "Profile Option",
a.profile_option_value "Profile Value",
DECODE(a.level_id, 10001, ''Site'',
10002, ''Application'',
10003, ''Responsibility'',
10004, ''User'') "Level",
DECODE(a.level_id, 10001, ''Site'', 
                   10002, b.application_short_name, 
                   10003, c.responsibility_name, 
                   10004, ##$$A$$##.mask_text(d.user_name,''##$$M$$##'')) "Level Value",
c.responsibility_id
FROM 
  fnd_profile_options e
  INNER JOIN fnd_profile_options_tl t ON t.profile_option_name = e.profile_option_name AND t.LANGUAGE = ''US''
  LEFT JOIN fnd_profile_option_values a ON e.application_id = a.application_id AND e.profile_option_id = a.profile_option_id
  LEFT JOIN fnd_application b ON a.level_value = b.application_id
  LEFT JOIN fnd_responsibility_tl c ON a.level_value = c.responsibility_id AND nvl(c.LANGUAGE,''US'') = ''US''
  LEFT JOIN fnd_user d ON a.level_value = d.user_id
WHERE 
  ((e.application_id in (222,7003))
   or (t.user_profile_option_name in (''GL: Data Access Set'', ''SLA: Additional Data Access Set'',
       ''SLA: Enable Data Access Set Security in Subledger'')))
  AND ((a.level_id = 10003 AND a.level_value = ##$$RESP_ID$$##)
       OR (a.level_id = 10004 AND d.user_name = ''##$$USERNAME$$##'')
       OR (a.level_id = 10001 )
       OR (a.level_id = 10002 )
       OR a.level_id IS NULL)
ORDER BY 
  e.profile_option_name,
  a.level_id DESC',
      p_title                  => 'AR Profile Options',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'This is a data collection of settings for AR system profile options.',
      p_solution               => '',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '15'
      );
   l_info.delete;
debug('end add_signature: AR_GEN_PROFILES');



debug('begin add_signature: EBS_FIN_AR_GEN_MOAC');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '22835',
      p_sig_id                 => 'EBS_FIN_AR_GEN_MOAC',
      p_sig_sql                => 'select decode(to_char(pov.level_id),''10001'', ''Site'',''10002'', ''Application'',''10003'', ''Responsibility'', ''10004'', ''User'', ''10005'', ''Server'',''10006'', ''Org'',''10007'', ''Servresp'', ''???'') "Level" ,
       decode(to_char(pov.level_id),''10001'', ''Site'',
              ''10002'', nvl(app.application_short_name,to_char(pov.level_value)),''10003'', nvl(rsp.responsibility_name,to_char(pov.level_value)),
			  ''10004'', nvl(usr.user_name, to_char(pov.level_value)),
              ''10005'', svr.node_name,''10006'', org.name,''10007'', pov.level_value ||'', ''|| pov.level_value_application_id ||'', ''|| pov.level_value2,''???'') "Context", 
        n.user_profile_option_name "Profile Option",
        pov.profile_option_value "Profile Value"
        from   fnd_profile_options po,
               fnd_profile_option_values pov,
               fnd_profile_options_tl n,
               fnd_user usr,fnd_application app,fnd_responsibility_vl rsp,fnd_nodes svr,hr_operating_units org
        where  po.profile_option_name in (''ORG_ID'', ''DEFAULT_ORG_ID'', ''XLA_MO_SECURITY_PROFILE_LEVEL'')
        and    pov.application_id = po.application_id
        and    po.profile_option_name = n.profile_option_name
        and    pov.profile_option_id = po.profile_option_id
        and    usr.user_id (+) = pov.level_value
        and    rsp.application_id (+) = pov.level_value_application_id
        and    rsp.responsibility_id (+) = pov.level_value
        and    app.application_id (+) = pov.level_value
        and    svr.node_id (+) = pov.level_value
        and    svr.node_id (+) = pov.level_value2
        and    org.organization_id (+) = pov.level_value
	    and    n.language=''US''
        and (pov.level_id in (10001, 10004, 10005,10006,10007) or ( pov.level_id=10003 and rsp.APPLICATION_ID in (222)) or ( pov.level_id=10002 and app.APPLICATION_ID in (222)))
        order by pov.level_id,"Context", "Profile Option"',
      p_title                  => 'MOAC Setup for Receivables',
      p_fail_condition         => 'NRS',
      p_problem_descr          => 'This is a data collection of settings for MOAC (Receivables only)',
      p_solution               => '',
      p_success_msg            => '',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '3'
      );
   l_info.delete;
debug('end add_signature: EBS_FIN_AR_GEN_MOAC');



debug('begin add_signature: AR_GEN_AR_INVALIDS');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '1443',
      p_sig_id                 => 'AR_GEN_AR_INVALIDS',
      p_sig_sql                => 'SELECT a.object_name,
           decode(a.object_type,
             ''PACKAGE'', ''Package Spec'',
             ''PACKAGE BODY'', ''Package Body'',
             a.object_type) type,
           (
             SELECT ltrim(rtrim(substr(substr(c.text, instr(c.text,''Header: '')),
               instr(substr(c.text, instr(c.text,''Header: '')), '' '', 1, 1),
               instr(substr(c.text, instr(c.text,''Header: '')), '' '', 1, 2) -
               instr(substr(c.text, instr(c.text,''Header: '')), '' '', 1, 1)
               ))) || '' - '' ||
               ltrim(rtrim(substr(substr(c.text, instr(c.text,''Header: '')),
               instr(substr(c.text, instr(c.text,''Header: '')), '' '', 1, 2),
               instr(substr(c.text, instr(c.text,''Header: '')), '' '', 1, 3) -
               instr(substr(c.text, instr(c.text,''Header: '')), '' '', 1, 2)
               )))
             FROM dba_source c
             WHERE c.owner = a.owner
             AND   c.name = a.object_name
             AND   c.type = a.object_type
             AND   c.line = 2
             AND   c.text like ''%$Header%''
           ) "File Version",
           b.text "Error Text"
    FROM dba_objects a,
         dba_errors b
    WHERE a.object_name = b.name(+)
    AND a.object_type = b.type(+)
    AND a.owner = ''APPS''
    AND (a.object_name like ''AR%'')
    AND a.status = ''INVALID''',
      p_title                  => 'Accounts Receivable (AR) Invalid PL/SQL Packages',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'There are invalid Accounts Receivable (AR) PL/SQL packages.',
      p_solution               => 'The invalid objects are listed for information only.  They may not impact your task, but it is advisable to review and address them as follows:
<ul>
      <li>Review any error messages provided</li>
      <li>Recompile the individual objects or recompile the entire APPS schema with adadmin utility</li>
      <li>If you still have invalid objects, please review steps from [1325394/KB401905] Troubleshooting Guide - Invalid Objects in the E-Business Suite Environment 11i and 12</li>
</ul>',
      p_success_msg            => 'There are no invalid objects for Accounts Receivable (AR) in the database.',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '19'
      );
   l_info.delete;
debug('end add_signature: AR_GEN_AR_INVALIDS');



