   l_info('##STYLE##SEGMENT9_HIGH'):= ',#333333,#FFE864,bold';
   l_info('##STYLE##SEGMENT9_LOW'):= ',#333333,#FFE864,bold';
  add_signature(
      p_sig_repo_id            => '15951',
      p_sig_id                 => 'AR_TRX_VIOLATE_CROSS_VAL_RULE',
      p_sig_sql                => 'select distinct gl_dist.customer_trx_id,
           ''##$$TRXNUMBER$$##'' TRX_NUMBER,
           gl_dist.account_class ACCOUNT_TYPE,
           gl_dist.code_combination_id,
           ##$$SEG_USED$$##,
           rule_line_id,
           id_flex_code,
           id_flex_num,
           flex_validation_rule_name
from fnd_flex_exclude_rule_lines rule,
          gl_code_combinations gl,
          ra_cust_trx_line_gl_dist_all gl_dist
where rule.application_id = 101
and id_flex_code = ''GL#''
and id_flex_num = ##$$FLEX_NUM$$##
and gl_dist.customer_trx_id = ##$$TRXID$$##
and gl_dist.posting_control_id = -3
and     gl_dist.account_set_flag = ''N''
and gl_dist.code_combination_id = gl.code_combination_id
and ##$$SEG_COND$$##
and rule.enabled_flag = ''Y''',
      p_title                  => 'Transaction Uses GL Account which may Violate Cross-Validation Rules',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Transaction uses a GL Account with segment that violates the cross-validation rules.',
      p_solution               => '<ul>
<li>The analyzer has identified usage of GL Accounts with segments that potentially violate cross-validation rules.</li>
<li>Due to cross-validation rule, you may encounter an error similar to that described in [290564/KB715226].</li>
<li>Compare the values in SEGMENT* fields (in red) to the excluded segment range: SEGMENT*_LOW/HIGH fields (highlighted in yellow) to identify which segment may cause issues.</li> 
<li>If you have issues, you can either: Edit your cross-validation rules, or change the GL account associated with this entry so it does not use an account that violates your cross-validation rules.</li>
<li>If you need further assistance, please log a Service Request and upload this analyzer output.</li>
</ul>',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '16'
      );
   l_info.delete;
debug('end add_signature: AR_TRX_VIOLATE_CROSS_VAL_RULE');



