debug('begin add_signature: AR_TRX_PART_PER_RULE_NO_END_DATE');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '16648',
      p_sig_id                 => 'AR_TRX_PART_PER_RULE_NO_END_DATE',
      p_sig_sql                => 'SELECT DISTINCT 
b.customer_trx_id
, c.trx_number
, c.org_id
, b.customer_trx_line_id
, b.accounting_rule_id
, b.rule_start_date
, b.accounting_rule_duration
, b.rule_end_date
FROM
ra_rules a
, ra_customer_trx_lines_all b
, ra_customer_trx_all c
, ra_cust_trx_types_all d
WHERE
a.rule_id = b.accounting_rule_id
AND b.customer_trx_id = c.customer_trx_id
AND b.org_id = c.org_id
AND b.accounting_rule_id IS NOT NULL
AND b.customer_trx_id = ##$$TRXID$$##
AND a.type IN (''PP_DR_ALL'',''PP_DR_PP'')
AND b.rule_end_date IS NULL
AND b.rule_start_date IS NOT NULL
AND c.cust_trx_type_id = d.cust_trx_type_id
AND d.type IN (''DM'',''INV'')',
      p_title                  => 'Transaction with Partial Period Rule with Missing End Date',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'The transaction has a partial period accounting rule on one or more lines which is missing end date on the rule.  This will prevent Revenue Recognition from completing on the transactions.',
      p_solution               => '<ul><li>The analyzer has identified the issue described in [2744628/KB789869].</li>
<li>Please review note for steps to resolve issue.</li></ul>
',
      p_success_msg            => 'There are no transaction lines with partial period accounting rule missing end date.',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '5'
      );
