      p_sig_repo_id            => '19586',
      p_sig_id                 => 'AR_TRX_GL_DIST_ALL_TOTALS_CHECK',
      p_sig_sql                => 'select a.customer_trx_id, a.rec_amt TOTAL_REC_AMOUNT, b.non_rec_amt TOTAL_NON_REC_AMOUNT, 
            a.rec_acctd_amt TOTAL_REC_ACCTD_AMOUNT, b.non_rec_acctd_amt TOTAL_NON_REC_ACCTD_AMOUNT,
decode((a.rec_amt - b.non_rec_amt)+(a.rec_acctd_amt - b.non_rec_acctd_amt),0,''BALANCED'',''OUT OF BALANCE'') STATUS
from (select customer_trx_id, sum(amount) REC_AMT, sum(acctd_amount) REC_ACCTD_AMT from ra_cust_trx_line_gl_dist_all
           where account_set_flag = ''N'' 
           and customer_trx_id = ##$$TRXID$$##
           and account_class = ''REC''
           group by customer_trx_id) a,  
         (select sum(amount) NON_REC_AMT, sum(acctd_amount) NON_REC_ACCTD_AMT from ra_cust_trx_line_gl_dist_all
          where account_set_flag = ''N'' 
          and customer_trx_id = ##$$TRXID$$##
          and account_class <> ''REC'') b
',
      p_title                  => 'Check RA_CUST_TRX_LINE_GL_DIST_ALL Totals',
      p_fail_condition         => '[STATUS] = [OUT OF BALANCE]',
      p_problem_descr          => 'The amounts in RA_CUST_TRX_LINE_GL_DIST_ALL for this transaction are out of balance.',
