   l_info('##STYLE##SEGMENT7_LOW'):= ',#333333,#FFE864,bold';
   l_info('##STYLE##SEGMENT8'):= ',#CC0000,,bold';
   l_info('##STYLE##SEGMENT8_HIGH'):= ',#333333,#FFE864,bold';
   l_info('##STYLE##SEGMENT8_LOW'):= ',#333333,#FFE864,bold';
   l_info('##STYLE##SEGMENT9'):= ',#CC0000,,bold';
   l_info('##STYLE##SEGMENT9_HIGH'):= ',#333333,#FFE864,bold';
   l_info('##STYLE##SEGMENT9_LOW'):= ',#333333,#FFE864,bold';
  add_signature(
      p_sig_repo_id            => '15956',
      p_sig_id                 => 'AR_CMAPP_VIOLATE_CROSS_VAL_RULE',
      p_sig_sql                => 'select distinct ra.customer_trx_id,
           ''##$$TRXNUMBER$$##'' TRX_NUMBER,
           dist.source_type ACCOUNT_TYPE,
           dist.code_combination_id,
           ##$$SEG_USED$$##,
           rule_line_id,
           id_flex_code,
           id_flex_num,
           flex_validation_rule_name
from fnd_flex_exclude_rule_lines rule,
          gl_code_combinations gl,
          ar_receivable_applications_all ra,
          ar_distributions_all dist
where rule.application_id = 101
and id_flex_code = ''GL#''
and id_flex_num = ##$$FLEX_NUM$$##
and ra.customer_trx_id = ##$$TRXID$$##
and ra.posting_control_id = -3
and dist.source_id =  ra.receivable_application_id
and dist.source_table = ''RA''
and dist.code_combination_id = gl.code_combination_id
and ##$$SEG_COND$$##
and rule.enabled_flag = ''Y''',
      p_title                  => 'Credit Memo Application Uses GL Account which Violates Cross-Validation Rules',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Credit memo application uses a GL Account with segment that violates the cross-validation rules.',
      p_solution               => '<ul>
<li>The analyzer has identified usage of GL Accounts with segments that violate cross-validation rules.</li>
<li>Due to the violation of the cross-validation rule, you may encounter an error similar to that described in [781961/KB716136].</li>
<li>Compare the values in SEGMENT* fields (in red) to the excluded segment range: SEGMENT*_LOW/HIGH fields (highlighted in yellow) to identify which segment is causing the failure.</li> 
<li>You have the option to either: Edit your cross-validation rules, or change the GL account associated with this entry so it does not use an account that violates your cross-validation rules.</li>
<li>If you need further assistance, please log a Service Request and upload this analyzer output.</li>
</ul>',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '14'
      );
   l_info.delete;
debug('end add_signature: AR_CMAPP_VIOLATE_CROSS_VAL_RULE');



