debug('begin add_signature: AR_TRX_AR_DIST_APP_TO_OTHERS_TOTAL');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '5195',
      p_sig_id                 => 'AR_TRX_AR_DIST_APP_TO_OTHERS_TOTAL',
      p_sig_sql                => 'SELECT sum(amount_dr) "SUM AMOUNT_DR",
       sum(amount_cr) "SUM AMOUNT_CR",
       sum(acctd_amount_dr) "SUM ACCTD_AMOUNT_DR",
       sum(acctd_amount_cr) "SUM ACCTD_AMOUNT_CR",
       decode(nvl(sum(amount_dr),0)-nvl(sum(amount_cr),0)+
              nvl(sum(acctd_amount_dr),0)-nvl(sum(acctd_amount_cr),0),
              0, ''BALANCED'',''OUT OF BALANCE'') STATUS
