debug('begin add_signature: EBS_FIN_AR_TRX_BR_AR_GL_PERIOD_STATUSES');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '24082',
      p_sig_id                 => 'EBS_FIN_AR_TRX_BR_AR_GL_PERIOD_STATUSES',
      p_sig_sql                => 'SELECT distinct gps.application_id, gps.set_of_books_id, gps.closing_status,
       gps.period_year, gps.period_name, gps.start_date, gps.end_date,
       to_char(gps.last_update_date,''DD-MON-YYYY HH24:MI:SS'') last_update_date
FROM   GL_PERIOD_STATUSES gps,
       AR_SYSTEM_PARAMETERS_ALL sys,
(SELECT distinct gl_date
 FROM   ar_transaction_history_all
 WHERE  customer_trx_id = ##$TRXID$##
 union
 SELECT distinct gl_date
 FROM   ar_receivable_applications_all
 WHERE  customer_trx_id = ##$TRXID$##) atg_date
 WHERE  period_year in (select period_year
 from   gl_period_statuses gps2
 where  atg_date.gl_date between gps2.start_date and gps2.end_date)
 AND NVL(sys.org_id, -99) = (select org_id
                             from   ra_customer_trx_all
                             where  customer_trx_id = ##$TRXID$##)
AND   gps.set_of_books_id in (select distinct a.target_ledger_id ledger_id
from  gl_ledger_relationships a,
      gl_ledgers b
where ledger_id = 1
and   a.primary_ledger_id = b.ledger_id)
AND   gps.application_id = 222
AND   nvl(adjustment_period_flag,''N'') = ''N''
ORDER BY 1 desc, 2 asc, 6 asc',
      p_title                  => 'Period Information for AR',
      p_fail_condition         => 'NRS',
      p_problem_descr          => 'Period statuses for this transaction in GL_PERIOD_STATUSES for AR (application_id = 222).
',
      p_solution               => 'No AR (application_id = 222) data found in GL_PERIOD_STATUSES for this transaction.',
      p_success_msg            => '',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '1'
      );
   l_info.delete;
debug('end add_signature: EBS_FIN_AR_TRX_BR_AR_GL_PERIOD_STATUSES');



