---------------------------------
-- MAIN ENTRY POINT
---------------------------------
PROCEDURE main(
            p_user_name                    IN VARCHAR2    DEFAULT NULL
           ,p_resp_id                      IN NUMBER      DEFAULT NULL
           ,p_customer_trx_id              IN VARCHAR2    DEFAULT NULL
           ,p_includeGL                    IN VARCHAR2    DEFAULT 'Y'
           ,p_apps_check                   IN VARCHAR2    DEFAULT 'N'
           ,p_max_output_rows              IN NUMBER      DEFAULT 5000
           ,p_debug_mode                   IN VARCHAR2    DEFAULT 'Y')

 IS

  l_sql_result VARCHAR2(1);
  l_step       VARCHAR2(5);
  --l_analyzer_end_time   TIMESTAMP;

BEGIN

  l_step := '1';
  initialize_globals;

  -- Workaround for handling debugging before file init
  g_debug_mode := nvl(p_debug_mode, 'Y');
  g_params_string := '';



  l_step := '10';
  initialize_files;

  analyzer_title := 'Receivables Transaction Analyzer';
  analyzer_title := regexp_replace('EBS ' || analyzer_title, '(\S+\s)\1', '\1', 1, 0, 'i');  -- EBSAF-243

  l_step := '15';
   validate_parameters(
     p_user_name                    => upper(p_user_name)
    ,p_resp_id                      => p_resp_id
    ,p_customer_trx_id              => p_customer_trx_id
    ,p_includeGL                    => upper(p_includeGL)
    ,p_apps_check                   => upper(p_apps_check)
    ,p_max_output_rows              => p_max_output_rows
    ,p_debug_mode                   => p_debug_mode
  );


  l_step := '20';
  set_cloud_flag;

  l_step := '23';
  set_snap_days;

  l_step := '25';
  print_page_header;

  l_step := '30';
  print_rep_header(analyzer_title);
  --print_execdetails;
  print_feedback;
  print_parameters;
  print_whatsnew;

  l_step := '40';
  load_signatures;

  l_step := '45';
  create_hyperlink_table;

  l_step := '50';
  initialize_hidden_xml;

  -- Start of Sections and signatures
  l_step := '60';
  debug('begin section: Main Section');
  -- Print the menu of the section screen
  start_main_section;

debug('begin section: TRX_DATA');
start_section('Transaction Data', 'TRX_DATA');
   set_item_result(run_stored_sig('AR_TRX_SUMMARY_INFO'));
   set_item_result(run_stored_sig('AR_TRX_RA_CUSTOMER_TRX_ALL'));
   set_item_result(run_stored_sig('AR_TRX_FND_CURRENCY'));
   set_item_result(run_stored_sig('AR_TRX_GL_DAILY_RATES'));
   set_item_result(run_stored_sig('AR_TRX_AA_DUP_SEGMENTS'));
   set_item_result(run_stored_sig('AR_TRX_INCOMPLETE_TRX'));
   set_item_result(run_stored_sig('AR_TRX_INACTIVE_SALESREP_TRX'));
   set_item_result(run_stored_sig('AR_TRX_RA_BATCH_SOURCES_ALL'));
   IF g_auto_trx = 'Y' THEN
      set_item_result(run_stored_sig('AR_TRX_BATCH_CACHE_SIZE'));
   END IF;
   set_item_result(run_stored_sig('AR_TRX_RA_CUST_TRX_TYPES_ALL'));
   set_item_result(run_stored_sig('AR_TRX_RA_TERMS_B'));
   set_item_result(run_stored_sig('AR_TRX_RA_TERMS_LINES'));
   set_item_result(run_stored_sig('EBS_FIN_AR_TRX_RA_TERMS_LINES_DISCOUNTS'));
   set_item_result(run_stored_sig('EBS_FIN_AR_TRX_BILL_CYCLES_B'));
   set_item_result(run_stored_sig('AR_TRX_RA_CUSTOMER_TRX_LINES_ALL'));
   set_item_result(run_stored_sig('AR_TRX_RA_CUSTOMER_TRX_LINES_ALL_TOTALS'));
   set_item_result(run_stored_sig('EBS_FIN_AR_TRX_INV_ACC_RULES'));
   set_item_result(run_stored_sig('AR_TRX_MTL_SYSTEM_ITEMS_B'));
   set_item_result(run_stored_sig('EBS_FIN_AR_TRX_MEMO_LINE_ID'));
   IF g_type <> 'BR' THEN
      set_item_result(run_stored_sig('AR_TRX_ZX_LINES'));
      set_item_result(run_stored_sig('EBS_FIN_AR_TRX_ZX_LINES_TOTALS'));
      set_item_result(run_stored_sig('AR_TRX_ZX_LINES_DET_FACTORS'));
      set_item_result(run_stored_sig('AR_TRX_ZX_THIRD_PARTY'));
   END IF;
   set_item_result(run_stored_sig('AR_TRX_RA_CUST_TRX_LINE_SALESREPS_ALL'));
   set_item_result(run_stored_sig('AR_TRX_JTF_RS_SALESREPS'));
   IF g_type = 'BR' THEN
      set_item_result(run_stored_sig('AR_TRX_BR_AR_BATCHES_ALL'));
      set_item_result(run_stored_sig('AR_TRX_AR_TRANSACTION_HISTORY_ALL'));
      set_item_result(run_stored_sig('AR_TRX_TH_AR_DISTRIBUTIONS_ALL'));
      set_item_result(run_stored_sig('AR_TRX_BR_AR_GL_ACCOUNTS'));
      set_item_result(run_stored_sig('AR_TRX_VIOLATE_CROSS_VAL_RULE'));
      set_item_result(run_stored_sig('AR_TRX_APP_TO_VIOLATE_CROSS_RULE'));
   END IF;
   IF g_type <> 'BR' THEN
      set_item_result(run_stored_sig('AR_TRX_REV_REC_NOT_RUN'));
      set_item_result(run_stored_sig('AR_TRX_PART_PER_RULE_NO_END_DATE'));
      set_item_result(run_stored_sig('AR_TRX_RA_CUST_TRX_LINE_GL_DIST_ALL'));
      set_item_result(run_stored_sig('AR_TRX_GL_DIST_ALL_TOTALS_CHECK'));
      set_item_result(run_stored_sig('AR_TRX_AR_GL_ACCOUNTS'));
      set_item_result(run_stored_sig('AR_TRX_CST_REVENUE_RECOGNITION_LINES'));
      set_item_result(run_stored_sig('AR_TRX_VIOLATE_CROSS_VAL_RULE'));
      set_item_result(run_stored_sig('AR_TRX_APP_TO_VIOLATE_CROSS_RULE'));
      set_item_result(run_stored_sig('AR_TRX_RA_CM_REQUESTS_ALL'));
      set_item_result(run_stored_sig('AR_TRX_RA_CM_REQUEST_LINES_ALL'));
   END IF;
   IF g_type = 'CM' THEN
      set_item_result(run_stored_sig('AR_CMAPP_VIOLATE_CROSS_VAL_RULE'));
      set_item_result(run_stored_sig('AR_TRX_AR_REC_APP_TO_OTHERS'));
      set_item_result(run_stored_sig('EBS_FIN_AR_TRX_REFUND_AP_INVOICES_ALL'));
      set_item_result(run_stored_sig('AR_TRX_AR_DIST_APP_TO_OTHERS'));
      set_item_result(run_stored_sig('EBS_FIN_AR_TRX_RA_CM_TOTALS'));
      set_item_result(run_stored_sig('AR_TRX_AR_DIST_APP_TO_OTHERS_TOTAL'));
      set_item_result(run_stored_sig('AR_TRX_AR_CREDIT_MEMO_AMOUNTS'));
   END IF;
   set_item_result(run_stored_sig('AR_TRX_APPLICATIONS_TO'));
   set_item_result(run_stored_sig('AR_TRX_APPLICATIONS_TO_TOTALS'));
   set_item_result(run_stored_sig('AR_TRX_AR_DIST_TO_TRX'));
   set_item_result(run_stored_sig('EBS_FIN_AR_TRX_APP_ADJ_GL_ACCOUNTS'));
   set_item_result(run_stored_sig('AR_TRX_AR_ADJUSTMENTS_ALL'));
   set_item_result(run_stored_sig('AR_TRX_AR_ADJUSTMENTS_ALL_TOTALS'));
   set_item_result(run_stored_sig('AR_TRX_ADJUSTMENT_DIST'));
   set_item_result(run_stored_sig('AR_TRX_AR_PAYMENT_SCHEDULES_ALL'));
   IF g_type <> 'BR' THEN
      set_item_result(run_stored_sig('AR_TRX_AR_REVENUE_ADJUSTMENTS_ALL'));
      set_item_result(run_stored_sig('AR_TRX_AR_ACTIVITY_DETAILS'));
      set_item_result(run_stored_sig('AR_TRX_AR_LINE_CONTS_ALL'));
      set_item_result(run_stored_sig('AR_TRX_AR_DEFERRED_LINES_ALL'));
      set_item_result(run_stored_sig('AR_TRX_AR_DEFERRAL_REASONS'));
      set_item_result(run_stored_sig('AR_TRX_RA_RULES'));
      set_item_result(run_stored_sig('AR_TRX_ACCT_RULES'));
      set_item_result(run_stored_sig('AR_TRX_ACCT_RULE_SCHED'));
      set_item_result(run_stored_sig('EBS_FIN_AR_TRX_PARENT_INV_AR_DEFERRED_LINES_ALL'));
      set_item_result(run_stored_sig('EBS_FIN_AR_TRX_PARENT_INV_AR_LINE_CONTS_ALL'));
   END IF;
   set_item_result(run_stored_sig('AR_TRX_AR_DISPUTE_HISTORY1'));
   set_item_result(run_stored_sig('AR_TRX_IBY_TRX_EXT'));
   set_item_result(run_stored_sig('AR_TRX_IBY_TX_EXT'));
   set_item_result(run_stored_sig('AR_TRX_IBY_TX_OPER'));
   set_item_result(run_stored_sig('AR_TRX_IBY_TRX_SUMM'));
   set_item_result(run_stored_sig('EBS_FIN_AR_TRX_CREATION_REQUEST_DETAILS'));
   set_item_result(run_stored_sig('EBS_FIN_AR_TRX_DEPOSIT_TRXS'));
   set_item_result(run_stored_sig('EBS_FIN_AR_TRX_ATTACHMENTS'));
   set_item_result(run_stored_sig('EBS_FIN_AR_TRX_GTA_TRX_HDR'));
end_section;
debug('end section: TRX_DATA');

debug('begin section: XLA_DATA');
start_section('XLA Data', 'XLA_DATA');
   set_item_result(run_stored_sig('AR_TRX_XLA_TRANSACTION_ENTITIES'));
   set_item_result(run_stored_sig('AR_TRX_XLA_EVENTS'));
   set_item_result(run_stored_sig('AR_TRX_XLA_AE_HEADERS'));
   set_item_result(run_stored_sig('AR_TRX_XLA_AE_LINES'));
   set_item_result(run_stored_sig('AR_TRX_SLA_ACCOUNTS'));
   set_item_result(run_stored_sig('AR_TRX_XLA_DISTRIBUTION_LINKS'));
   set_item_result(run_stored_sig('AR_TRX_XLA_ACCOUNTING_ERRORS'));
   set_item_result(run_stored_sig('EBS_FIN_AR_TRX_XLA_CUSTOM_ADRS'));
   set_item_result(run_stored_sig('AR_TRX_DUP_INV_INVALID'));
end_section;
debug('end section: XLA_DATA');

debug('begin section: GL_DATA');
IF g_includeGL = 'Y' THEN
   start_section('GL Data', 'GL_DATA');
      set_item_result(run_stored_sig('AR_TRX_GL_JE_BATCHES'));
      set_item_result(run_stored_sig('AR_TRX_GL_JE_HEADERS'));
      set_item_result(run_stored_sig('AR_TRX_GL_JE_LINES'));
      set_item_result(run_stored_sig('EBS_FIN_AR_TRX_GL_ACCTS'));
      set_item_result(run_stored_sig('AR_TRX_GL_IMPORT_REFERENCES'));
   end_section;
